    /// R465：视频播放器区必须有实底（黑），不能是空白页色 —— 第一帧未到时"像没有视频"。
    func testVideoPlayerHasASolidBackingSurface() throws {
        let scratch = FileManager.default.temporaryDirectory
            .appendingPathComponent("r465-video-surface-\(UUID().uuidString)", isDirectory: true)
        try FileManager.default.createDirectory(at: scratch, withIntermediateDirectories: true)
        defer { try? FileManager.default.removeItem(at: scratch) }

        for appearance in [NSAppearance.Name.aqua, .darkAqua] {
            let tag = appearance == .darkAqua ? "dark" : "light"
            guard let fixture = fixtures(appearance: appearance)
                .first(where: { $0.name == "detail-file-video-controls" }) else {
                return XCTFail("\(tag)：找不到 `detail-file-video-controls` ⇒ 这条判据没有对象")
            }
            let file = scratch.appendingPathComponent("video-controls-\(tag).png")
            _ = try render(fixture, appearance: appearance, to: file)
            guard let data = try? Data(contentsOf: file),
                  let rep = NSBitmapImageRep(data: data), let base = rep.bitmapData else {
                XCTFail("\(tag)：video-controls 帧读不回字节 ⇒ 这条判据没有对象")
                continue
            }
            let scale = Double(rep.pixelsWide) / 600.0
            let height = rep.pixelsHigh, bytesPerRow = rep.bytesPerRow
            let spp = rep.samplesPerPixel
            let alphaFirst = rep.bitmapFormat.contains(.alphaFirst)
            let rOff = alphaFirst ? 1 : 0
            func luma(_ x: Int, _ y: Int) -> Double {
                let o = y * bytesPerRow + x * spp
                return 0.299 * Double(base[o + rOff]) + 0.587 * Double(base[o + rOff + 1])
                    + 0.114 * Double(base[o + rOff + 2])
            }
            func mean(x0Pt: Double, x1Pt: Double, y0Pt: Double, y1Pt: Double) -> Double {
                let x0 = Int((x0Pt * scale).rounded()), x1 = Int((x1Pt * scale).rounded())
                let y0 = Int((y0Pt * scale).rounded()), y1 = min(height, Int((y1Pt * scale).rounded()))
                var sum = 0.0, count = 0
                for y in y0..<y1 { for x in x0..<x1 { sum += luma(x, y); count += 1 } }
                return count > 0 ? sum / Double(count) : -1
            }
            // 播放器区（x 100..500、y 120..360）与页底（x 4..16，播放器从 x=20 起）。
            let player = mean(x0Pt: 100, x1Pt: 500, y0Pt: 120, y1Pt: 360)
            let page = mean(x0Pt: 4, x1Pt: 16, y0Pt: 120, y1Pt: 160)
            let delta = page - player
            emit("VIDEO_SURFACE \(tag) 播放器=\(String(format: "%.0f", player))"
                 + " 页底=\(String(format: "%.0f", page)) 差=\(String(format: "%.0f", delta))")
            XCTAssertGreaterThanOrEqual(delta, 20.0,
                                        "\(tag)：播放器区只比页底暗 \(String(format: "%.0f", delta))"
                                        + " ⇒ 第一帧前是一块空白页色，像没有视频")
        }
    }

    /// R466：视频播放器的右缘应和控件胶囊对齐（播放器留 20pt、控件留 80pt ⇒ 差 60pt；
    /// 播放器还伸到右下角浮层下面）。量播放器顶部黑带的右缘与控件行最右墨的差。
    func testVideoPlayerAlignsWithItsControls() throws {
        let scratch = FileManager.default.temporaryDirectory
            .appendingPathComponent("r466-video-align-\(UUID().uuidString)", isDirectory: true)
        try FileManager.default.createDirectory(at: scratch, withIntermediateDirectories: true)
        defer { try? FileManager.default.removeItem(at: scratch) }

        for appearance in [NSAppearance.Name.aqua, .darkAqua] {
            let tag = appearance == .darkAqua ? "dark" : "light"
            guard let fixture = fixtures(appearance: appearance)
                .first(where: { $0.name == "detail-file-video-controls" }) else {
                return XCTFail("\(tag)：找不到 `detail-file-video-controls` ⇒ 这条判据没有对象")
            }
            let file = scratch.appendingPathComponent("video-align-\(tag).png")
            _ = try render(fixture, appearance: appearance, to: file)
            guard let data = try? Data(contentsOf: file),
                  let rep = NSBitmapImageRep(data: data), let base = rep.bitmapData else {
                XCTFail("\(tag)：video-controls 帧读不回字节 ⇒ 这条判据没有对象")
                continue
            }
            let scale = Double(rep.pixelsWide) / 600.0
            let height = rep.pixelsHigh, bytesPerRow = rep.bytesPerRow
            let spp = rep.samplesPerPixel
            let alphaFirst = rep.bitmapFormat.contains(.alphaFirst)
            let rOff = alphaFirst ? 1 : 0
            func luma(_ x: Int, _ y: Int) -> Double {
                let o = y * bytesPerRow + x * spp
                return 0.299 * Double(base[o + rOff]) + 0.587 * Double(base[o + rOff + 1])
                    + 0.114 * Double(base[o + rOff + 2])
            }
            // 播放器顶部黑带（y 120..200，浮层从 y 240pt 起）的最右黑列。
            var playerRight = -1
            for y in Int((120.0 * scale))..<min(height, Int((200.0 * scale))) {
                for x in 0..<rep.pixelsWide where luma(x, y) <= 10 {
                    playerRight = max(playerRight, x)
                }
            }
            // 控件行（y 395..430）在 x<535（浮层从 540 起）的最右墨列。
            let muteInk: (Double) -> Bool = appearance == .darkAqua ? { $0 >= 90 } : { $0 <= 190 }
            var controlsRight = -1
            for y in Int((395.0 * scale))..<min(height, Int((430.0 * scale))) {
                for x in 0..<min(rep.pixelsWide, Int((535.0 * scale))) where muteInk(luma(x, y)) {
                    controlsRight = max(controlsRight, x)
                }
            }
            guard playerRight >= 0, controlsRight >= 0 else {
                XCTFail("\(tag)：读不到播放器黑带或控件墨 ⇒ 判据没有对象")
                continue
            }
            let gap = Double(playerRight - controlsRight) / scale
            emit("VIDEO_ALIGN \(tag) 播放器右=\(String(format: "%.1f", Double(playerRight) / scale))pt"
                 + " 控件右=\(String(format: "%.1f", Double(controlsRight) / scale))pt 差=\(String(format: "%.1f", gap))pt")
            XCTAssertLessThanOrEqual(gap, 30.0,
                                     "\(tag)：播放器右缘比控件右缘多出 \(String(format: "%.1f", gap))pt"
                                     + " ⇒ 播放器和控件不齐、还伸到浮层下面")
        }
    }

    /// R467：视频进度滑杆的轨道必须在胶囊底上看得见（系统轨道近页色，seek 范围像没有）。
    /// 量控件行里滑杆那一段（x 120..410、y 400..420）对胶囊底的**最大亮度偏离**；
    /// 旧系统轨道约 20，新加的自绘轨道 ≥60（≈3:1）。
    func testVideoSeekTrackIsVisible() throws {
        let scratch = FileManager.default.temporaryDirectory
            .appendingPathComponent("r467-seek-track-\(UUID().uuidString)", isDirectory: true)
        try FileManager.default.createDirectory(at: scratch, withIntermediateDirectories: true)
        defer { try? FileManager.default.removeItem(at: scratch) }

        for appearance in [NSAppearance.Name.aqua, .darkAqua] {
            let tag = appearance == .darkAqua ? "dark" : "light"
            guard let fixture = fixtures(appearance: appearance)
                .first(where: { $0.name == "detail-file-video-controls" }) else {
                return XCTFail("\(tag)：找不到 `detail-file-video-controls` ⇒ 这条判据没有对象")
            }
            let file = scratch.appendingPathComponent("seek-\(tag).png")
            _ = try render(fixture, appearance: appearance, to: file)
            guard let data = try? Data(contentsOf: file),
                  let rep = NSBitmapImageRep(data: data), let base = rep.bitmapData else {
                XCTFail("\(tag)：video-controls 帧读不回字节 ⇒ 这条判据没有对象")
                continue
            }
            let scale = Double(rep.pixelsWide) / 600.0
            let height = rep.pixelsHigh, bytesPerRow = rep.bytesPerRow
            let spp = rep.samplesPerPixel
            let alphaFirst = rep.bitmapFormat.contains(.alphaFirst)
            let rOff = alphaFirst ? 1 : 0
            func luma(_ x: Int, _ y: Int) -> Double {
                let o = y * bytesPerRow + x * spp
                return 0.299 * Double(base[o + rOff]) + 0.587 * Double(base[o + rOff + 1])
                    + 0.114 * Double(base[o + rOff + 2])
            }
            // thumb 停在 0 位（x≈112..130），采样从 160 起，只量轨道段。
            let x0 = Int((160.0 * scale).rounded()), x1 = Int((410.0 * scale).rounded())
            let y0 = Int((400.0 * scale).rounded()), y1 = min(height, Int((420.0 * scale).rounded()))
            var histogram: [Int: Int] = [:]
            for y in y0..<y1 { for x in x0..<x1 { histogram[Int(luma(x, y)) / 4, default: 0] += 1 } }
            let mode = Double((histogram.max { $0.value < $1.value }?.key ?? 0) * 4 + 2)
            var maxDeviation = 0.0
            for y in y0..<y1 {
                for x in x0..<x1 { maxDeviation = max(maxDeviation, abs(luma(x, y) - mode)) }
            }
            emit("VIDEO_SEEK \(tag) 底=\(String(format: "%.0f", mode)) 最大偏离=\(String(format: "%.0f", maxDeviation))")
            XCTAssertGreaterThanOrEqual(maxDeviation, 60.0,
                                        "\(tag)：滑杆轨道对胶囊底只偏离 \(String(format: "%.0f", maxDeviation))"
                                        + "（<60）⇒ seek 范围几乎看不见")
        }
    }

    func testCodeBlocksShowLineNumbers() throws {
        let scratch = FileManager.default.temporaryDirectory
            .appendingPathComponent("r441-code-gutter-\(UUID().uuidString)", isDirectory: true)
        try FileManager.default.createDirectory(at: scratch, withIntermediateDirectories: true)
        defer { try? FileManager.default.removeItem(at: scratch) }

        let expectedLines = 3

        for appearance in [NSAppearance.Name.aqua, .darkAqua] {
            let tag = appearance == .darkAqua ? "dark" : "light"
            guard let fixture = fixtures(appearance: appearance)
                .first(where: { $0.name == "detail-code" }) else {
                return XCTFail("\(tag)：找不到 `detail-code` ⇒ 这条判据没有对象")
            }
            let file = scratch.appendingPathComponent("detail-code-\(tag).png")
            _ = try render(fixture, appearance: appearance, to: file)
            guard let data = try? Data(contentsOf: file),
                  let rep = NSBitmapImageRep(data: data), let base = rep.bitmapData else {
                XCTFail("\(tag)：`detail-code` 读不回字节 ⇒ 这条判据没有对象")
                return
            }
            let scale = Double(rep.pixelsWide) / 720.0
            let height = rep.pixelsHigh, bytesPerRow = rep.bytesPerRow
            func luma(_ x: Int, _ y: Int) -> Double {
                let o = y * bytesPerRow + x * 4
                return 0.299 * Double(base[o]) + 0.587 * Double(base[o + 1]) + 0.114 * Double(base[o + 2])
            }
            let isInk: (Double) -> Bool = appearance == .darkAqua ? { $0 >= 90 } : { $0 <= 190 }

            /// 代码块的三行正文就是内容区里最后三条墨带（夹具只有 h1 + 三行代码）。
            /// 不用灰底定位：最后一行没有换行符，`.backgroundColor` 只涂到最后一个字形，
            /// 600..650pt 的采样列在第三行上是白的（R441 第二版实测）——
            /// 拿灰底当对象会把第三行漏掉，行号带就只剩 2 个。
            let textX0 = Int((20.0 * scale).rounded())
            let textX1 = Int((300.0 * scale).rounded())
            var textBands: [(top: Int, bottom: Int)] = []
            var top = -1
            for y in Int((60.0 * scale))..<min(height, Int((520.0 * scale))) {
                var has = false
                for x in textX0..<textX1 where isInk(luma(x, y)) {
                    has = true
                    break
                }
                if has && top < 0 { top = y }
                if !has && top >= 0 { textBands.append((top, y - 1)); top = -1 }
            }
            if top >= 0 { textBands.append((top, min(height, Int((520.0 * scale))) - 1)) }
            let codeBands = Array(textBands.suffix(expectedLines))
            guard codeBands.count == expectedLines else {
                emit("CODE_LINE_NUMBERS_NOT_RUN=runner-detail-frame-plain \(tag) 正文带=\(textBands.count)"
                     + " ⇒ 找不到三行代码，判据没有对象")
                continue
            }
            let codeTop = codeBands.first!.top
            let codeBottom = codeBands.last!.bottom
            // 灰底覆盖：在正文/浮层都够不着的 600..650pt 采样，代码块的三行都应被灰底覆盖。
            // 旧形状最后一行只涂到最后一个字 ⇒ 这一列在第三行上是白的（覆盖率 ~2/3）。
            let tintX0 = Int((600.0 * scale).rounded())
            let tintX1 = Int((650.0 * scale).rounded())
            func tintMean(_ y: Int) -> Double {
                var sum = 0.0
                for x in tintX0..<tintX1 { sum += luma(x, y) }
                return sum / Double(max(tintX1 - tintX0, 1))
            }
            let paneTop = Int((60.0 * scale).rounded())
            let paneBottom = Int((68.0 * scale).rounded())
            let pane = (paneTop..<paneBottom).map(tintMean).reduce(0, +)
                / Double(max(paneBottom - paneTop, 1))
            var tintedRows = 0
            for y in codeTop...codeBottom where abs(tintMean(y) - pane) >= 6 {
                tintedRows += 1
            }
            let coverage = Double(tintedRows) / Double(codeBottom - codeTop + 1)

            func inkBandCount(x0Pt: Double, x1Pt: Double) -> Int {
                let x0 = Int((x0Pt * scale).rounded())
                let x1 = Int((x1Pt * scale).rounded())
                var count = 0
                var inBand = false
                for y in codeTop...codeBottom {
                    var has = false
                    for x in x0..<x1 where isInk(luma(x, y)) {
                        has = true
                        break
                    }
                    if has && !inBand { count += 1; inBand = true }
                    if !has { inBand = false }
                }
                return count
            }
            let numberBands = inkBandCount(x0Pt: 2, x1Pt: 18)
            var codeTextLeft = Double.nan
            search: for x in Int((19.0 * scale).rounded())..<Int((400.0 * scale).rounded()) {
                for y in codeTop...codeBottom where isInk(luma(x, y)) {
                    codeTextLeft = Double(x) / scale
                    break search
                }
            }
            emit("CODE_LINE_NUMBERS \(tag) 代码带=\(String(format: "%.1f", Double(codeBottom - codeTop + 1) / scale))pt"
                 + " 行号带=\(numberBands) 正文左=\(String(format: "%.1f", codeTextLeft))pt"
                 + " 带覆盖=\(String(format: "%.0f", coverage * 100))%")
            XCTAssertEqual(numberBands, expectedLines,
                           "\(tag)：行号带 \(numberBands) 个（应为 \(expectedLines)）⇒ 行号没画或没按行画")
            XCTAssertGreaterThanOrEqual(codeTextLeft, 19.0,
                                        "\(tag)：正文左沿跑到 \(codeTextLeft)pt ⇒ 行号把正文挤走了")
            XCTAssertLessThanOrEqual(codeTextLeft, 22.0,
                                     "\(tag)：正文左沿跑到 \(codeTextLeft)pt ⇒ 行号槽动了正文")
            XCTAssertGreaterThanOrEqual(coverage, 0.85,
                                        "\(tag)：灰底只覆盖了三行的 \(Int(coverage * 100))%"
                                        + " ⇒ 最后一行只涂到字尾（锯齿底）")
        }
    }

    /// R446：代码块语言标签。
    ///
    /// 两臂是**逐字相同**的三行代码，只差围栏信息串（`swift` vs 空）：
    /// ① 有语言那一帧，第一行代码带右区应有标签墨（地板 12·scale²，1x/2x 各自成立）；
    ///    空语言那一帧同区必须为 0 —— 右区的墨只可能来自标签；
    /// ② 两臂的代码正文左沿与行号带数必须相同：标签没挤动代码、也没顶掉行号槽；
    /// ③ 第二行右区两臂都为 0：标签只画第一行，不是通栏水印。
    /// 标签不进文本存储，所以这条判据只看帧（复制出来的代码不带标签）。
    func testCodeBlocksShowTheirLanguage() throws {
        let scratch = FileManager.default.temporaryDirectory
            .appendingPathComponent("r446-code-language-\(UUID().uuidString)", isDirectory: true)
        try FileManager.default.createDirectory(at: scratch, withIntermediateDirectories: true)
        defer { try? FileManager.default.removeItem(at: scratch) }

        enum FrameError: Error { case unreadable }

        for appearance in [NSAppearance.Name.aqua, .darkAqua] {
            let tag = appearance == .darkAqua ? "dark" : "light"
            guard let taggedFixture = fixtures(appearance: appearance)
                .first(where: { $0.name == "detail-code" }),
                let plainFixture = fixtures(appearance: appearance)
                .first(where: { $0.name == "detail-code-plain" }) else {
                return XCTFail("\(tag)：找不到 `detail-code` / `detail-code-plain` ⇒ 这条判据没有对象")
            }

            func load(_ fixture: Fixture) throws -> (rep: NSBitmapImageRep,
                                                     base: UnsafeMutablePointer<UInt8>,
                                                     scale: Double) {
                let file = scratch.appendingPathComponent("\(fixture.name)-\(tag).png")
                _ = try render(fixture, appearance: appearance, to: file)
                guard let data = try? Data(contentsOf: file),
                      let rep = NSBitmapImageRep(data: data),
                      let base = rep.bitmapData else {
                    XCTFail("\(tag)：`\(fixture.name)` 读不回字节 ⇒ 这条判据没有对象")
                    throw FrameError.unreadable
                }
                return (rep, base, Double(rep.pixelsWide) / 720.0)
            }

            let tagged = try load(taggedFixture)
            let plain = try load(plainFixture)
            let scale = tagged.scale

            func luma(_ frame: (rep: NSBitmapImageRep,
                                base: UnsafeMutablePointer<UInt8>,
                                scale: Double), _ x: Int, _ y: Int) -> Double {
                let o = y * frame.rep.bytesPerRow + x * 4
                return 0.299 * Double(frame.base[o]) + 0.587 * Double(frame.base[o + 1])
                    + 0.114 * Double(frame.base[o + 2])
            }
            let isInk: (Double) -> Bool = appearance == .darkAqua ? { $0 >= 90 } : { $0 <= 190 }

            /// 代码块的三行正文 = 内容区最后三条墨带（夹具只有 h1 + 三行代码），
            /// 与 `testCodeBlocksShowLineNumbers` 取同一批带。
            func textBands(_ frame: (rep: NSBitmapImageRep,
                                     base: UnsafeMutablePointer<UInt8>,
                                     scale: Double)) -> [(top: Int, bottom: Int)] {
                let textX0 = Int((20.0 * scale).rounded())
                let textX1 = Int((300.0 * scale).rounded())
                var bands: [(top: Int, bottom: Int)] = []
                var top = -1
                for y in Int((60.0 * scale))..<min(frame.rep.pixelsHigh, Int((520.0 * scale))) {
                    var has = false
                    for x in textX0..<textX1 where isInk(luma(frame, x, y)) {
                        has = true
                        break
                    }
                    if has && top < 0 { top = y }
                    if !has && top >= 0 { bands.append((top, y - 1)); top = -1 }
                }
                if top >= 0 {
                    bands.append((top, min(frame.rep.pixelsHigh, Int((520.0 * scale))) - 1))
                }
                return bands
            }

            func inkBandCount(_ frame: (rep: NSBitmapImageRep,
                                       base: UnsafeMutablePointer<UInt8>,
                                       scale: Double),
                              codeTop: Int, codeBottom: Int, x0Pt: Double, x1Pt: Double) -> Int {
                let x0 = Int((x0Pt * scale).rounded())
                let x1 = Int((x1Pt * scale).rounded())
                var count = 0
                var inBand = false
                for y in codeTop...codeBottom {
                    var has = false
                    for x in x0..<x1 where isInk(luma(frame, x, y)) {
                        has = true
                        break
                    }
                    if has && !inBand { count += 1; inBand = true }
                    if !has { inBand = false }
                }
                return count
            }

            func codeTextLeft(_ frame: (rep: NSBitmapImageRep,
                                        base: UnsafeMutablePointer<UInt8>,
                                        scale: Double),
                              codeTop: Int, codeBottom: Int) -> Double {
                for x in Int((19.0 * scale).rounded())..<Int((400.0 * scale).rounded()) {
                    for y in codeTop...codeBottom where isInk(luma(frame, x, y)) {
                        return Double(x) / scale
                    }
                }
                return .nan
            }

            let taggedBands = textBands(tagged)
            let plainBands = textBands(plain)
            let taggedCode = Array(taggedBands.suffix(3))
            let plainCode = Array(plainBands.suffix(3))
            guard taggedCode.count == 3, plainCode.count == 3 else {
                emit("CODE_LANGUAGE_NOT_RUN=runner-detail-frame-plain \(tag)"
                     + " 有语言带=\(taggedBands.count) 无语言带=\(plainBands.count)"
                     + " ⇒ 找不到三行代码，判据没有对象")
                continue
            }

            /// 代码带右沿从**第二行**扫描：标签在第一行，第二行的右区只有灰底，
            /// 扫到的右沿才是底色本身的右沿，不会被标签墨拉短。
            let paneTop = Int((60.0 * scale).rounded())
            let paneBottom = Int((68.0 * scale).rounded())
            func paneMean(_ frame: (rep: NSBitmapImageRep,
                                    base: UnsafeMutablePointer<UInt8>,
                                    scale: Double)) -> Double {
                var sum = 0.0
                var n = 0
                for y in paneTop..<paneBottom {
                    for x in Int((600.0 * scale).rounded())..<Int((650.0 * scale).rounded()) {
                        sum += luma(frame, x, y)
                        n += 1
                    }
                }
                return sum / Double(max(n, 1))
            }
            let secondBandMid = (plainCode[1].top + plainCode[1].bottom) / 2
            let pane = paneMean(plain)
            var bandRight = Int((650.0 * scale).rounded())
            for x in Int((300.0 * scale).rounded())..<min(plain.rep.pixelsWide, Int((710.0 * scale).rounded())) {
                if abs(luma(plain, x, secondBandMid) - pane) >= 6 { bandRight = x }
            }
            let regionX0 = max(Int((300.0 * scale).rounded()), bandRight - Int((140.0 * scale).rounded()))
            let regionX1 = max(regionX0 + 1, bandRight - Int((4.0 * scale).rounded()))

            func inkMass(_ frame: (rep: NSBitmapImageRep,
                                   base: UnsafeMutablePointer<UInt8>,
                                   scale: Double),
                         band: (top: Int, bottom: Int)) -> Int {
                let y0 = max(0, band.top - Int((2.0 * scale).rounded()))
                let y1 = min(frame.rep.pixelsHigh - 1, band.bottom + Int((2.0 * scale).rounded()))
                var count = 0
                for y in y0...y1 {
                    for x in regionX0..<regionX1 where isInk(luma(frame, x, y)) {
                        count += 1
                    }
                }
                return count
            }

            let taggedInk = inkMass(tagged, band: taggedCode[0])
            let plainInk = inkMass(plain, band: plainCode[0])
            let taggedSecondInk = inkMass(tagged, band: taggedCode[1])
            let plainSecondInk = inkMass(plain, band: plainCode[1])
            let taggedNumbers = inkBandCount(tagged, codeTop: taggedCode[0].top,
                                             codeBottom: taggedCode[2].bottom, x0Pt: 2, x1Pt: 18)
            let plainNumbers = inkBandCount(plain, codeTop: plainCode[0].top,
                                            codeBottom: plainCode[2].bottom, x0Pt: 2, x1Pt: 18)
            let taggedLeft = codeTextLeft(tagged, codeTop: taggedCode[0].top,
                                          codeBottom: taggedCode[2].bottom)
            let plainLeft = codeTextLeft(plain, codeTop: plainCode[0].top,
                                         codeBottom: plainCode[2].bottom)
            let inkFloor = Int((12.0 * scale * scale).rounded())

            emit("CODE_LANGUAGE \(tag) 右区="
                 + String(format: "%.0f..%.0fpt", Double(regionX0) / scale, Double(regionX1) / scale)
                 + " 标签墨=\(taggedInk) 无语言臂=\(plainInk) 第二行=\(taggedSecondInk)/\(plainSecondInk)"
                 + " 行号带=\(taggedNumbers)/\(plainNumbers)"
                 + " 正文左=\(String(format: "%.1f", taggedLeft))/\(String(format: "%.1f", plainLeft))pt")

            XCTAssertGreaterThanOrEqual(taggedInk, inkFloor,
                                        "\(tag)：语言标签在右区只有 \(taggedInk) 个墨点（地板 \(inkFloor)）"
                                        + " ⇒ 代码块没有把围栏里的语言画出来")
            XCTAssertEqual(plainInk, 0,
                           "\(tag)：无语言臂右区也有 \(plainInk) 个墨点 ⇒ 右区的墨不全来自标签，"
                           + "这条判据量错了对象")
            XCTAssertEqual(taggedSecondInk, 0,
                           "\(tag)：第二行右区有 \(taggedSecondInk) 个墨点 ⇒ 标签画成了通栏/多行")
            XCTAssertEqual(plainSecondInk, 0,
                           "\(tag)：无语言臂第二行右区有 \(plainSecondInk) 个墨点")
            XCTAssertEqual(taggedNumbers, 3, "\(tag)：有语言臂的行号带 \(taggedNumbers) 个（应为 3）⇒ 标签挤掉了行号")
            XCTAssertEqual(plainNumbers, 3, "\(tag)：无语言臂的行号带 \(plainNumbers) 个（应为 3）")
            XCTAssertEqual(taggedLeft, plainLeft, accuracy: 0.5,
                           "\(tag)：两臂正文左沿 \(taggedLeft)/\(plainLeft)pt 不同 ⇒ 标签挪了代码")
        }
    }

    /// R447：Markdown 主题分隔线必须画成**通栏一条线**，而不是 24 个 `─` 字符。
    ///
    /// 判据只看帧：在正文区（避开详情头部那条分隔线）逐行找最长的连续墨行。
    /// 新形状：一条 ≥450pt、厚度 ≤4pt 的长线，且正文区里只有这一条；
    /// 旧形状（24 个 `─`）：每一段只有几 pt，拼不出 450pt，墨带高也是一行字（>4pt）。
    /// 复制语义那一半在 `ThematicBreakRuleTests`：属性串里不许再出现 `─`。
    func testThematicBreaksAreDrawnAsALine() throws {
        let scratch = FileManager.default.temporaryDirectory
            .appendingPathComponent("r447-rule-\(UUID().uuidString)", isDirectory: true)
        try FileManager.default.createDirectory(at: scratch, withIntermediateDirectories: true)
        defer { try? FileManager.default.removeItem(at: scratch) }

        for appearance in [NSAppearance.Name.aqua, .darkAqua] {
            let tag = appearance == .darkAqua ? "dark" : "light"
            guard let fixture = fixtures(appearance: appearance)
                .first(where: { $0.name == "detail-rule" }) else {
                return XCTFail("\(tag)：找不到 `detail-rule` ⇒ 这条判据没有对象")
            }
            let file = scratch.appendingPathComponent("detail-rule-\(tag).png")
            _ = try render(fixture, appearance: appearance, to: file)
            guard let data = try? Data(contentsOf: file),
                  let rep = NSBitmapImageRep(data: data), let base = rep.bitmapData else {
                XCTFail("\(tag)：`detail-rule` 读不回字节 ⇒ 这条判据没有对象")
                return
            }
            let scale = Double(rep.pixelsWide) / 720.0
            let height = rep.pixelsHigh, bytesPerRow = rep.bytesPerRow
            func luma(_ x: Int, _ y: Int) -> Double {
                let o = y * bytesPerRow + x * 4
                return 0.299 * Double(base[o]) + 0.587 * Double(base[o + 1]) + 0.114 * Double(base[o + 2])
            }
            // 用"离背景足够远"而不是绝对墨阈值：1pt 线在 1x 可能被摊到相邻两行，
            // 半覆盖那一行读不到纯色的深，但它仍然明显比窗口底色深/亮。
            let isRuleInk: (Double) -> Bool = appearance == .darkAqua ? { $0 >= 70 } : { $0 <= 210 }
            let x0 = Int((20.0 * scale).rounded())
            let x1 = Int((700.0 * scale).rounded())
            let y0 = Int((70.0 * scale).rounded())
            let y1 = min(height, Int((500.0 * scale).rounded()))

            func longestRun(y: Int) -> Int {
                var best = 0
                var current = 0
                for x in x0..<x1 {
                    if isRuleInk(luma(x, y)) {
                        current += 1
                        best = max(best, current)
                    } else {
                        current = 0
                    }
                }
                return best
            }

            let floorPx = 450.0 * scale
            var bands: [(top: Int, bottom: Int, run: Int)] = []
            var top = -1
            var runInBand = 0
            for y in y0..<y1 {
                let run = longestRun(y: y)
                let isLong = Double(run) >= floorPx
                if isLong {
                    if top < 0 { top = y }
                    runInBand = max(runInBand, run)
                } else if top >= 0 {
                    bands.append((top, y - 1, runInBand))
                    top = -1
                    runInBand = 0
                }
            }
            if top >= 0 { bands.append((top, y1 - 1, runInBand)) }

            let longest = bands.map { $0.run }.max() ?? 0
            let longestPt = Double(longest) / scale
            let bandHeightPt = bands.first.map { Double($0.bottom - $0.top + 1) / scale } ?? 0
            emit("THEMATIC_RULE \(tag) 长线=\(String(format: "%.1f", longestPt))pt"
                 + " 带高=\(String(format: "%.1f", bandHeightPt))pt 带数=\(bands.count)")

            XCTAssertEqual(bands.count, 1,
                           "\(tag)：正文区里读到 \(bands.count) 条通栏长线（应为 1）"
                           + " ⇒ 多出来的那条是谁？这条判据量错了对象")
            guard let band = bands.first else { continue }
            XCTAssertGreaterThanOrEqual(longestPt, 450.0,
                                        "\(tag)：分隔线只有 \(longestPt)pt 长"
                                        + " ⇒ 它还是按字数画的字符线，不是通栏线")
            let thickness = Double(band.bottom - band.top + 1) / scale
            XCTAssertLessThanOrEqual(thickness, 4.0,
                                     "\(tag)：分隔线厚 \(thickness)pt（应 ≤4pt）"
                                     + " ⇒ 读到的是字高不是线厚")
        }
    }

    /// R448：Markdown 表格**体行之间**必须有发丝分隔线。
    ///
    /// 正臂 `detail-table-rows`（表头 + 四行体行）→ 体行之间 **3** 条；
    /// 负臂 `detail-table`（表头 + 一行体行）→ **0** 条（表头之后与最后一行之后都不画）。
    /// 判据只看帧：在表格行带范围里找"长于表宽 80%"的连续墨行；
    /// 线必须 ① 正臂恰好 3 条 ② 厚 ≤2pt ③ 起止与表格文字外接宽度对齐（±6pt）。
    func testMarkdownTablesSeparateTheirBodyRows() throws {
        let scratch = FileManager.default.temporaryDirectory
            .appendingPathComponent("r448-table-rows-\(UUID().uuidString)", isDirectory: true)
        try FileManager.default.createDirectory(at: scratch, withIntermediateDirectories: true)
        defer { try? FileManager.default.removeItem(at: scratch) }

        enum FrameError: Error { case unreadable }

        for appearance in [NSAppearance.Name.aqua, .darkAqua] {
            let tag = appearance == .darkAqua ? "dark" : "light"

            func load(_ name: String) throws -> (rep: NSBitmapImageRep,
                                                 base: UnsafeMutablePointer<UInt8>,
                                                 scale: Double) {
                guard let fixture = fixtures(appearance: appearance)
                    .first(where: { $0.name == name }) else {
                    XCTFail("\(tag)：找不到 `\(name)` ⇒ 这条判据没有对象")
                    throw FrameError.unreadable
                }
                let file = scratch.appendingPathComponent("\(name)-\(tag).png")
                _ = try render(fixture, appearance: appearance, to: file)
                guard let data = try? Data(contentsOf: file),
                      let rep = NSBitmapImageRep(data: data),
                      let base = rep.bitmapData else {
                    XCTFail("\(tag)：`\(name)` 读不回字节 ⇒ 这条判据没有对象")
                    throw FrameError.unreadable
                }
                return (rep, base, Double(rep.pixelsWide) / 720.0)
            }

            let rowsFrame = try load("detail-table-rows")
            let oneFrame = try load("detail-table")
            let scale = rowsFrame.scale

            func luma(_ frame: (rep: NSBitmapImageRep,
                                base: UnsafeMutablePointer<UInt8>,
                                scale: Double), _ x: Int, _ y: Int) -> Double {
                let o = y * frame.rep.bytesPerRow + x * 4
                return 0.299 * Double(frame.base[o]) + 0.587 * Double(frame.base[o + 1])
                    + 0.114 * Double(frame.base[o + 2])
            }
            let isInk: (Double) -> Bool = appearance == .darkAqua ? { $0 >= 90 } : { $0 <= 190 }
            let isLineInk: (Double) -> Bool = appearance == .darkAqua ? { $0 >= 70 } : { $0 <= 210 }
            let textX0 = Int((20.0 * scale).rounded())
            let textX1 = Int((300.0 * scale).rounded())

            /// 文本行带（高度 ≥5pt）：分隔线自己只有 1pt，不能混进行带里。
            func textBands(_ frame: (rep: NSBitmapImageRep,
                                     base: UnsafeMutablePointer<UInt8>,
                                     scale: Double)) -> [(top: Int, bottom: Int)] {
                var bands: [(top: Int, bottom: Int)] = []
                var top = -1
                for y in Int((60.0 * scale))..<min(frame.rep.pixelsHigh, Int((520.0 * scale))) {
                    var has = false
                    for x in textX0..<textX1 where isInk(luma(frame, x, y)) {
                        has = true
                        break
                    }
                    if has && top < 0 { top = y }
                    if !has && top >= 0 {
                        if y - top >= Int((5.0 * scale).rounded()) { bands.append((top, y - 1)) }
                        top = -1
                    }
                }
                if top >= 0,
                   min(frame.rep.pixelsHigh, Int((520.0 * scale))) - top >= Int((5.0 * scale).rounded()) {
                    bands.append((top, min(frame.rep.pixelsHigh, Int((520.0 * scale))) - 1))
                }
                return bands
            }

            let rowsText = Array(textBands(rowsFrame).suffix(5))
            let oneText = Array(textBands(oneFrame).suffix(2))
            guard rowsText.count == 5, oneText.count == 2 else {
                emit("TABLE_ROW_LINES_NOT_RUN=runner-detail-frame-plain \(tag)"
                     + " 正臂行带=\(textBands(rowsFrame).count) 负臂行带=\(textBands(oneFrame).count)"
                     + " ⇒ 找不到表格行，判据没有对象")
                continue
            }

            func span(_ frame: (rep: NSBitmapImageRep,
                                base: UnsafeMutablePointer<UInt8>,
                                scale: Double),
                      bands: [(top: Int, bottom: Int)]) -> (left: Int, right: Int) {
                var left = Int.max, right = -1
                for band in bands {
                    for y in band.top...band.bottom {
                        for x in textX0..<textX1 where isInk(luma(frame, x, y)) {
                            left = min(left, x)
                            right = max(right, x)
                        }
                    }
                }
                return (left, right)
            }

            /// 表格纵向范围里，长于表宽 80% 的连续墨行 = 分隔线。
            func separatorBands(_ frame: (rep: NSBitmapImageRep,
                                          base: UnsafeMutablePointer<UInt8>,
                                          scale: Double),
                                top: Int, bottom: Int, minRun: Int) -> [(top: Int, bottom: Int, left: Int, right: Int)] {
                let scanX0 = Int((10.0 * scale).rounded())
                let scanX1 = min(frame.rep.pixelsWide, Int((500.0 * scale).rounded()))
                var bands: [(top: Int, bottom: Int, left: Int, right: Int)] = []
                var bandTop = -1
                var bandLeft = Int.max, bandRight = -1
                for y in top...bottom {
                    var run = 0, best = 0, runStart = 0, bestStart = 0
                    for x in scanX0..<scanX1 {
                        if isLineInk(luma(frame, x, y)) {
                            if run == 0 { runStart = x }
                            run += 1
                            if run > best { best = run; bestStart = runStart }
                        } else {
                            run = 0
                        }
                    }
                    let isLong = best >= minRun
                    if isLong {
                        if bandTop < 0 { bandTop = y }
                        bandLeft = min(bandLeft, bestStart)
                        bandRight = max(bandRight, bestStart + best - 1)
                    } else if bandTop >= 0 {
                        bands.append((bandTop, y - 1, bandLeft, bandRight))
                        bandTop = -1
                        bandLeft = Int.max
                        bandRight = -1
                    }
                }
                if bandTop >= 0 { bands.append((bandTop, bottom, bandLeft, bandRight)) }
                return bands
            }

            let rowsSpan = span(rowsFrame, bands: rowsText)
            let oneSpan = span(oneFrame, bands: oneText)
            let tableWidthPx = rowsSpan.right - rowsSpan.left + 1
            let minRun = Int((Double(tableWidthPx) * 0.8).rounded())
            let oneMinRun = Int((Double(oneSpan.right - oneSpan.left + 1) * 0.8).rounded())
            let rowsTop = rowsText.first!.top, rowsBottom = rowsText.last!.bottom
            let separators = separatorBands(rowsFrame, top: rowsTop, bottom: rowsBottom, minRun: minRun)
            let oneSeparators = separatorBands(oneFrame, top: oneText.first!.top,
                                              bottom: oneText.last!.bottom, minRun: oneMinRun)

            let thicknessPt = separators.first.map {
                Double($0.bottom - $0.top + 1) / scale
            } ?? 0
            let lineWidthPt = separators.first.map { Double($0.right - $0.left + 1) / scale } ?? 0
            let textWidthPt = Double(tableWidthPx) / scale
            emit("TABLE_ROW_LINES \(tag) 线数=\(separators.count) 负臂=\(oneSeparators.count)"
                 + " 线宽=\(String(format: "%.1f", lineWidthPt))pt 表宽=\(String(format: "%.1f", textWidthPt))pt"
                 + " 厚=\(String(format: "%.1f", thicknessPt))pt")

            XCTAssertEqual(separators.count, 3,
                           "\(tag)：体行之间读到 \(separators.count) 条线（应为 3）"
                           + " ⇒ 四行体行没有分隔或画错了行")
            XCTAssertEqual(oneSeparators.count, 0,
                           "\(tag)：单行体行臂也画了 \(oneSeparators.count) 条线 ⇒ 表头后/末行后不该画")
            for separator in separators {
                let thickness = Double(separator.bottom - separator.top + 1) / scale
                XCTAssertLessThanOrEqual(thickness, 2.0,
                                         "\(tag)：分隔线厚 \(thickness)pt（应 ≤2pt）")
                let leftPt = Double(separator.left) / scale
                let rightPt = Double(separator.right) / scale
                let textLeftPt = Double(rowsSpan.left) / scale
                let textRightPt = Double(rowsSpan.right) / scale
                XCTAssertEqual(leftPt, textLeftPt, accuracy: 6.0,
                               "\(tag)：线左沿 \(leftPt)pt 与表格文字 \(textLeftPt)pt 不同轴")
                XCTAssertEqual(rightPt, textRightPt, accuracy: 6.0,
                               "\(tag)：线右沿 \(rightPt)pt 与表格文字 \(textRightPt)pt 不同轴")
            }
        }
    }

    /// R449：QuickPick 底部必须有键盘操作提示。
    ///
    /// 缺陷形状：面板底部一直是空白（旧帧最后一行以下没有墨），↑/↓ 选择、↵ 粘贴、
    /// esc 关闭全靠用户猜。判据两头：① 产品视图树里存在提示标签、文本是 policy 的那一句、
    /// 且**在表格可见区下方**（不压候选行）；② 帧的底部 26pt 带里有墨（旧帧同带 = 0），
    /// 地板 12·scale²（1x 12 / 2x 48）。
    func testQuickPickShowsKeyboardHints() throws {
        let scratch = FileManager.default.temporaryDirectory
            .appendingPathComponent("r449-qp-hint-\(UUID().uuidString)", isDirectory: true)
        try FileManager.default.createDirectory(at: scratch, withIntermediateDirectories: true)
        defer { try? FileManager.default.removeItem(at: scratch) }

        for appearance in [NSAppearance.Name.aqua, .darkAqua] {
            let tag = appearance == .darkAqua ? "dark" : "light"
            guard let fixture = fixtures(appearance: appearance)
                .first(where: { $0.name == "quickpick-list" }) else {
                return XCTFail("\(tag)：找不到 `quickpick-list` ⇒ 这条判据没有对象")
            }
            let file = scratch.appendingPathComponent("quickpick-list-\(tag).png")
            var foundHint = false
            var hintText: String?
            var hintTop = CGFloat.nan
            var tableBottom = CGFloat.nan
            _ = try render(fixture, appearance: appearance, to: file) { host in
                @MainActor func allSubviews(_ view: NSView) -> [NSView] {
                    [view] + view.subviews.flatMap(allSubviews)
                }
                if let hint = allSubviews(host).first(where: {
                    $0.identifier?.rawValue == QuickPickKeyboardHint.identifier
                }) {
                    foundHint = true
                    hintText = (hint as? NSTextField)?.stringValue
                    hintTop = host.convert(hint.bounds, from: hint).maxY
                }
                if let table = Self.firstTableView(in: host) {
                    tableBottom = host.convert(table.visibleRect, from: table).minY
                }
            }
            guard let data = try? Data(contentsOf: file),
                  let rep = NSBitmapImageRep(data: data), let base = rep.bitmapData else {
                XCTFail("\(tag)：`quickpick-list` 读不回字节 ⇒ 这条判据没有对象")
                continue
            }
            let scale = Double(rep.pixelsWide) / Double(fixture.size.width)
            let height = rep.pixelsHigh, bytesPerRow = rep.bytesPerRow
            func luma(_ x: Int, _ y: Int) -> Double {
                let o = y * bytesPerRow + x * 4
                return 0.299 * Double(base[o]) + 0.587 * Double(base[o + 1]) + 0.114 * Double(base[o + 2])
            }
            let isInk: (Double) -> Bool = appearance == .darkAqua ? { $0 >= 70 } : { $0 <= 210 }
            let x0 = Int((QuickPickKeyboardHint.horizontalInset * scale).rounded())
            let x1 = min(rep.pixelsWide, Int(((Double(fixture.size.width) - QuickPickKeyboardHint.horizontalInset) * scale).rounded()))
            let y0 = Int(((Double(fixture.size.height) - 26.0) * scale).rounded())
            var ink = 0
            for y in y0..<height {
                for x in x0..<x1 where isInk(luma(x, y)) { ink += 1 }
            }
            let floor = Int((12.0 * scale * scale).rounded())
            emit("QUICKPICK_HINT \(tag) 底部墨=\(ink) 地板=\(floor)"
                 + " 文本=\(hintText ?? "nil") 提示顶=\(String(format: "%.1f", hintTop))"
                 + " 表底=\(String(format: "%.1f", tableBottom))")
            XCTAssertTrue(foundHint, "\(tag)：找不到 `quickPickKeyboardHint` 标签 ⇒ 提示没接进真实面板")
            XCTAssertEqual(hintText, QuickPickKeyboardHint.text,
                           "\(tag)：底部提示文本不对 ⇒ ↑↓/↵/esc 的说明没进产品")
            XCTAssertGreaterThanOrEqual(ink, floor,
                                        "\(tag)：底部 26pt 带只有 \(ink) 个墨点（地板 \(floor)）"
                                        + " ⇒ 提示没画出来（旧帧同带 = 0）")
            XCTAssertLessThanOrEqual(hintTop, tableBottom + 2.0,
                                     "\(tag)：提示顶 \(hintTop) 压到表格可见区底 \(tableBottom)"
                                     + " ⇒ 提示与候选行重叠")
        }
    }

    /// R450：Markdown 已完成任务项的**正文**必须比未完成项弱一档。
    ///
    /// 两行任务项的正文逐字相同（`待办事项`），只有 `[x]`/`[ ]` 不同：
    /// ① 正文文字区（x 40..300，排除标记字形）的墨像素平均灰度，勾选行在亮档应更亮、
    ///    暗档应更暗（次要色），差 ≥20；
    /// ② 两行的墨像素数相差 ≤25%（证明差来自颜色而不是少画了字）。
    /// 旧形状两行同色 ⇒ 差约 0，由 M1234/M1235 的刀证明。
    func testCheckedTasksDimTheirText() throws {
        let scratch = FileManager.default.temporaryDirectory
            .appendingPathComponent("r450-task-dim-\(UUID().uuidString)", isDirectory: true)
        try FileManager.default.createDirectory(at: scratch, withIntermediateDirectories: true)
        defer { try? FileManager.default.removeItem(at: scratch) }

        for appearance in [NSAppearance.Name.aqua, .darkAqua] {
            let tag = appearance == .darkAqua ? "dark" : "light"
            guard let fixture = fixtures(appearance: appearance)
                .first(where: { $0.name == "detail-tasks" }) else {
                return XCTFail("\(tag)：找不到 `detail-tasks` ⇒ 这条判据没有对象")
            }
            let file = scratch.appendingPathComponent("detail-tasks-\(tag).png")
            _ = try render(fixture, appearance: appearance, to: file)
            guard let data = try? Data(contentsOf: file),
                  let rep = NSBitmapImageRep(data: data), let base = rep.bitmapData else {
                XCTFail("\(tag)：`detail-tasks` 读不回字节 ⇒ 这条判据没有对象")
                continue
            }
            let scale = Double(rep.pixelsWide) / 720.0
            let height = rep.pixelsHigh, bytesPerRow = rep.bytesPerRow
            func luma(_ x: Int, _ y: Int) -> Double {
                let o = y * bytesPerRow + x * 4
                return 0.299 * Double(base[o]) + 0.587 * Double(base[o + 1]) + 0.114 * Double(base[o + 2])
            }
            let isInk: (Double) -> Bool = appearance == .darkAqua ? { $0 >= 70 } : { $0 <= 210 }
            let bandX0 = Int((20.0 * scale).rounded())
            let bandX1 = Int((400.0 * scale).rounded())
            let textX0 = Int((40.0 * scale).rounded())
            let textX1 = Int((300.0 * scale).rounded())

            var bands: [(top: Int, bottom: Int)] = []
            var top = -1
            for y in Int((60.0 * scale))..<min(height, Int((520.0 * scale))) {
                var has = false
                for x in bandX0..<bandX1 where isInk(luma(x, y)) {
                    has = true
                    break
                }
                if has && top < 0 { top = y }
                if !has && top >= 0 { bands.append((top, y - 1)); top = -1 }
            }
            if top >= 0 { bands.append((top, min(height, Int((520.0 * scale))) - 1)) }
            let rows = Array(bands.suffix(2))
            guard rows.count == 2 else {
                emit("TASK_DIM_NOT_RUN=runner-detail-frame-plain \(tag) 带=\(bands.count)"
                     + " ⇒ 找不到两行任务项，判据没有对象")
                continue
            }

            func stats(_ band: (top: Int, bottom: Int)) -> (mean: Double, count: Int) {
                var sum = 0.0
                var count = 0
                for y in band.top...band.bottom {
                    for x in textX0..<textX1 where isInk(luma(x, y)) {
                        sum += luma(x, y)
                        count += 1
                    }
                }
                return (count > 0 ? sum / Double(count) : .nan, count)
            }
            let checked = stats(rows[0])
            let unchecked = stats(rows[1])
            let diff = checked.mean - unchecked.mean
            emit("TASK_DIM \(tag) 勾选=\(String(format: "%.1f", checked.mean))"
                 + " 未勾选=\(String(format: "%.1f", unchecked.mean))"
                 + " 差=\(String(format: "%.1f", diff))"
                 + " 墨数=\(checked.count)/\(unchecked.count)")
            guard checked.count > 0, unchecked.count > 0 else {
                emit("TASK_DIM_NOT_RUN=text-band-empty \(tag) 墨数=\(checked.count)/\(unchecked.count)")
                continue
            }
            if appearance == .darkAqua {
                XCTAssertLessThanOrEqual(diff, -20.0,
                                         "\(tag)：完成项正文没有更暗（差 \(diff)）⇒ 完成态只在标记上")
            } else {
                XCTAssertGreaterThanOrEqual(diff, 20.0,
                                            "\(tag)：完成项正文没有更浅（差 \(diff)）⇒ 完成态只在标记上")
            }
            let ratio = Double(max(checked.count, unchecked.count)) / Double(max(min(checked.count, unchecked.count), 1))
            XCTAssertLessThanOrEqual(ratio, 1.25,
                                     "\(tag)：两行墨数相差 \(ratio) 倍 ⇒ 差来自少画了字，不是颜色")
        }
    }

    /// R451：列表项折行后，**续行必须回到首行正文的同一条竖轴**。
    ///
    /// 缺陷形状：`headIndent` 是 16，但首行正文靠**默认制表位** 28 —— 首行正文 28、续行 16，
    /// 多行列表项一折行就错开 12pt。判据读产品文本视图里那一段的 `NSParagraphStyle`：
    /// ① 必须有一个显式制表位；② 制表位位置 == headIndent（首行正文与续行同轴）；
    /// ③ headIndent > firstLineHeadIndent（续行的缩进仍存在）。
    /// 旧形状没有 tabStops（默认 28）⇒ ① 直接红。帧仍拍（`detail-list-wrap`），看图在账里。
    func testWrappedListItemsAlignTheirContinuation() throws {
        let scratch = FileManager.default.temporaryDirectory
            .appendingPathComponent("r451-list-hang-\(UUID().uuidString)", isDirectory: true)
        try FileManager.default.createDirectory(at: scratch, withIntermediateDirectories: true)
        defer { try? FileManager.default.removeItem(at: scratch) }

        for appearance in [NSAppearance.Name.aqua, .darkAqua] {
            let tag = appearance == .darkAqua ? "dark" : "light"
            guard let fixture = fixtures(appearance: appearance)
                .first(where: { $0.name == "detail-list-wrap" }) else {
                return XCTFail("\(tag)：找不到 `detail-list-wrap` ⇒ 这条判据没有对象")
            }
            let file = scratch.appendingPathComponent("detail-list-wrap-\(tag).png")
            var tabCount = -1
            var tabLocation = CGFloat.nan
            var headIndent = CGFloat.nan
            var firstLineIndent = CGFloat.nan
            _ = try render(fixture, appearance: appearance, to: file) { host in
                @MainActor func allSubviews(_ view: NSView) -> [NSView] {
                    [view] + view.subviews.flatMap(allSubviews)
                }
                guard let textView = allSubviews(host).compactMap({ $0 as? NSTextView }).first,
                      let storage = textView.textStorage else { return }
                let text = storage.string as NSString
                let range = text.range(of: "这是一条")
                guard range.location != NSNotFound else { return }
                guard let style = storage.attribute(.paragraphStyle, at: range.location,
                                                    effectiveRange: nil) as? NSParagraphStyle else { return }
                tabCount = style.tabStops.count
                tabLocation = style.tabStops.first?.location ?? .nan
                headIndent = style.headIndent
                firstLineIndent = style.firstLineHeadIndent
            }
            emit("LIST_HANG_STYLE \(tag) 制表位数=\(tabCount)"
                 + " 制表位=\(String(format: "%.1f", tabLocation))"
                 + " 续行=\(String(format: "%.1f", headIndent))"
                 + " 首行=\(String(format: "%.1f", firstLineIndent))pt")
            XCTAssertEqual(tabCount, 1,
                           "\(tag)：折行列表项没有显式制表位（读到 \(tabCount) 个）"
                           + " ⇒ 首行正文还走默认制表位 28，续行在 16")
            XCTAssertEqual(tabLocation, headIndent, accuracy: 0.01,
                           "\(tag)：制表位 \(tabLocation) 与 headIndent \(headIndent) 不同轴"
                           + " ⇒ 首行正文与续行会错开")
            XCTAssertGreaterThan(headIndent, firstLineIndent + 4,
                                 "\(tag)：续行缩进 \(headIndent) 没有大于首行缩进 \(firstLineIndent)")
        }
    }

    /// R452：推荐权重滑块的 **100% 中心刻度**。
    ///
    /// 0–200% 的量程里，默认位（100%）原先只有一排 1pt 原生小点，没有更强的参照。
    /// 判据在 `weights` 组件帧上：先按"长灰条"找到每条滑轨，再量滑轨下方
    /// 中心列与 ±20pt 邻列的**最长竖墨段**；中心列应有 1×5pt 刻度（≥3.5pt），
    /// 邻列只有原生小点（≤2pt）。旧形状中心列与邻列一样只有小点。
    func testWeightSlidersMarkTheDefaultCenter() throws {
        let scratch = FileManager.default.temporaryDirectory
            .appendingPathComponent("r452-weight-tick-\(UUID().uuidString)", isDirectory: true)
        try FileManager.default.createDirectory(at: scratch, withIntermediateDirectories: true)
        defer { try? FileManager.default.removeItem(at: scratch) }

        for appearance in [NSAppearance.Name.aqua, .darkAqua] {
            let tag = appearance == .darkAqua ? "dark" : "light"
            guard let fixture = fixtures(appearance: appearance)
                .first(where: { $0.name == "weights" }) else {
                return XCTFail("\(tag)：找不到 `weights` ⇒ 这条判据没有对象")
            }
            let file = scratch.appendingPathComponent("weights-\(tag).png")
            _ = try render(fixture, appearance: appearance, to: file)
            guard let data = try? Data(contentsOf: file),
                  let rep = NSBitmapImageRep(data: data), let base = rep.bitmapData else {
                XCTFail("\(tag)：`weights` 读不回字节 ⇒ 这条判据没有对象")
                continue
            }
            let scale = Double(rep.pixelsWide) / Double(fixture.size.width)
            let width = rep.pixelsWide, height = rep.pixelsHigh, bytesPerRow = rep.bytesPerRow
            let spp = rep.samplesPerPixel
            let alphaFirst = rep.bitmapFormat.contains(.alphaFirst)
            let rOff = alphaFirst ? 1 : 0
            func luma(_ x: Int, _ y: Int) -> Double {
                let o = y * bytesPerRow + x * spp
                return 0.299 * Double(base[o + rOff]) + 0.587 * Double(base[o + rOff + 1])
                    + 0.114 * Double(base[o + rOff + 2])
            }
            // 滑轨：长灰条（亮档 180..235 / 暗档 55..85），至少 300pt 长。
            let isTrack: (Double) -> Bool = appearance == .darkAqua
                ? { $0 >= 55 && $0 <= 85 } : { $0 >= 180 && $0 <= 235 }
            // 刻度/小点：离背景足够远（亮 ≤210 / 暗 ≥70）。
            let isInk: (Double) -> Bool = appearance == .darkAqua ? { $0 >= 70 } : { $0 <= 210 }
            let x0 = Int((20.0 * scale).rounded())
            let x1 = min(width, Int((Double(fixture.size.width) - 20.0) * scale))
            let minTrack = Int((150.0 * scale).rounded())

            /// 滑轨在 100% 被白色旋钮截成两段：取该行首末轨像素的**跨度**，
            /// 中心仍落在旋钮（100%）处；分隔线只有 1pt 高，后面按带高过滤。
            func trackSpan(y: Int) -> (count: Int, left: Int, right: Int) {
                var count = 0, left = Int.max, right = -1
                for x in x0..<x1 where isTrack(luma(x, y)) {
                    count += 1
                    left = min(left, x)
                    right = max(right, x)
                }
                return (count, left, right)
            }
            var tracks: [(top: Int, bottom: Int, left: Int, right: Int)] = []
            var trackTop = -1
            var trackLeft = 0, trackRight = 0
            for y in Int((40.0 * scale))..<min(height, Int((Double(fixture.size.height) - 20.0) * scale)) {
                let hit = trackSpan(y: y)
                if hit.count >= minTrack {
                    if trackTop < 0 {
                        trackTop = y
                        trackLeft = hit.left
                        trackRight = hit.right
                    } else {
                        trackLeft = min(trackLeft, hit.left)
                        trackRight = max(trackRight, hit.right)
                    }
                } else if trackTop >= 0 {
                    tracks.append((trackTop, y - 1, trackLeft, trackRight))
                    trackTop = -1
                }
            }
            if trackTop >= 0 {
                tracks.append((trackTop, min(height, Int((Double(fixture.size.height) - 20.0) * scale)) - 1,
                               trackLeft, trackRight))
            }
            tracks = tracks.filter { Double($0.bottom - $0.top + 1) / scale >= 2.5 }
            guard tracks.count >= 5 else {
                emit("WEIGHT_CENTER_TICK_NOT_RUN=runner-settings-content-flat \(tag) 轨=\(tracks.count)"
                     + " ⇒ 找不到权重滑轨，判据没有对象")
                continue
            }

            func longestVerticalRun(x: Int, from y0: Int, to y1: Int) -> Int {
                var best = 0, run = 0
                for y in y0..<y1 {
                    if isInk(luma(x, y)) {
                        run += 1
                        best = max(best, run)
                    } else {
                        run = 0
                    }
                }
                return best
            }

            var judged = 0
            var worstCenter = 0.0
            var worstSide = 0.0
            for track in tracks {
                let center = (track.left + track.right) / 2
                // 窗口只取轨道下方 4..14pt：旋钮的阴影贴着轨道，不进入这一带；
                // 中心的 1×5pt 刻度落在其中，邻列只有原生小点。
                let y0 = track.bottom + Int((4.0 * scale).rounded())
                let y1 = min(height, y0 + Int((10.0 * scale).rounded()))
                let centerRun = longestVerticalRun(x: center, from: y0, to: y1)
                var sideRun = 0
                for side in [center - Int((20.0 * scale).rounded()),
                             center + Int((20.0 * scale).rounded())] where side > x0 && side < x1 {
                    sideRun = max(sideRun, longestVerticalRun(x: side, from: y0, to: y1))
                }
                let centerPt = Double(centerRun) / scale
                let sidePt = Double(sideRun) / scale
                worstCenter = max(worstCenter, centerPt)
                worstSide = max(worstSide, sidePt)
                judged += 1
                XCTAssertGreaterThanOrEqual(centerPt, 3.5,
                                            "\(tag)：第 \(judged) 条滑轨中心列只有 \(centerPt)pt 竖墨"
                                            + " ⇒ 100% 中心刻度没画出来（旧形状与旁边小点一样高）")
                XCTAssertLessThanOrEqual(sidePt, 2.0,
                                         "\(tag)：第 \(judged) 条滑轨邻列竖墨 \(sidePt)pt（应 ≤2pt）"
                                         + " ⇒ 中心列没有比邻列更强")
            }
            emit("WEIGHT_CENTER_TICK \(tag) 轨=\(judged)"
                 + " 中心最高=\(String(format: "%.1f", worstCenter))pt"
                 + " 邻列最高=\(String(format: "%.1f", worstSide))pt")
        }
    }

    /// R453：`~~` 删除线的正文必须比正常正文弱一档（删除线本身仍在）。
    ///
    /// 两段正文逐字相同（`同样的字`），只有前一段带删除线：
    /// 墨像素平均灰度差——亮档删除段更亮、暗档更暗（差 ≥20）。
    /// 删除线本身由 AppKit 的 `.strikethroughStyle` 画；最长连续墨只是**前提**
    ///（证明这一行确实带线），新面是颜色差。
    /// 旧形状两段同色 ⇒ 差约 0，由 M1240/M1241 的刀证明。
    func testStruckTextIsDeEmphasized() throws {
        let scratch = FileManager.default.temporaryDirectory
            .appendingPathComponent("r453-strike-\(UUID().uuidString)", isDirectory: true)
        try FileManager.default.createDirectory(at: scratch, withIntermediateDirectories: true)
        defer { try? FileManager.default.removeItem(at: scratch) }

        for appearance in [NSAppearance.Name.aqua, .darkAqua] {
            let tag = appearance == .darkAqua ? "dark" : "light"
            guard let fixture = fixtures(appearance: appearance)
                .first(where: { $0.name == "detail-strike" }) else {
                return XCTFail("\(tag)：找不到 `detail-strike` ⇒ 这条判据没有对象")
            }
            let file = scratch.appendingPathComponent("detail-strike-\(tag).png")
            _ = try render(fixture, appearance: appearance, to: file)
            guard let data = try? Data(contentsOf: file),
                  let rep = NSBitmapImageRep(data: data), let base = rep.bitmapData else {
                XCTFail("\(tag)：`detail-strike` 读不回字节 ⇒ 这条判据没有对象")
                continue
            }
            let scale = Double(rep.pixelsWide) / 720.0
            let height = rep.pixelsHigh, bytesPerRow = rep.bytesPerRow
            let spp = rep.samplesPerPixel
            let alphaFirst = rep.bitmapFormat.contains(.alphaFirst)
            let rOff = alphaFirst ? 1 : 0
            func luma(_ x: Int, _ y: Int) -> Double {
                let o = y * bytesPerRow + x * spp
                return 0.299 * Double(base[o + rOff]) + 0.587 * Double(base[o + rOff + 1])
                    + 0.114 * Double(base[o + rOff + 2])
            }
            let isInk: (Double) -> Bool = appearance == .darkAqua ? { $0 >= 90 } : { $0 <= 190 }
            let x0 = Int((20.0 * scale).rounded())
            let x1 = Int((300.0 * scale).rounded())
            var bands: [(top: Int, bottom: Int)] = []
            var top = -1
            for y in Int((60.0 * scale))..<min(height, Int((520.0 * scale))) {
                var has = false
                for x in x0..<x1 where isInk(luma(x, y)) {
                    has = true
                    break
                }
                if has && top < 0 { top = y }
                if !has && top >= 0 { bands.append((top, y - 1)); top = -1 }
            }
            if top >= 0 { bands.append((top, min(height, Int((520.0 * scale))) - 1)) }
            let rows = Array(bands.suffix(2))
            guard rows.count == 2 else {
                emit("STRIKE_DIM_NOT_RUN=runner-detail-frame-plain \(tag) 带=\(bands.count)"
                     + " ⇒ 找不到两段正文，判据没有对象")
                continue
            }
            func stats(_ band: (top: Int, bottom: Int)) -> (mean: Double, count: Int) {
                var sum = 0.0
                var count = 0
                for y in band.top...band.bottom {
                    for x in x0..<x1 where isInk(luma(x, y)) {
                        sum += luma(x, y)
                        count += 1
                    }
                }
                return (count > 0 ? sum / Double(count) : .nan, count)
            }
            /// 每一列在该带里有没有墨（同一条正文的两段列宽一致）。
            func columnInk(_ band: (top: Int, bottom: Int)) -> [Bool] {
                var mask = [Bool](repeating: false, count: x1 - x0)
                for y in band.top...band.bottom {
                    for x in x0..<x1 where isInk(luma(x, y)) {
                        mask[x - x0] = true
                    }
                }
                return mask
            }
            let struck = stats(rows[0])
            let plain = stats(rows[1])
            let diff = struck.mean - plain.mean
            // 删除线证人：正常段的**字形间隙列**在删除段同一列被填上墨。
            // 灰度差不能当线证人（灰字的抗锯齿会并成一条长墨），间隙列只有线会填。
            let plainMask = columnInk(rows[1])
            let struckMask = columnInk(rows[0])
            let plainColumns = plainMask.indices.filter { plainMask[$0] }
            var gapTotal = 0
            var gapFilled = 0
            if let first = plainColumns.first, let last = plainColumns.last, last > first + 2 {
                for index in (first + 1)..<last where !plainMask[index] {
                    gapTotal += 1
                    if struckMask[index] { gapFilled += 1 }
                }
            }
            emit("STRIKE_DIM \(tag) 删除=\(String(format: "%.1f", struck.mean))"
                 + " 正常=\(String(format: "%.1f", plain.mean))"
                 + " 差=\(String(format: "%.1f", diff))"
                 + " 隙=\(gapFilled)/\(gapTotal)")
            guard struck.count > 0, plain.count > 0 else {
                emit("STRIKE_DIM_NOT_RUN=text-band-empty \(tag)")
                continue
            }
            if appearance == .darkAqua {
                XCTAssertLessThanOrEqual(diff, -20.0,
                                         "\(tag)：删除线正文没有更暗（差 \(diff)）⇒ 删除内容还抢视线")
            } else {
                XCTAssertGreaterThanOrEqual(diff, 20.0,
                                            "\(tag)：删除线正文没有更浅（差 \(diff)）⇒ 删除内容还抢视线")
            }
            XCTAssertGreaterThanOrEqual(gapTotal, 3,
                                        "\(tag)：正常段的字形间隙只有 \(gapTotal) 列 ⇒ 这一行不是中文正文，前提不成立")
            XCTAssertGreaterThanOrEqual(gapFilled, 1,
                                        "\(tag)：正常段的 \(gapTotal) 个字形间隙列在删除段一个也没被填上"
                                        + " ⇒ 删除线没画出来（颜色弱化不能替代线）")
        }
    }

    /// R454：弱化正文（完成项/删除线）的颜色必须过 14pt 正文的 4.5:1。
    ///
    /// R450/R453 用的 `secondaryLabelColor` 亮档实测 3.95:1；这里读 `detail-tasks` 帧上
    /// 完成项文字的**核心色**（亮档最深的墨 / 暗档最亮的墨）与正文底色，算 sRGB 相对亮度比。
    /// 旧形状亮档 3.95 会红；新动态弱化色两档都应 ≥4.5。
    func testDeEmphasizedTextMeetsContrast() throws {
        let scratch = FileManager.default.temporaryDirectory
            .appendingPathComponent("r454-deemph-\(UUID().uuidString)", isDirectory: true)
        try FileManager.default.createDirectory(at: scratch, withIntermediateDirectories: true)
        defer { try? FileManager.default.removeItem(at: scratch) }

        func channel(_ c: Double) -> Double {
            c <= 0.04045 ? c / 12.92 : pow((c + 0.055) / 1.055, 2.4)
        }
        func relativeLuminance(_ r: Double, _ g: Double, _ b: Double) -> Double {
            0.2126 * channel(r) + 0.7152 * channel(g) + 0.0722 * channel(b)
        }
        func contrast(_ a: Double, _ b: Double) -> Double {
            let hi = max(a, b), lo = min(a, b)
            return (hi + 0.05) / (lo + 0.05)
        }

        for appearance in [NSAppearance.Name.aqua, .darkAqua] {
            let tag = appearance == .darkAqua ? "dark" : "light"
            guard let fixture = fixtures(appearance: appearance)
                .first(where: { $0.name == "detail-tasks" }) else {
                return XCTFail("\(tag)：找不到 `detail-tasks` ⇒ 这条判据没有对象")
            }
            let file = scratch.appendingPathComponent("detail-tasks-\(tag).png")
            _ = try render(fixture, appearance: appearance, to: file)
            guard let data = try? Data(contentsOf: file),
                  let rep = NSBitmapImageRep(data: data), let base = rep.bitmapData else {
                XCTFail("\(tag)：`detail-tasks` 读不回字节 ⇒ 这条判据没有对象")
                continue
            }
            let scale = Double(rep.pixelsWide) / 720.0
            let height = rep.pixelsHigh, bytesPerRow = rep.bytesPerRow
            let spp = rep.samplesPerPixel
            let alphaFirst = rep.bitmapFormat.contains(.alphaFirst)
            let rOff = alphaFirst ? 1 : 0
            func rgb(_ x: Int, _ y: Int) -> (Double, Double, Double) {
                let o = y * bytesPerRow + x * spp
                return (Double(base[o + rOff]) / 255, Double(base[o + rOff + 1]) / 255,
                        Double(base[o + rOff + 2]) / 255)
            }
            func luma(_ x: Int, _ y: Int) -> Double {
                let c = rgb(x, y)
                return (0.299 * c.0 + 0.587 * c.1 + 0.114 * c.2) * 255
            }
            let isInk: (Double) -> Bool = appearance == .darkAqua ? { $0 >= 90 } : { $0 <= 190 }
            let x0 = Int((20.0 * scale).rounded())
            let x1 = Int((300.0 * scale).rounded())
            var bands: [(top: Int, bottom: Int)] = []
            var top = -1
            for y in Int((60.0 * scale))..<min(height, Int((520.0 * scale))) {
                var has = false
                for x in x0..<x1 where isInk(luma(x, y)) {
                    has = true
                    break
                }
                if has && top < 0 { top = y }
                if !has && top >= 0 { bands.append((top, y - 1)); top = -1 }
            }
            if top >= 0 { bands.append((top, min(height, Int((520.0 * scale))) - 1)) }
            let rows = Array(bands.suffix(2))
            guard rows.count == 2 else {
                emit("DEEMPHASIS_CONTRAST_NOT_RUN=runner-detail-frame-plain \(tag) 带=\(bands.count)")
                continue
            }
            let checked = rows[0]
            var core: (Double, Double, Double)?
            var coreLuma = appearance == .darkAqua ? -1.0 : 999.0
            for y in checked.top...checked.bottom {
                for x in Int((40.0 * scale).rounded())..<x1 where isInk(luma(x, y)) {
                    let value = luma(x, y)
                    let better = appearance == .darkAqua ? value > coreLuma : value < coreLuma
                    if better { coreLuma = value; core = rgb(x, y) }
                }
            }
            guard let core else {
                emit("DEEMPHASIS_CONTRAST_NOT_RUN=text-band-empty \(tag)")
                continue
            }
            let bg = rgb(min(rep.pixelsWide - 1, Int((600.0 * scale).rounded())),
                         (checked.top + checked.bottom) / 2)
            let textLum = relativeLuminance(core.0, core.1, core.2)
            let bgLum = relativeLuminance(bg.0, bg.1, bg.2)
            let ratio = contrast(textLum, bgLum)
            emit("DEEMPHASIS_CONTRAST \(tag) 文字=\(String(format: "%.0f", coreLuma))"
                 + " 底色=\(String(format: "%.0f", bg.0 * 255))"
                 + " 比=\(String(format: "%.2f", ratio))")
            XCTAssertGreaterThanOrEqual(ratio, 4.5,
                                        "\(tag)：弱化正文对比 \(String(format: "%.2f", ratio)):1"
                                        + " 低于 14pt 正文 4.5:1（旧 secondary 亮档 3.95）")
        }
    }

    /// R455：行内代码的底色带必须有**内边距**。
    ///
    /// 旧形状是属性串 `.backgroundColor`：底色带 94.5pt、字宽 92.0pt，左右各 ~1pt。
    /// 判据：找一条 40..150pt 的**连续**带色行（文字抗锯齿是碎片，进不来）→ 带宽；
    /// 取包含它的文字带高度 → 带内文字墨宽；带宽−字宽 ≥5pt。
    /// 代码块的通栏带（>300pt）与 1pt 分隔线都不在范围里。
    func testInlineCodeBackgroundHasPadding() throws {
        let scratch = FileManager.default.temporaryDirectory
            .appendingPathComponent("r455-inline-code-\(UUID().uuidString)", isDirectory: true)
        try FileManager.default.createDirectory(at: scratch, withIntermediateDirectories: true)
        defer { try? FileManager.default.removeItem(at: scratch) }

        for appearance in [NSAppearance.Name.aqua, .darkAqua] {
            let tag = appearance == .darkAqua ? "dark" : "light"
            guard let fixture = fixtures(appearance: appearance)
                .first(where: { $0.name == "detail-markdown-rendered" }) else {
                return XCTFail("\(tag)：找不到 `detail-markdown-rendered` ⇒ 这条判据没有对象")
            }
            let file = scratch.appendingPathComponent("detail-markdown-rendered-\(tag).png")
            _ = try render(fixture, appearance: appearance, to: file)
            guard let data = try? Data(contentsOf: file),
                  let rep = NSBitmapImageRep(data: data), let base = rep.bitmapData else {
                XCTFail("\(tag)：`detail-markdown-rendered` 读不回字节 ⇒ 这条判据没有对象")
                continue
            }
            let scale = Double(rep.pixelsWide) / 720.0
            let height = rep.pixelsHigh, bytesPerRow = rep.bytesPerRow
            let spp = rep.samplesPerPixel
            let alphaFirst = rep.bitmapFormat.contains(.alphaFirst)
            let rOff = alphaFirst ? 1 : 0
            let nonPremultiplied = rep.bitmapFormat.contains(.alphaNonpremultiplied)
            let alphaOff = spp == 4 ? (alphaFirst ? 0 : 3) : -1
            // runner 的详情帧约 76% 透明：底色带是以 alpha 画在透明底上的，直接读 RGB 会读到
            // 预乘后的近黑值（R458 现读：light/dark 都“找不到带”）。先按页面底合成，再量**相对**
            // 页面底的小色差（不抄产品的绝对色）：页面底由该行的众数自己给出，所以两档都成立。
            let pageBase = appearance == .darkAqua ? 30.0 : 255.0
            func luma(_ x: Int, _ y: Int) -> Double {
                let o = y * bytesPerRow + x * spp
                func channel(_ index: Int) -> Double {
                    let value = Double(base[o + index])
                    guard alphaOff >= 0 else { return value }
                    let alpha = Double(base[o + alphaOff]) / 255.0
                    return nonPremultiplied ? value * alpha + pageBase * (1 - alpha)
                                            : value + pageBase * (1 - alpha)
                }
                return 0.299 * channel(rOff) + 0.587 * channel(rOff + 1)
                    + 0.114 * channel(rOff + 2)
            }
            let isInk: (Double) -> Bool = appearance == .darkAqua ? { $0 >= 150 } : { $0 <= 150 }
            let x0 = Int((20.0 * scale).rounded())
            let x1 = Int((640.0 * scale).rounded())
            let minWidth = Int((40.0 * scale).rounded())
            let maxWidth = Int((150.0 * scale).rounded())
            let gapPx = max(3, Int((3.0 * scale).rounded()))
            // 页面底 = 该行众数；底色带 = 相对页面底 4…48 的**第二众数**。
            // 只认第二众数的像素（容差 6），避免把相邻正文的抗锯齿算进带宽。
            func bandLuma(row y: Int) -> (page: Double, band: Double)? {
                var bins: [Int: Int] = [:]
                for x in x0..<x1 { bins[Int(luma(x, y)) / 8, default: 0] += 1 }
                guard let pageBin = bins.max(by: { $0.value < $1.value })?.key else { return nil }
                let page = Double(pageBin * 8 + 4)
                let threshold = max(8, Int(8.0 * scale * scale))
                let bandBin = bins.filter {
                    let value = Double($0.key * 8 + 4)
                    return abs(value - page) >= 4 && abs(value - page) <= 48
                        && $0.value >= threshold
                }.max(by: { $0.value < $1.value })?.key
                guard let bandBin else { return nil }
                return (page, Double(bandBin * 8 + 4))
            }
            func candidateSpans(y: Int, band: Double) -> [InlineCodeBandChoice.Candidate] {
                let yLo = max(0, y - Int((20.0 * scale).rounded()))
                let yHi = min(height - 1, y + Int((20.0 * scale).rounded()))
                var xs: [Int] = []
                for x in x0..<x1 where abs(luma(x, y) - band) <= 6 { xs.append(x) }
                guard !xs.isEmpty else { return [] }
                var prefix = [Int](repeating: 0, count: x1 - x0 + 2)
                for x in x0..<x1 {
                    prefix[x - x0 + 1] = prefix[x - x0] + (isInk(luma(x, y)) ? 1 : 0)
                }
                struct RawRun { let left: Int; let right: Int; let span: Int; let ink: Int; let coverage: Double }
                var runs: [RawRun] = []
                var i = 0
                while i < xs.count {
                    var j = i + 1
                    while j < xs.count, xs[j] - xs[j - 1] <= gapPx { j += 1 }
                    let left = xs[i], right = xs[j - 1]
                    let span = right - left + 1
                    let ink = prefix[right - x0 + 1] - prefix[left - x0]
                    runs.append(RawRun(left: left, right: right, span: span, ink: ink,
                                       coverage: Double(j - i) / Double(span)))
                    i = j
                }
                let rowMax = runs.map(\.span).max() ?? 0
                return runs.map { run in
                    var inkLeft = Int.max, inkRight = -1, inkInWindow = 0
                    for yy in yLo...yHi {
                        for xx in run.left...run.right where isInk(luma(xx, yy)) {
                            inkInWindow += 1
                            inkLeft = min(inkLeft, xx)
                            inkRight = max(inkRight, xx)
                        }
                    }
                    let inkWidth = inkRight >= inkLeft
                        ? Double(inkRight - inkLeft + 1) / scale : 0
                    return InlineCodeBandChoice.Candidate(
                        row: y, left: run.left, right: run.right,
                        coverage: run.coverage, ink: run.ink,
                        padding: Double(run.span) / scale - inkWidth,
                        rowMaxBandRun: rowMax,
                        verticalInk: inkInWindow)
                }
            }

            // 1) 所有候选行里选**覆盖率最高**的 run（真带 padding 行 ~1.0；假文字带 ~0.55）。
            var candidates: [InlineCodeBandChoice.Candidate] = []
            for y in Int((80.0 * scale))..<min(height, Int((400.0 * scale))) {
                guard let tones = bandLuma(row: y) else { continue }
                candidates.append(contentsOf: candidateSpans(y: y, band: tones.band))
            }
            let chosen = InlineCodeBandChoice.best(
                candidates, minSpan: minWidth, maxSpan: maxWidth,
                minCoverage: 0.55, minInk: max(6, Int(6.0 * scale * scale)))
            // R475：四门分桶 —— 只看 top-by-padding 时，长带若被某一门砍掉就只剩短碎片，
            // 分不清是 span 太短、覆盖率太低、ink 不够，还是同一行有全宽块底。
            // 这里逐门数一遍（门与 `best` 同一组常量），下一跑就能回答"长带死在哪一门"。
            let minInk = max(6, Int(6.0 * scale * scale))
            let spanOK = candidates.filter { $0.span >= minWidth && $0.span <= maxWidth }
            let coverageOK = spanOK.filter { $0.coverage >= 0.55 }
            let inkOK = coverageOK.filter { $0.verticalInk >= minInk }
            let rowMaxOK = inkOK.filter { $0.rowMaxBandRun <= maxWidth }
            emit("INLINE_CODE_GATES \(tag) 候选=\(candidates.count)"
                 + " 过span=\(spanOK.count) 过coverage=\(coverageOK.count)"
                 + " 过ink=\(inkOK.count) 过rowMax=\(rowMaxOK.count)"
                 + " 门=span[\(minWidth),\(maxWidth)]px coverage≥0.55 ink≥\(minInk) rowMax≤\(maxWidth)px")
            let topSpan = candidates.sorted { $0.span > $1.span }.prefix(6)
                .map { "r\($0.row):s\(String(format: "%.1f", Double($0.span) / scale))"
                    + ":c\(String(format: "%.2f", $0.coverage)):i\($0.ink):v\($0.verticalInk)"
                    + ":p\(String(format: "%.1f", $0.padding))"
                    + ":m\(String(format: "%.1f", Double($0.rowMaxBandRun) / scale))" }
                .joined(separator: ",")
            emit("INLINE_CODE_TOP_SPAN \(tag) \(topSpan)")
            // R472：诊断必须先于 guard —— R470 的整行门把 runner dark 的假 150 带排掉后，
            // guard 先红，DIAG 一行都没打出来。这里用"chosen 为 nil 时的第一条候选行"做诊断锚点。
            let diagRow = chosen?.row ?? candidates.first?.row ?? -1
            let diagTones = diagRow >= 0 ? bandLuma(row: diagRow) : nil
            let topCandidates = candidates.sorted { $0.padding > $1.padding }.prefix(5)
                .map { "r\($0.row):s\(String(format: "%.1f", Double($0.span) / scale))"
                    + ":c\(String(format: "%.2f", $0.coverage)):i\($0.ink):v\($0.verticalInk)"
                    + ":p\(String(format: "%.1f", $0.padding))"
                    + ":m\(String(format: "%.1f", Double($0.rowMaxBandRun) / scale))" }
                .joined(separator: ",")
            emit("INLINE_CODE_DIAG \(tag) 选行=\(diagRow)"
                 + " 页=\(String(format: "%.0f", diagTones?.page ?? -1))"
                 + " 带=\(String(format: "%.0f", diagTones?.band ?? -1))"
                 + " 候选=\(candidates.count) 选中=\(chosen != nil) top=\(topCandidates)")
            guard let band = chosen else {
                XCTFail("\(tag)：找不到行内代码的短底色带 ⇒ 底色带没画出来（夹具保证这一行有行内码）")
                continue
            }
            let bandRow = band.row, bandLeft = band.left, bandRight = band.right
            // 2) 文字窗口：带顶 padding 与字形之间行距有空隙，不能用"连续墨行"扩；
            //    在带的左右范围内取 bandRow ±20pt 的窗口找字墨（行内码就在带里）。
            let bandTop = max(Int((80.0 * scale)), bandRow - Int((20.0 * scale).rounded()))
            let bandBottom = min(min(height - 1, Int((400.0 * scale))),
                                 bandRow + Int((20.0 * scale).rounded()))
            // 3) 带内文字墨宽。
            var inkLeft = Int.max, inkRight = -1
            for y in bandTop...bandBottom {
                for x in bandLeft...bandRight where isInk(luma(x, y)) {
                    inkLeft = min(inkLeft, x)
                    inkRight = max(inkRight, x)
                }
            }
            guard inkRight >= inkLeft else {
                emit("INLINE_CODE_PAD_NOT_RUN=text-empty \(tag)")
                continue
            }
            let bandWidth = Double(bandRight - bandLeft + 1) / scale
            let inkWidth = Double(inkRight - inkLeft + 1) / scale
            let padding = bandWidth - inkWidth
            emit("INLINE_CODE_PAD \(tag) 带宽=\(String(format: "%.1f", bandWidth))pt"
                 + " 字宽=\(String(format: "%.1f", inkWidth))pt"
                 + " 隙=\(String(format: "%.1f", padding))pt")
            XCTAssertGreaterThanOrEqual(padding, 4.5,
                                        "\(tag)：行内代码底色带只比字宽多 \(padding)pt"
                                        + " ⇒ 没有内边距（旧形状 ~2.5pt）")
            XCTAssertLessThanOrEqual(padding, 12.0,
                                     "\(tag)：行内代码底色带比字宽多 \(padding)pt ⇒ 读到的是别的带")
        }
    }

    /// R442：设置侧栏必须有「关于」这一行。
    ///
    /// 1x 可画的是侧栏（设置内容列在 runner 上是平涂）：数分区标签带，应为
    /// `SettingsCategory.allCases.count`（7）。行带**从视图树取**（`sidebarTextBands`）：
    /// R118 量过同一份设置帧在 runner 上整列下移 282pt，绝对 y 60..285 在那里一条都盖不住
    ///（R442 的 CI 就是这么红的：light 读到 0 条）；树给的带与被判的东西同源（D-166）。
    /// 暗档若读不到 7 条带 ⇒ 具名 `SETTINGS_ABOUT_ROW_NOT_RUN=runner-dark-sidebar-text-blind`，
    /// 不把"读不到"记成"没有这一行"。
    func testSettingsSidebarShowsTheAboutCategoryRow() throws {
        let scratch = FileManager.default.temporaryDirectory
            .appendingPathComponent("r442-about-row-\(UUID().uuidString)", isDirectory: true)
        try FileManager.default.createDirectory(at: scratch, withIntermediateDirectories: true)
        defer { try? FileManager.default.removeItem(at: scratch) }

        XCTAssertTrue(SettingsCategory.allCases.contains(.about), "关于没进侧栏分区")

        for appearance in [NSAppearance.Name.aqua, .darkAqua] {
            let tag = appearance == .darkAqua ? "dark" : "light"
            guard let fixture = fixtures(appearance: appearance)
                .first(where: { $0.name == "settings-general" }) else {
                return XCTFail("\(tag)：找不到 `settings-general` ⇒ 这条判据没有对象")
            }
            let file = scratch.appendingPathComponent("settings-general-\(tag).png")
            var rowBands: [CGRect] = []
            _ = try render(fixture, appearance: appearance, to: file) { host in
                rowBands = Self.sidebarTextBands(in: host)
            }
            guard let data = try? Data(contentsOf: file),
                  let rep = NSBitmapImageRep(data: data), let base = rep.bitmapData else {
                XCTFail("\(tag)：`settings-general` 读不回字节 ⇒ 这条判据没有对象")
                return
            }
            let scale = Double(rep.pixelsWide) / 720.0
            let bytesPerRow = rep.bytesPerRow
            func luma(_ x: Int, _ y: Int) -> Double {
                let o = y * bytesPerRow + x * 4
                return 0.299 * Double(base[o]) + 0.587 * Double(base[o + 1]) + 0.114 * Double(base[o + 2])
            }
            // 只数**主色/强调色**标签：底部那行署名是 `.secondary`（亮档 luma≈128），
            // 用 ≤190 就会在"关于行被删掉、署名行上移"时把署名行当成第 7 条带（M1214 第一版
            // 逃脱就是这么发生的）。主色标签 luma≈0、选中的强调色≈101，≤110 两者都进、署名行不进。
            let isInk: (Double) -> Bool = appearance == .darkAqua ? { $0 >= 90 } : { $0 <= 110 }
            let x0 = Int((38.0 * scale).rounded())
            let x1 = Int((120.0 * scale).rounded())
            // 逐条**树给的**行带数：一条带里标签列有墨就算这一行有标签。底部那行署名不在
            // 树的行带里，不会被当成第 8 条（M1214 第一版逃脱的那一格也因此不会再发生）。
            var bands = 0
            for band in rowBands {
                let y0 = max(0, Int((band.minY * scale).rounded()))
                let y1 = min(rep.pixelsHigh, Int((band.maxY * scale).rounded()))
                var has = false
                if y1 > y0 {
                    for y in y0..<y1 {
                        for x in x0..<x1 where isInk(luma(x, y)) {
                            has = true
                            break
                        }
                        if has { break }
                    }
                }
                if has { bands += 1 }
            }
            if appearance == .darkAqua && bands < SettingsCategory.allCases.count {
                emit("SETTINGS_ABOUT_ROW_NOT_RUN=runner-dark-sidebar-text-blind \(tag) 带=\(bands)"
                     + " ⇒ 暗侧栏标签在离屏通道读不出来（R457 同族），不当成没有这一行")
                continue
            }
            emit("SETTINGS_ABOUT_ROW \(tag) 分区行=\(bands) 应为=\(SettingsCategory.allCases.count)")
            XCTAssertEqual(bands, SettingsCategory.allCases.count,
                           "\(tag)：分区标签带 \(bands) 条（应为 \(SettingsCategory.allCases.count)）"
                           + " ⇒ 关于行没进侧栏或标签被截掉")
        }
    }

    /// R444：主列表行的时间行必须带来源 App 名（时间在前、来源在后；nil 只显示时间）。
    ///
    /// 两帧同一段正文/时间，只差来源字段：`sidebar-history` 第一行（Safari）对
    /// `sidebar-no-source` 第一行（来源 nil）。读第一行最后一条文字带（时间行）的墨宽，
    /// 来源行应比无来源行宽出来源那一段；左沿相同（时间不因来源挪位）。
    /// 1x 通道：侧栏行文字在 runner 上画得出来（R431 的同一批帧）；若整列无墨则具名 NOT-RUN。
    func testHistoryRowsShowTheirSourceAppName() throws {
        let scratch = FileManager.default.temporaryDirectory
            .appendingPathComponent("r444-row-source-\(UUID().uuidString)", isDirectory: true)
        try FileManager.default.createDirectory(at: scratch, withIntermediateDirectories: true)
        defer { try? FileManager.default.removeItem(at: scratch) }

        for appearance in [NSAppearance.Name.aqua, .darkAqua] {
            let tag = appearance == .darkAqua ? "dark" : "light"
            func timeLine(_ name: String) throws -> (width: Double, left: Double)? {
                guard let fixture = fixtures(appearance: appearance)
                    .first(where: { $0.name == name }) else {
                    XCTFail("\(tag)：找不到 `\(name)` ⇒ 这条判据没有对象")
                    return nil
                }
                let file = scratch.appendingPathComponent("\(name)-\(tag).png")
                _ = try render(fixture, appearance: appearance, to: file)
                guard let data = try? Data(contentsOf: file),
                      let rep = NSBitmapImageRep(data: data), let base = rep.bitmapData else {
                    XCTFail("\(tag)：`\(name)` 读不回字节 ⇒ 这条判据没有对象")
                    return nil
                }
                let scale = Double(rep.pixelsWide) / Double(fixture.size.width)
                let height = rep.pixelsHigh, bytesPerRow = rep.bytesPerRow
                func luma(_ x: Int, _ y: Int) -> Double {
                    let o = y * bytesPerRow + x * 4
                    return 0.299 * Double(base[o]) + 0.587 * Double(base[o + 1]) + 0.114 * Double(base[o + 2])
                }
                let isInk: (Double) -> Bool = appearance == .darkAqua ? { $0 >= 90 } : { $0 <= 190 }
                let x0 = Int((96.0 * scale).rounded())
                let x1 = Int((285.0 * scale).rounded())
                var bands: [(top: Int, bottom: Int)] = []
                var top = -1
                for y in Int((140.0 * scale))..<min(height, Int((230.0 * scale))) {
                    var has = false
                    for x in x0..<x1 where isInk(luma(x, y)) {
                        has = true
                        break
                    }
                    if has && top < 0 { top = y }
                    if !has && top >= 0 { bands.append((top, y - 1)); top = -1 }
                }
                if top >= 0 { bands.append((top, min(height, Int((230.0 * scale))) - 1)) }
                guard bands.count >= 3 else { return nil }
                let timeBand = bands[2]                // 标题/预览两行之后是时间行
                var leftmost = Int.max
                var rightmost = -1
                for y in timeBand.top...timeBand.bottom {
                    for x in x0..<x1 where isInk(luma(x, y)) {
                        leftmost = min(leftmost, x)
                        rightmost = max(rightmost, x)
                    }
                }
                guard rightmost >= 0 else { return nil }
                return (Double(rightmost - leftmost + 1) / scale, Double(leftmost) / scale)
            }
            guard let source = try timeLine("sidebar-history"),
                  let noSource = try timeLine("sidebar-no-source") else {
                emit("HISTORY_ROW_SOURCE_NOT_RUN=runner-1x-sidebar-plain \(tag)"
                     + " ⇒ 侧栏行文字没画出来（1x 通道），这条判据没有对象")
                continue
            }
            emit("HISTORY_ROW_SOURCE \(tag) 来源行宽=\(String(format: "%.1f", source.width))pt"
                 + " 无来源行宽=\(String(format: "%.1f", noSource.width))pt"
                 + " 差=\(String(format: "%.1f", source.width - noSource.width))pt"
                 + " 左沿=\(String(format: "%.1f", source.left))/\(String(format: "%.1f", noSource.left))pt")
            XCTAssertGreaterThanOrEqual(source.width - noSource.width, 25.0,
                                        "\(tag)：来源行只比无来源行宽 \(source.width - noSource.width)pt"
                                        + " ⇒ 来源 App 名没有进时间行")
            XCTAssertEqual(source.left, noSource.left, accuracy: 1.0,
                           "\(tag)：来源行左沿 \(source.left)pt 与无来源 \(noSource.left)pt 不同 ⇒ 时间被挪了")
        }
    }

    /// R445：侧栏搜索必须匹配**来源 App 名**（R437 的欠账；R444 已把来源显示在行里）。
    ///
    /// 查询 "Safari" 不在任何一行的正文里，只在第一行的来源字段里：
    /// `sidebar-search-source` 的表行数应为 1（新口径），`sidebar-no-results`（不存在的词）为 0。
    /// 旧口径下前者会退化成 0 —— 表行数是结构量，1x runner 上也成立；行带墨是"这一行真画出来了"的像素证人。
    func testSidebarSearchMatchesTheSourceAppName() throws {
        let scratch = FileManager.default.temporaryDirectory
            .appendingPathComponent("r445-search-source-\(UUID().uuidString)", isDirectory: true)
        try FileManager.default.createDirectory(at: scratch, withIntermediateDirectories: true)
        defer { try? FileManager.default.removeItem(at: scratch) }

        for appearance in [NSAppearance.Name.aqua, .darkAqua] {
            let tag = appearance == .darkAqua ? "dark" : "light"
            func read(_ name: String) throws -> (tableFound: Bool, rows: Int, rowBands: Int) {
                guard let fixture = fixtures(appearance: appearance)
                    .first(where: { $0.name == name }) else {
                    XCTFail("\(tag)：找不到 `\(name)` ⇒ 这条判据没有对象")
                    return (false, -1, -1)
                }
                let file = scratch.appendingPathComponent("\(name)-\(tag).png")
                var rows = -1
                var tableFound = false
                _ = try render(fixture, appearance: appearance, to: file) { host in
                    if let table = Self.firstTableView(in: host) {
                        tableFound = true
                        rows = table.numberOfRows
                    }
                }
                guard let data = try? Data(contentsOf: file),
                      let rep = NSBitmapImageRep(data: data), let base = rep.bitmapData else {
                    XCTFail("\(tag)：`\(name)` 读不回字节 ⇒ 这条判据没有对象")
                    return (tableFound, rows, -1)
                }
                let scale = Double(rep.pixelsWide) / Double(fixture.size.width)
                let height = rep.pixelsHigh, bytesPerRow = rep.bytesPerRow
                func luma(_ x: Int, _ y: Int) -> Double {
                    let o = y * bytesPerRow + x * 4
                    return 0.299 * Double(base[o]) + 0.587 * Double(base[o + 1]) + 0.114 * Double(base[o + 2])
                }
                let isInk: (Double) -> Bool = appearance == .darkAqua ? { $0 >= 90 } : { $0 <= 190 }
                let x0 = Int((96.0 * scale).rounded())
                let x1 = Int((285.0 * scale).rounded())
                var bands = 0
                var top = -1
                for y in Int((140.0 * scale))..<min(height, Int((260.0 * scale))) {
                    var has = false
                    for x in x0..<x1 where isInk(luma(x, y)) {
                        has = true
                        break
                    }
                    if has && top < 0 { top = y }
                    if !has && top >= 0 { bands += 1; top = -1 }
                }
                if top >= 0 { bands += 1 }
                return (tableFound, rows, bands)
            }
            let source = try read("sidebar-search-source")
            let empty = try read("sidebar-no-results")
            emit("HISTORY_SEARCH_SOURCE \(tag) 来源查询行数=\(source.rows)（行带=\(source.rowBands)）"
                 + " 无结果查询行数=\(empty.rows)（行带=\(empty.rowBands)）")
            // runner 1x 的暗档侧栏行文字是盲区（R444 已给 `HISTORY_ROW_SOURCE` 具名）：
            // 这里只把**行带像素证人**记成 NOT-RUN（fe956e3 跑实读 dark 行带 1），
            // 表行数与"无结果无表"两条结构判据照判。门槛没动：读得到 ≥3 的档仍照红。
            let rowBandsBlind = source.rowBands < 3
            if rowBandsBlind {
                emit("HISTORY_SEARCH_SOURCE_NOT_RUN=runner-1x-sidebar-plain \(tag)"
                     + " 行带=\(source.rowBands) ⇒ 侧栏行文字没画出来（1x 通道），像素证人记未运行")
            }
            // 无结果态会把列表换成那句"没有匹配"，**没有 NSTableView**：无表 = 0 行。
            XCTAssertTrue(!empty.tableFound || empty.rows == 0,
                          "\(tag)：不存在的词却留下了表 \(empty.rows) 行 ⇒ 负对照不成立")
            XCTAssertTrue(source.tableFound,
                          "\(tag)：来源查询没有 NSTableView ⇒ 这一屏没有列表可判")
            XCTAssertEqual(source.rows, 1,
                           "\(tag)：只命中来源名的查询搜出 \(source.rows) 行（应为 1）"
                           + " ⇒ 侧栏搜索没匹配 `sourceAppName`")
            if !rowBandsBlind {
                XCTAssertGreaterThanOrEqual(source.rowBands, 3,
                                            "\(tag)：货源查询那一行只画出 \(source.rowBands) 条带"
                                            + " ⇒ 行没画出来（表行数对但像素无证）")
            }
        }
    }

    /// R456：搜索命中必须在**行里**看得出来（标题或来源行）。
    ///
    /// 旧形状：过滤用了 query，行里却一个字都不标 —— 只命中来源 App 名的行（R445）整行没有线索，
    /// 正文命中落在两行截断之外时同样没有。新形状：命中的可见片段带
    /// `DetailTypography.highlightColor` 底。判据用**黄像素落在哪一条文字带**回答：
    /// 来源查询帧 → 标题带 0、来源带 > 0；正文查询帧 → 标题带 > 0、来源带 0；
    /// 无查询帧 → 两处都 0。地板 40×scale²（1x 源词约 40×11pt、扣掉字形仍有 ~290 颗）。
    func testSidebarSearchRowsShowWhyTheyMatched() throws {
        let scratch = FileManager.default.temporaryDirectory
            .appendingPathComponent("r456-row-match-\(UUID().uuidString)", isDirectory: true)
        try FileManager.default.createDirectory(at: scratch, withIntermediateDirectories: true)
        defer { try? FileManager.default.removeItem(at: scratch) }

        for appearance in [NSAppearance.Name.aqua, .darkAqua] {
            let tag = appearance == .darkAqua ? "dark" : "light"
            func read(_ name: String) throws -> (title: Int, source: Int, rowBands: Int, scale: Double) {
                guard let fixture = fixtures(appearance: appearance)
                    .first(where: { $0.name == name }) else {
                    XCTFail("\(tag)：找不到 `\(name)` ⇒ 这条判据没有对象")
                    return (-1, -1, -1, 1)
                }
                let file = scratch.appendingPathComponent("\(name)-\(tag).png")
                _ = try render(fixture, appearance: appearance, to: file)
                guard let data = try? Data(contentsOf: file),
                      let rep = NSBitmapImageRep(data: data), let base = rep.bitmapData else {
                    XCTFail("\(tag)：`\(name)` 读不回字节 ⇒ 这条判据没有对象")
                    return (-1, -1, -1, 1)
                }
                let scale = Double(rep.pixelsWide) / Double(fixture.size.width)
                let height = rep.pixelsHigh, bytesPerRow = rep.bytesPerRow
                let spp = rep.samplesPerPixel
                let alphaFirst = rep.bitmapFormat.contains(.alphaFirst)
                let rOff = alphaFirst ? 1 : 0
                func luma(_ x: Int, _ y: Int) -> Double {
                    let o = y * bytesPerRow + x * spp
                    return 0.299 * Double(base[o + rOff]) + 0.587 * Double(base[o + rOff + 1])
                        + 0.114 * Double(base[o + rOff + 2])
                }
                func isYellow(_ x: Int, _ y: Int) -> Bool {
                    let o = y * bytesPerRow + x * spp
                    let r = Double(base[o + rOff])
                    let g = Double(base[o + rOff + 1])
                    let b = Double(base[o + rOff + 2])
                    return r - b >= 40 && g - b >= 25 && r >= 80
                }
                let isInk: (Double) -> Bool = appearance == .darkAqua ? { $0 >= 90 } : { $0 <= 190 }
                let x0 = Int((96.0 * scale).rounded())
                let x1 = Int((285.0 * scale).rounded())
                var bands: [(top: Int, bottom: Int)] = []
                var top = -1
                for y in Int((140.0 * scale))..<min(height, Int((260.0 * scale))) {
                    var has = false
                    for x in x0..<x1 where isInk(luma(x, y)) {
                        has = true
                        break
                    }
                    if has && top < 0 { top = y }
                    if !has && top >= 0 {
                        bands.append((top, y - 1))
                        top = -1
                    }
                    if bands.count >= 3 { break }
                }
                if top >= 0 && bands.count < 3 {
                    bands.append((top, min(height, Int((260.0 * scale))) - 1))
                }
                func yellow(_ band: (top: Int, bottom: Int)?) -> Int {
                    guard let band else { return -1 }
                    var count = 0
                    for y in band.top...band.bottom {
                        for x in x0..<x1 where isYellow(x, y) { count += 1 }
                    }
                    return count
                }
                let rowBands = bands.count
                let title = (rowBands >= 3 ? yellow(bands[0]) : -1)
                    + (rowBands >= 3 ? yellow(bands[1]) : -1)
                let source = rowBands >= 3 ? yellow(bands[2]) : -1
                return (title, source, rowBands, scale)
            }
            let sourceQuery = try read("sidebar-search-source")
            let contentQuery = try read("sidebar-search-content")
            let neutral = try read("sidebar-history")
            emit("HISTORY_ROW_MATCH \(tag) 来源查询 标题黄=\(sourceQuery.title) 来源黄=\(sourceQuery.source)"
                 + " 行带=\(sourceQuery.rowBands)"
                 + " ｜正文查询 标题黄=\(contentQuery.title) 来源黄=\(contentQuery.source)"
                 + " ｜无查询 标题黄=\(neutral.title) 来源黄=\(neutral.source)")
            // runner 1x 的暗档侧栏行文字是盲区（R444/R445 同族）：读不到三条带就不判像素，
            // 具名 NOT-RUN；亮档读得到时照红，门槛不动。
            if sourceQuery.rowBands < 3 || contentQuery.rowBands < 3 || neutral.rowBands < 3 {
                emit("HISTORY_ROW_MATCH_NOT_RUN=runner-1x-sidebar-plain \(tag)"
                     + " 行带=\(sourceQuery.rowBands)/\(contentQuery.rowBands)/\(neutral.rowBands)"
                     + " ⇒ 侧栏行文字没画出来（1x 通道），像素证人记未运行")
                continue
            }
            let scale = sourceQuery.scale
            let floor = Int((40.0 * scale * scale).rounded())
            XCTAssertEqual(neutral.title, 0,
                           "\(tag)：没有查询却读到 \(neutral.title) 颗黄底 ⇒ 高亮漏电")
            XCTAssertEqual(neutral.source, 0,
                           "\(tag)：没有查询却读到 \(neutral.source) 颗来源黄底 ⇒ 高亮漏电")
            XCTAssertEqual(sourceQuery.title, 0,
                           "\(tag)：只命中来源的查询把标题也标了 \(sourceQuery.title) 颗黄 ⇒ 高亮落错字段")
            XCTAssertGreaterThanOrEqual(sourceQuery.source, floor,
                                        "\(tag)：只命中来源的行来源带只有 \(sourceQuery.source) 颗黄"
                                        + "（地板 \(floor)）⇒ 行里看不出为什么命中")
            XCTAssertGreaterThanOrEqual(contentQuery.title, floor,
                                        "\(tag)：正文命中的行标题只有 \(contentQuery.title) 颗黄"
                                        + "（地板 \(floor)）⇒ 命中没进列表")
            XCTAssertEqual(contentQuery.source, 0,
                           "\(tag)：正文查询把来源带标了 \(contentQuery.source) 颗黄 ⇒ 高亮落错字段")
        }
    }

    /// R436：批量操作栏里「删除」与其余四颗之间必须有一条发丝分隔。
    ///
    /// 缺陷形状（修之前 `sidebar-multi-select` 亮/暗现读）：五颗在 `spacing: 0` 的一排里，
    /// 破坏性的垃圾桶只靠红色与其它四颗分开；分隔带里一笔墨都没有。
    /// 判据只读帧：先按红色找到垃圾桶的最左列，再量它左侧 8..4pt 的窄带（分隔线应在那里）；
    /// 旧形状 0 墨、新形状有墨；校准 = 垃圾桶本体的红像素数 > 地板。
    func testBulkActionBarSeparatesTheDestructiveButton() throws {
        let scratch = FileManager.default.temporaryDirectory
            .appendingPathComponent("r436-bulk-sep-\(UUID().uuidString)", isDirectory: true)
        try FileManager.default.createDirectory(at: scratch, withIntermediateDirectories: true)
        defer { try? FileManager.default.removeItem(at: scratch) }

        for appearance in [NSAppearance.Name.aqua, .darkAqua] {
            let tag = appearance == .darkAqua ? "dark" : "light"
            guard let fixture = fixtures(appearance: appearance)
                .first(where: { $0.name == "sidebar-multi-select" }) else {
                return XCTFail("\(tag)：找不到 `sidebar-multi-select` ⇒ 这条判据没有对象")
            }
            let file = scratch.appendingPathComponent("multi-\(tag).png")
            _ = try render(fixture, appearance: appearance, to: file)
            guard let data = try? Data(contentsOf: file),
                  let rep = NSBitmapImageRep(data: data), let base = rep.bitmapData else {
                return XCTFail("\(tag)：`sidebar-multi-select` 读不回字节 ⇒ 这条判据没有对象")
            }
            let scale = Double(rep.pixelsWide) / 300.0
            // 头部带：图标实际在 y 112..132pt（批量模式下「已选 N 条」那一行）。
            var trashLeft: Int?
            var redPixels = 0
            for x in 40..<Int(300 * scale) {
                var red = 0
                for y in Int(112 * scale)..<Int(132 * scale) {
                    let o = y * rep.bytesPerRow + x * rep.samplesPerPixel
                    let r = Int(base[o]), g = Int(base[o + 1]), b = Int(base[o + 2])
                    if r > 140 && r > g + 40 && r > b + 40 { red += 1 }
                }
                if red > 0 {
                    redPixels += red
                    if trashLeft == nil { trashLeft = x }
                }
            }
            guard let left = trashLeft else {
                return XCTFail("\(tag)：找不到红色垃圾桶 ⇒ 这一屏没画出来")
            }
            // 分隔线是**发丝线**，不是文字；而侧栏材质本身有渐变（整段相对底色差可以到 20+），
            // 所以不能拿"与远处底色的差"当读数 —— 要**局部对比**：每一列与左右各 4pt 列比，
            // 线是一条窄而深的列，渐变在局部是平的。第一版用远处的底色，刀 M1197 撤掉线仍绿
            // （材质渐变冒充了线），这一版把那条假绿堵上。
            func columnLuma(_ x: Int) -> Double {
                var sum = 0.0
                for y in Int(112 * scale)..<Int(132 * scale) {
                    let o = y * rep.bytesPerRow + x * rep.samplesPerPixel
                    sum += (Double(base[o]) + Double(base[o + 1]) + Double(base[o + 2])) / 3
                }
                return sum / Double(max(1, Int(20 * scale)))
            }
            var separatorDelta = 0.0
            for x in Int(258 * scale)..<Int(263 * scale) {
                let nearL = columnLuma(x - Int(4 * scale))
                let nearR = columnLuma(x + Int(4 * scale))
                separatorDelta = max(separatorDelta, abs(columnLuma(x) - (nearL + nearR) / 2))
            }
            emit("BULK_ACTION_SEPARATOR \(tag) 红墨=\(redPixels) 垃圾桶左=\(String(format: "%.1f", Double(left) / scale))pt "
                  + "分隔带最大差=\(String(format: "%.1f", separatorDelta)) 档=\(String(format: "%.2f", scale))px/pt")
            XCTAssertGreaterThan(redPixels, Int(10 * scale * scale),
                                 "\(tag)：垃圾桶的红像素太少 ⇒ 这一屏没画出来")
            XCTAssertGreaterThan(separatorDelta, 8,
                                 "\(tag)：垃圾桶左侧 12pt 内与底色最大差只有 "
                                 + "\(String(format: "%.1f", separatorDelta)) ⇒ 破坏性动作没有分隔"
                                 + "（发丝线在暗档材质上的局部对比现读 11.9；旧形状 0–1，地板 8 仍有 8 倍余量）")
        }
    }

    /// R437：多文件行展开后的预览必须**站在所属行的文字轴上**。
    ///
    /// 缺陷形状（修之前 `detail-3-files-expanded` 亮档现读）：展开的骷髅条从窗口的
    /// `containerGutter`（20pt）+ 圆角框 20pt 起 ⇒ **40.0pt**，而同一行文件名从
    /// `rowTextLeading` 起 ⇒ **82.0pt**；差 42pt，展开块看起来不属于那一行。
    /// 修法：`expandedContentLeadingInset = rowTextLeading − previewHorizontalInset − containerGutter`，
    /// 只补左侧。判据只读帧：第 0 行文件名左沿 vs 展开内容（骷髅条/那句说明）左沿，差 ≤2.5pt。
    func testExpandedFilePreviewSitsOnTheRowTextAxis() throws {
        let scratch = FileManager.default.temporaryDirectory
            .appendingPathComponent("r437-expanded-axis-\(UUID().uuidString)", isDirectory: true)
        try FileManager.default.createDirectory(at: scratch, withIntermediateDirectories: true)
        defer { try? FileManager.default.removeItem(at: scratch) }

        for appearance in [NSAppearance.Name.aqua, .darkAqua] {
            let tag = appearance == .darkAqua ? "dark" : "light"
            guard let fixture = fixtures(appearance: appearance)
                .first(where: { $0.name == "detail-3-files-expanded" }) else {
                return XCTFail("\(tag)：找不到 `detail-3-files-expanded` ⇒ 这条判据没有对象")
            }
            let file = scratch.appendingPathComponent("expanded-\(tag).png")
            _ = try render(fixture, appearance: appearance, to: file)
            guard let data = try? Data(contentsOf: file),
                  let rep = NSBitmapImageRep(data: data), let base = rep.bitmapData else {
                return XCTFail("\(tag)：`detail-3-files-expanded` 读不回字节 ⇒ 这条判据没有对象")
            }
            let scale = Double(rep.pixelsWide) / 720.0
            func firstInk(fromX: CGFloat, y0: Int, y1: Int) -> Double? {
                for x in Int(fromX * scale)..<Int(600 * scale) {
                    for y in Int(Double(y0) * scale)..<Int(Double(y1) * scale) {
                        let o = y * rep.bytesPerRow + x * rep.samplesPerPixel
                        let r = Int(base[o]), g = Int(base[o + 1]), b = Int(base[o + 2])
                        let bg: (Int, Int, Int) = appearance == .darkAqua ? (50, 50, 50) : (255, 255, 255)
                        if max(abs(r - bg.0), max(abs(g - bg.1), abs(b - bg.2))) > 60 {
                            return Double(x) / scale
                        }
                    }
                }
                return nil
            }
            // 第 0 行文件名在 y 84..100pt；x 从 76 起跳过 34pt 的箭头与 54..72 的类型图标。
            guard let rowText = firstInk(fromX: 76, y0: 84, y1: 100),
                  let content = firstInk(fromX: 20, y0: 120, y1: 220) else {
                return XCTFail("\(tag)：行文字或展开内容读不到 ⇒ 这一屏没画出来")
            }
            emit("EXPANDED_PREVIEW_AXIS \(tag) 行文字左=\(String(format: "%.1f", rowText))pt "
                  + "展开内容左=\(String(format: "%.1f", content))pt 差=\(String(format: "%.1f", abs(rowText - content)))pt")
            XCTAssertGreaterThan(rowText, 60, "\(tag)：行文字左沿读不到（小于 60pt）⇒ 尺没有对象")
            XCTAssertLessThanOrEqual(abs(rowText - content), 2.5,
                                     "\(tag)：展开内容左沿 \(String(format: "%.1f", content))pt 对行文字 "
                                     + "\(String(format: "%.1f", rowText))pt ⇒ 展开块没有站在所属行的文字轴上")
        }
    }

    /// R435：浮层搜索框有字时右侧必须出现一颗清除按钮；空查询时它必须收起来。
    ///
    /// 缺陷形状：主窗口的 `SearchField` 早就有 ×，浮层的主输入框一直没有 —— 打错一个字
    /// 只能全选重打（空结果态那颗「清除搜索」只在 0 条时才出现）。
    /// 判据只读帧：`quickpick-typed`（查询「访达」）与 `quickpick-list`（空查询）在
    /// 搜索框右端 384..406pt × 14..34pt 的墨量；校准带取同一字段左半段（两帧都必有字）。
    func testQuickPickSearchFieldShowsAClearButtonOnlyWhenTyping() throws {
        let scratch = FileManager.default.temporaryDirectory
            .appendingPathComponent("r435-clear-\(UUID().uuidString)", isDirectory: true)
        try FileManager.default.createDirectory(at: scratch, withIntermediateDirectories: true)
        defer { try? FileManager.default.removeItem(at: scratch) }

        for appearance in [NSAppearance.Name.aqua, .darkAqua] {
            let tag = appearance == .darkAqua ? "dark" : "light"
            func ink(_ name: String) throws -> (button: Int, control: Int, rowControl: Int, scale: Double)? {
                guard let fixture = fixtures(appearance: appearance).first(where: { $0.name == name }) else {
                    XCTFail("\(tag)：找不到 `\(name)` ⇒ 这条判据没有对象")
                    return nil
                }
                let file = scratch.appendingPathComponent("\(name)-\(tag).png")
                _ = try render(fixture, appearance: appearance, to: file)
                guard let data = try? Data(contentsOf: file),
                      let rep = NSBitmapImageRep(data: data), let base = rep.bitmapData else {
                    XCTFail("\(tag)：`\(name)` 读不回字节 ⇒ 这条判据没有对象")
                    return nil
                }
                let scale = Double(rep.pixelsWide) / 420.0
                func mass(_ rect: CGRect) -> Int {
                    Self.textInkMass(bytes: base, width: rep.pixelsWide, height: rep.pixelsHigh,
                                     bytesPerRow: rep.bytesPerRow, rect: rect, scale: scale).pixels
                }
                return (mass(CGRect(x: 384, y: 14, width: 22, height: 20)),
                        mass(CGRect(x: 28, y: 14, width: 150, height: 20)),
                        mass(CGRect(x: 40, y: 57, width: 160, height: 13)), scale)
            }
            guard let typed = try ink("quickpick-typed"), let list = try ink("quickpick-list") else { continue }
            let buttonFloor = Int(20.0 * typed.scale * typed.scale)
            emit("QUICKPICK_CLEAR_BUTTON \(tag) typed 按钮带=\(typed.button) 校准=\(typed.control) "
                  + "list 按钮带=\(list.button) 校准=\(list.control) 地板=\(buttonFloor)")
            XCTAssertGreaterThan(typed.control, buttonFloor,
                                 "\(tag)：typed 帧搜索框左半段没有字 ⇒ 这一屏没画出来")
            // R436 修 R435 的红：list 帧的**占位语**在 runner 1x 上读到 0（灰色占位没有墨），
            // 不代表整帧没画 —— 改用同一帧第 0 行标题当校准（它在 1x 上一直是稳的）。
            XCTAssertGreaterThan(list.rowControl, buttonFloor,
                                 "\(tag)：list 帧第 0 行标题没有字 ⇒ 这一屏没画出来")
            XCTAssertGreaterThan(typed.button, buttonFloor,
                                 "\(tag)：有字时搜索框右端只读到 \(typed.button) 颗墨（地板 \(buttonFloor)）⇒ 清除按钮没画出来")
            XCTAssertLessThan(list.button, buttonFloor,
                              "\(tag)：空查询时搜索框右端读到 \(list.button) 颗墨 ⇒ 清除按钮没有收起来")
        }
    }

    /// R433：详情大图必须有一圈**可见的边**（白底图在白底详情里以前整张看不见）。
    ///
    /// 缺陷形状（修之前 `detail-1-image` 亮/暗现读）：大图周围直接是页面底色，
    /// 图外 1–3pt 的带与 20pt 外的页面底色亮度相同（差 0–2）；白底截图完全看不出边界。
    /// 修法：贴合尺寸 + 1pt 中性边（`Color.primary.opacity(VisualTint.chipStroke)`）。
    /// 判据只读帧：先按**色度**找出青色的图片块，量它左沿外 1–3pt 的带与页面底色的亮度差；
    /// 旧形状差 0，新形状 ≥10（亮/暗两档都读得出）。
    func testDetailImagePreviewHasAVisibleEdge() throws {
        let scratch = FileManager.default.temporaryDirectory
            .appendingPathComponent("r433-image-edge-\(UUID().uuidString)", isDirectory: true)
        try FileManager.default.createDirectory(at: scratch, withIntermediateDirectories: true)
        defer { try? FileManager.default.removeItem(at: scratch) }

        for appearance in [NSAppearance.Name.aqua, .darkAqua] {
            let tag = appearance == .darkAqua ? "dark" : "light"
            guard let fixture = fixtures(appearance: appearance)
                .first(where: { $0.name == "detail-1-image" }) else {
                return XCTFail("\(tag)：找不到 `detail-1-image` ⇒ 这条判据没有对象")
            }
            let file = scratch.appendingPathComponent("detail-1-image-\(tag).png")
            _ = try render(fixture, appearance: appearance, to: file)
            guard let data = try? Data(contentsOf: file),
                  let rep = NSBitmapImageRep(data: data), let base = rep.bitmapData else {
                return XCTFail("\(tag)：`detail-1-image` 读不回字节 ⇒ 这条判据没有对象")
            }
            let scale = Double(rep.pixelsWide) / 720.0
            func luma(_ x: Int, _ y: Int) -> Double {
                let o = y * rep.bytesPerRow + x * rep.samplesPerPixel
                return (Double(base[o]) + Double(base[o + 1]) + Double(base[o + 2])) / 3.0
            }
            // 青色块：只认夹具那张 systemTeal 大图；扫描从 y=150px（正文区）起，
            // 把状态条左侧那颗彩色来源图标排除在外（否则 bbox 是两个块的并集）。
            var minX = rep.pixelsWide, maxX = -1, minY = rep.pixelsHigh, maxY = -1
            for y in min(rep.pixelsHigh, 150)..<rep.pixelsHigh {
                for x in 0..<rep.pixelsWide {
                    let o = y * rep.bytesPerRow + x * rep.samplesPerPixel
                    let r = Int(base[o]), g = Int(base[o + 1]), b = Int(base[o + 2])
                    // 只认夹具那张 systemTeal 大图（26,188,196）：来源 App 小图标也是彩色，
                    // 用宽泛色度条件会把状态条那颗图标一起圈进来（本轮第一版就这么错了）。
                    if r < 90 && g > 150 && b > 150 {
                        minX = min(minX, x); maxX = max(maxX, x)
                        minY = min(minY, y); maxY = max(maxY, y)
                    }
                }
            }
            guard maxX > minX, maxY > minY else {
                return XCTFail("\(tag)：帧里找不到青色图片块 ⇒ 这一屏没画出来，边判据没有对象")
            }
            let midY = (minY + maxY) / 2
            var page = 0.0
            for x in max(0, minX - Int(14 * scale))..<max(1, minX - Int(8 * scale)) {
                page += luma(x, midY)
            }
            page /= Double(max(1, Int(6 * scale)))
            var maxDelta = 0.0
            for offset in 1...3 {
                let x = max(0, minX - Int(Double(offset) * scale))
                maxDelta = max(maxDelta, abs(luma(x, midY) - page))
            }
            emit("DETAIL_IMAGE_EDGE \(tag) 图框=\(minX)..\(maxX)×\(minY)..\(maxY)px "
                  + "页底=\(String(format: "%.1f", page)) 边带最大差=\(String(format: "%.1f", maxDelta)) "
                  + "档=\(String(format: "%.2f", scale))px/pt")
            XCTAssertGreaterThan(page, 0, "\(tag)：页面底色的亮度读不出来 ⇒ 尺没有对象")
            XCTAssertGreaterThan(maxDelta, 10,
                                 "\(tag)：图沿外 1–3pt 与页面底色的最大亮度差只有 "
                                 + "\(String(format: "%.1f", maxDelta)) ⇒ 图没有可见的边")
        }
    }

    /// R432：设置页「不记录这些 App 的复制」默认名单的行首必须是一枚**图标**，不是裸 ID 文本。
    ///
    /// 缺陷形状（修之前亮/暗现读）：每行都是 `默认排除：com.…`，
    /// 行首第一段是**「默认排除：」五个字**（墨宽 **42.5pt**，逐行同值）；
    /// 用户认不出是哪个 App。修后行首是 10–14pt 的图标段。
    /// 修法：每行 = 16pt 图标 + 6pt 空隙 + 应用名 + bundle ID。判据只读帧：
    /// 每行第一段墨宽（间隙 5pt 断开）必须是图标那一段（≤30pt）；校准=该行有字。
    ///
    /// R433 修 R432 的红：高夹具（720×1040）在 runner 1x 上整帧不画（行数 0，同 1100pt 那族），
    /// 于是这一格在 CI 上没有对象。改用 540 高的 `settings-privacy`（1x 能画、首屏约 5 行）：
    /// 本机 2x 与 runner 1x 都读得到行首图标段，覆盖从"九行"降到"首屏三行以上"，
    /// 换来的是 CI 上真有像素证人。
    func testExcludedAppsStartWithAnIconInsteadOfRawIDs() throws {
        let scratch = FileManager.default.temporaryDirectory
            .appendingPathComponent("r432-excluded-icon-\(UUID().uuidString)", isDirectory: true)
        try FileManager.default.createDirectory(at: scratch, withIntermediateDirectories: true)
        defer { try? FileManager.default.removeItem(at: scratch) }

        var assertedTags = 0
        var namedNotRun = 0
        for appearance in [NSAppearance.Name.aqua, .darkAqua] {
            let tag = appearance == .darkAqua ? "dark" : "light"
            guard let fixture = fixtures(appearance: appearance)
                .first(where: { $0.name == "settings-privacy" }) else {
                return XCTFail("\(tag)：找不到 `settings-privacy` ⇒ 这条判据没有对象")
            }
            let file = scratch.appendingPathComponent("privacy-\(tag).png")
            _ = try render(fixture, appearance: appearance, to: file)
            guard let data = try? Data(contentsOf: file),
                  let rep = NSBitmapImageRep(data: data), let base = rep.bitmapData else {
                return XCTFail("\(tag)：`settings-privacy` 读不回字节 ⇒ 这条判据没有对象")
            }
            let scale = Double(rep.pixelsWide) / 720.0
            let x0: CGFloat = 150, x1: CGFloat = 420
            // 行带：x 150..420、默认名单从 y≈390 起；先找有墨的连续像素行，再按 9 行取前几段。
            var bands: [ClosedRange<Double>] = []
            var start: Double?
            for y in 394...528 {   // 394 之前是上面那句说明；528 是 540 高窗口里最后一行可见位置
                let rect = CGRect(x: x0, y: CGFloat(y), width: x1 - x0, height: 1)
                let ink = Self.textInkMass(bytes: base, width: rep.pixelsWide, height: rep.pixelsHigh,
                                           bytesPerRow: rep.bytesPerRow, rect: rect, scale: scale).pixels
                if ink > 0 {
                    if start == nil { start = Double(y) }
                } else if let s = start {
                    bands.append(s...Double(y - 1))
                    start = nil
                }
            }
            if let s = start { bands.append(s...528) }
            let judged = bands.prefix(6)
            var firstWidths: [Double] = []
            var inks: [Int] = []
            for band in judged {
                let rect = CGRect(x: x0, y: CGFloat(band.lowerBound),
                                  width: x1 - x0, height: CGFloat(band.upperBound - band.lowerBound + 1))
                let mass = Self.textInkMass(bytes: base, width: rep.pixelsWide, height: rep.pixelsHigh,
                                            bytesPerRow: rep.bytesPerRow, rect: rect, scale: scale)
                inks.append(mass.pixels)
                let runs = Self.inkRuns(bytes: base, width: rep.pixelsWide, height: rep.pixelsHigh,
                                        bytesPerRow: rep.bytesPerRow, rect: rect, scale: scale, gap: 5)
                firstWidths.append(runs.first?.width ?? 0)
            }
            let widthText = firstWidths.map { String(format: "%.1f", $0) }.joined(separator: ",")
            emit("EXCLUDED_APP_ROW \(tag) 行数=\(bands.count) 判=\(judged.count) "
                  + "首段宽=[\(widthText)] 行墨=\(inks)")
            // R434 修 R432/R433 的红：runner 1x 上**设置页内容列整列平涂**（不是这一屏特有 ——
            // `CAPTION_JUDGED` 连续多跑都只有 6/17 条设置页探针判成，其余走 machineFlat），
            // 所以列表行在这台机器的 1x 产物里没有墨可判。具名 NOT-RUN，2x 断言不动。
            if scale < 1.5 {
                namedNotRun += 1
                emit("EXCLUDED_APP_ROW_NOT_RUN=runner-1x-settings-content-plain \(tag) "
                      + "行数=\(bands.count) ⇒ 设置内容列在 1x 平涂（CAPTION_JUDGED 6/17 同证）；"
                      + "本机 2x 才判 5 行、首段 10–14pt")
                continue
            }
            XCTAssertGreaterThanOrEqual(judged.count, 3,
                                        "\(tag)：只找到 \(bands.count) 行默认排除项 ⇒ 这一格没有对象")
            for (index, ink) in inks.enumerated() {
                XCTAssertGreaterThan(ink, 20,
                                     "\(tag)：第 \(index) 行没有字 ⇒ 这一行在这台机器上没画出来")
            }
            for (index, width) in firstWidths.enumerated() {
                XCTAssertTrue(width >= 5 && width <= 30,
                              "\(tag)：第 \(index) 行首段墨宽 \(String(format: "%.1f", width))pt"
                              + " ⇒ 行首不是一枚图标（旧形状首段是「默认排除：」=42.5pt）")
            }
            assertedTags += 1
        }
        XCTAssertEqual(assertedTags + namedNotRun, 2,
                       "两档里有一档既没判也没登记 ⇒ 这条判据没有免检出口")
        XCTAssertTrue(assertedTags == 2 || namedNotRun == 2,
                      "同一台机器上两档必须走同一条路（判了 \(assertedTags)、具名 NOT-RUN \(namedNotRun)）")
    }

    /// R74 / U-115：浮层那一档悬停**不加淡入** —— 这条决定从今天起有读数，不是"我觉得"。
    ///
    /// 判的问题：给那层灰配一条 100ms 的淡入，用户打字时看到的是"过渡走完然后停住"，
    /// 还是"一直在打断重来"？后者 ⇒ 不加（淡入会把一次静置的描色变成呼吸）；
    /// 前者 ⇒ 我给 R67 的那句理由是错的，该加就得加。
    ///
    /// 量法走产品真路径：`queryChanged(_:)` 一个前缀一个前缀地喂，数两件**分开的**事：
    ///   ① 整列变了几个前缀（候选集往下切一层）；
    ///   ② 指针那一格（固定第 2 行）换了几次记录，含"那一行没了"。
    /// 分开打是因为它们证的不是同一件事：**整列动 ≠ 指针那一格动**，
    /// 而淡入的害处只在"指针那一格一直在换人"时才成立。断言用**比例**不用绝对次数：
    /// 打字速度、查询长度都不该由测试替产品决定。
    ///
    /// **两个语料都要量，因为第一个把我为 R67 写的那句理由证伪了**（U-128）：帧夹具那 5 条里
    /// "这是一段用于"只命中 1 条 ⇒ 6 个前缀列表只变 1 次 ⇒ "打字时整列一直在动"在这个语料上
    /// **不成立**。它不成立不是因为产品不动，是因为**这个夹具只剩一条命中** —— 一个只剩一条
    /// 结果的搜索框本来就不该重排。于是补上"同一条内容被反复复制"那一族真实形状（长度递增的
    /// 嵌套前缀），那才是浮层打字时的日常：每多打一个字，候选集往下切一层。
    ///
    /// 所以这一条的结论是**按语料限定**的，不是"任何情况下都不该加"：在嵌套语料上淡入的害处量得到，
    /// 在只命中一条的语料上量不到。写成限定式而不是全称式，是因为 U-115 要区分的正是
    /// "做过决定"与"没做过决定"，而第三种错更贵：**只在自己的夹具上成立的理由**（看着像证据）。
    func testOverlayHoverHasNoFadeAndTheReasonIsMeasuredOnTwoCorpora() throws {
        func reflow(store: HistoryStore, query: String) -> (prefixes: Int, changed: Int, churn: Int, rows: Int) {
            let build = QuickPickCapturePanel.builder(store: store, query: "")
            guard let panel = build(), let content = panel.contentView else { return (-1, -1, -1, -1) }
            panel.setFrameOrigin(NSPoint(x: -20009, y: -20009))
            panel.orderFrontRegardless()
            RunLoop.main.run(until: Date().addingTimeInterval(0.2))
            defer { panel.orderOut(nil) }
            guard let table = Self.productTable(in: content),
                  let controller = table.delegate as? QuickPickController else { return (-2, -2, -2, -2) }
            func visibleTitles() -> [String] {
                table.layoutSubtreeIfNeeded()
                return (0..<table.numberOfRows).compactMap { row in
                    (table.view(atColumn: 0, row: row, makeIfNecessary: true) as? NSTableCellView)?
                        .textField?.stringValue
                }
            }
            var prefixes: [String] = []
            var growing = ""
            for character in query { growing.append(character); prefixes.append(growing) }
            // 指针那一格固定在第 2 行：打字时鼠标通常是停着的，而 `mouseMoved` 是唯一能把那层灰
            // 补回来的入口 ⇒ "这一格此刻是谁"只由列表自己决定，不由测试决定。
            // 用空串而不是 nil 当"那一行没了"：让它和"换了别的记录"在同一个轴上可比。
            let pointerRow = 2
            var previous = visibleTitles()
            var atPointer = pointerRow < previous.count ? previous[pointerRow] : ""
            var changed = 0
            var churn = 0
            for prefix in prefixes {
                controller.queryChanged(prefix)
                let now = visibleTitles()
                if now != previous { changed += 1 }
                previous = now
                let nowPointer = pointerRow < now.count ? now[pointerRow] : ""
                if nowPointer != atPointer { churn += 1 }
                atPointer = nowPointer
            }
            return (prefixes.count, changed, churn, previous.count)
        }
        // 两个语料的分工写在上面那段文档里：帧夹具那条证伪了 R67 的理由（U-128），
        // 嵌套前缀那条才是浮层打字时的日常。
        let visualFixtureQuery = "这是一段用于"
        let query = "一二三四五六七八"
        let visual = reflow(store: makePopulatedStore(), query: visualFixtureQuery)
        let nested = reflow(store: makeNestedPrefixStore(), query: query)
        emit("OVERLAY_HOVER_REFLOW 帧夹具 前缀数=\(visual.prefixes) 整列变了=\(visual.changed) 次 "
            + "指针那格换了=\(visual.churn) 次 最终行数=\(visual.rows) "
            + "｜嵌套前缀语料 前缀数=\(nested.prefixes) 整列变了=\(nested.changed) 次 "
            + "指针那格换了=\(nested.churn) 次 最终行数=\(nested.rows)（指针=第 2 行，那一行没了也算换）")
        XCTAssertGreaterThanOrEqual(nested.prefixes, 3, "查询太短 ⇒ 这条判据没有对象")
        XCTAssertGreaterThanOrEqual(nested.changed, nested.prefixes - 1,
            "嵌套前缀语料里 \(nested.prefixes) 个前缀只让列表变了 \(nested.changed) 次 ⇒ "
                + "\"打字时整列一直在动\"这个理由不成立：淡入大部分时间能走完，"
                + "那不给悬停加过渡就只是没做，而不是做过决定（U-115 要的就是这个区分）。"
                + "注意 R67 当时写的就是这句话，而它在**帧夹具那个只命中一条的语料**上是错的（U-128）")
        XCTAssertLessThan(visual.changed, visual.prefixes - 1,
            "帧夹具那个语料什么时候变成\"每个字都重排\"了，上面那条对照就失去意义了 —— "
                + "它存在的理由就是\"一个只剩一条命中的搜索框不重排\"")
        XCTAssertGreaterThanOrEqual(nested.churn, nested.prefixes / 2,
            "整列变了 \(nested.changed) 次，但指针那一格（第 2 行）只换了 \(nested.churn) 次记录 ⇒ "
                + "那层灰基本一直停在同一条记录上，淡入走一次就能停住 —— 于是「淡入会变成呼吸」"
                + "这个**唯一的害处**就不成立了，这一格该重判（多半该加）。"
                + "两个数分开断言是因为它们证的不是同一件事：整列动 ≠ 指针那一格动")
        XCTAssertLessThan(visual.churn, visual.prefixes / 2,
            "帧夹具那一格换了 \(visual.churn) 次记录，快到每个前缀一次 ⇒ 这个语料被改成了嵌套形状，"
                + "它就不再是**反面语料**了：两个语料的对照塌成一个，"
                + "上面那条「整列一直在动」又变回只在一种形状上成立（U-128 那一课）")
        // 决定钉在源码上：这一族"声明了过渡但没人驱动"与"该动的没动"是同一枚硬币的两面，
        // 而这里我们**主动选择不动** ⇒ 必须有一条守卫，否则下一次有人顺手加 `.animation`
        // 或 `animator()` 时，没人知道这一格是量过才决定不加的。
        let rowSource = Self.codeOnly(try productSource(named: "Managers/QuickPickController.swift"))
        let hoverPart = rowSource.components(separatedBy: "final class QuickPickRowView").last ?? ""
        for forbidden in ["animator(", "NSAnimationContext", "animate(with:"] {
            XCTAssertFalse(hoverPart.contains(forbidden),
                "悬停那一档开始出现 `\(forbidden)` 了 ⇒ 这一格的决定是 R74 量过才做的"
                    + "（嵌套前缀语料里 \(nested.prefixes) 个前缀有 \(nested.changed) 次让整列重排、"
                    + "\(nested.churn) 次让指针那一格换人），"
                    + "要改这个决定请先重新量一遍，而不是顺手加一条动画")
        }
        // 第二条守卫钉的是**理由的机制**，不是结论：这一格不加淡入，靠的是「行重排会把那层灰拆掉，
        // 而把它补回来的唯一入口是指针事件」。哪天 `rebuildRows` 不再拆了（改成按指针位置重算、
        // 或把 hover 收进模型），我这套论证就过期 —— 那种红**不代表产品坏了**，
        // 代表「这一格该重判（也许真该加淡入）」。写清这一点是因为上一条守卫最容易被误修：
        // 看到红就顺手把 `clearHover` 加回去，等于用测试替产品保住一句已经不再成立的理由。
        let rebuild = Self.functionBody(named: "private func rebuildRows()", in: rowSource)
        XCTAssertTrue(rebuild.contains("clearHover"),
            "`rebuildRows` 里已经不叫 `clearHover` 了 ⇒ 「打字时那层灰会被拆掉、淡入每次都被打断」失去机制支撑"
                + "（实测：\(nested.prefixes) 个前缀让指针那一格换 \(nested.churn) 次人）。"
                + "这一条红的含义是「决定该重判」，不是「产品坏了」")
        // 扫描器自己的正/反对照（R71/M382 那一族的规矩：只测「该红的没红」不够，
        // 得证明这条网真的在网，而且网不住的时候会说「网住了」）。
        XCTAssertFalse(rebuild.isEmpty,
                       "扫不到 `rebuildRows` 的函数体 ⇒ 上面那条守卫是空转的（永远绿）")
        XCTAssertTrue(rebuild.contains("enumerateAvailableRowViews"),
                      "扫到的 `rebuildRows` 体里没有 `enumerateAvailableRowViews` ⇒ 截取的范围不对"
                          + "（多半在方法体之前就断了），那条守卫量的不是这个函数")
        XCTAssertFalse(rebuild.contains("final class QuickPickRowView"),
                       "从 `rebuildRows` 往后截到了类声明 ⇒ 截取器没在方法结尾断开，把文件后半当成了方法体 —— "
                           + "那 `contains(clearHover)` 判的就不再是这一个函数（这一条是截取器的**右边界**对照）")
        XCTAssertTrue(Self.functionBody(named: "private func definitelyNotInThisFile()", in: rowSource).isEmpty,
                      "一个不存在的函数名也能扫出东西 ⇒ 这个截取器「永远看得见」，"
                          + "上面几条源码守卫一起退化成噪声计数器")
    }

    /// 焦点那条轴的**处置**（R80）：把"这台机器判不了"这件事从一个 `if` 里提成一个**可测的函数**。
    ///
    /// 为什么要提成函数：这一整条判据只有 2× 那一台机器会走"正常"那一支，
    /// 1× 上的两支在本机**永远不会被执行** —— 一个本机跑不到的分支就是没有红钉着的分支，
    /// 而它恰恰是"能不能把一条轴说成没跑"的那道门（账本里"机器前提把该红的说成没跑"那一族）。
    /// 提出来之后它可以被合成数字直接打：三种处置各一格，改错一个 `>=` 就会红。
    enum FocusAxisDisposition: Equatable {
        /// 焦点这一档看得见在让位 ⇒ 照正常那几条判。
        case judged
        /// 同一把尺在同一格读得出别的成因在搬动，而聚焦不动 ⇒ 这台机器的 AppKit 不调淡占位符。
        case behaviorAbsentOnThisMachine
        /// 连"撤掉整串占位字"都读不出搬动 ⇒ 这一格对这把尺整体失明，判不判都是空的。
        case channelBlindOnThisMachine
    }

    /// 判据地板 = `max(常数地板, 噪声倍数 × 这台机器上同态重拍的噪声)`（R80，R38 的形状）。
    /// 单独提成函数是为了它能被**合成数字**打：本机噪声实测 0.0pt² ⇒ 那一条乘在这里永远乘出 0，
    /// 没有这一格，`focusNoiseMargin` 就是一个没有红的常数（账本里"地板从表推导"那一族的下半场：
    /// 推导出来了，但没人钉着推导的那一步）。
    static func focusFloorPointsSquared(noisePt2: Double) -> Double {
        max(focusMinMovedPointsSquared, focusNoiseMargin * noisePt2)
    }

    /// 处置 = 三个读数之间的关系，**不看它是哪台机器**（scale 由调用点单独决定放行还是红）。
    /// 两条地板分开给：`floorPt2` 是判据地板（含噪声余量），`competenceFloorPt2` 是证人地板 ——
    /// 它们不许合成一个数（R77 那一课：同一个词在两个判据里含义不同就别统一）。
    static func focusDisposition(focusMovedPt2: Double, floorPt2: Double,
                                 dimFraction: Double, minDimFraction: Double,
                                 competencePt2: Double, competenceFloorPt2: Double) -> FocusAxisDisposition {
        if focusMovedPt2 >= floorPt2 && dimFraction >= minDimFraction { return .judged }
        return competencePt2 >= competenceFloorPt2
            ? .behaviorAbsentOnThisMachine : .channelBlindOnThisMachine
    }

    /// R80 · 那把尺的**处置**三支各钉一格。
    ///
    /// 这三格是本轮唯一能给 1× 那两支作证的東西：本机永远走"judged"，
    /// 所以那两支在这台机器上**没有任何一条红**会跟着它们坏 —— 不单独钉就等于没写。
    func testFocusAxisDispositionIsATruthTable() throws {
        // 这几格**引用常量本身**，不引用我手抄的数 —— 否则抬高某道地板会只红在判据上，
        // 而"这条轴能不能被说成没跑"那扇门（在 1× 上）永远没有红钉着（R78 的 M415 同一课）。
        let floor = Self.focusMinMovedPointsSquared
        let competenceFloor = Self.competenceMinMovedPointsSquared
        let minFraction = Self.focusMinDimFraction
        func disposition(focus: Double, fraction: Double, competence: Double) -> FocusAxisDisposition {
            Self.focusDisposition(focusMovedPt2: focus, floorPt2: floor, dimFraction: fraction,
                                  minDimFraction: minFraction, competencePt2: competence,
                                  competenceFloorPt2: competenceFloor)
        }
        // 格①：本机那一遍的真实读数（亮档 98.7pt² / 占比 0.367 / 证人臂 268.7）⇒ judged
        XCTAssertEqual(disposition(focus: 98.7, fraction: 0.367, competence: 268.7), .judged,
                       "本机实测那一组数被判成'判不了' ⇒ 这条轴的正常那一支从此没人走")
        // 格②：runner 预计那一组（搬动 1.3、占比 0.014）而证人臂读得出东西 ⇒ 尺不瞎
        // 这里的 268.7 是**本机实测的证人臂读数**（`QUICKPICK_FOCUS_INK` 亮档那一列），
        // 不是随手写的数：这一格钉的正是"证人地板**现在这个大小**能不能让实测的证人过关"，
        // 所以它必须引用测量、不能引用常数 —— 写成 `competenceFloor + 49` 的话，
        // 有人把地板抬到十万也照样绿（M431 第一次就是这么逃的，本轮自己抓到）。
        XCTAssertEqual(disposition(focus: 1.3, fraction: 0.014, competence: 268.7),
                       .behaviorAbsentOnThisMachine,
                       "证人臂明明读得出别的成因在搬动，却把这一档说成'通道失明' ⇒ 这条缺席是在替产品开脱")
        // 格③：搬动与证人**都**读不出 ⇒ 只有这一支才允许说"这一格对这把尺看不见"
        XCTAssertEqual(disposition(focus: 1.3, fraction: 0.014, competence: competenceFloor - 0.1),
                       .channelBlindOnThisMachine,
                       "两条证人臂都过不了地板却仍被判成'这台机器不调淡' ⇒ 那是拿'行为没有'冒充'通道看不见'，"
                           + "反过来说就是：把一条本该红的轴说成没跑")
        // 格④：边界 —— 正好等于两道地板的不许算不过（`>=` 被写成 `>` 这一格就红）
        XCTAssertEqual(disposition(focus: floor, fraction: minFraction, competence: competenceFloor),
                       .judged,
                       "正好等于地板的必须算过 ⇒ 边界那一档被写成 `>` 之后，读数恰好在地板上的机器会说'看不见'")
        // 格⑤：占比单独承重 —— 搬动量够、占比不够 ⇒ 不许 judged（那是一条轴没在干活）
        XCTAssertNotEqual(disposition(focus: floor + 1, fraction: minFraction - 0.01,
                                      competence: competenceFloor), .judged,
                          "搬动量过线就判得出 ⇒ `focusMinDimFraction` 那一道没人钉，"
                              + "整格墨变淡到一半也能被读成'焦点在让位'")
        // 地板推导那一半：本机噪声是 0 ⇒ 乘法在这里永远乘出 0，必须用合成数字钉住它
        XCTAssertEqual(Self.focusFloorPointsSquared(noisePt2: 0), floor, accuracy: 0.001,
                       "噪声为 0 时地板应该回到常数地板")
        XCTAssertEqual(Self.focusFloorPointsSquared(noisePt2: floor), floor * Self.focusNoiseMargin,
                       accuracy: 0.001,
                       "噪声等于地板时判据地板必须抬高 `focusNoiseMargin` 倍 —— 这一条不许靠注释，"
                           + "它钉的是『地板从这一台机器的噪声推导』那句话里的那个系数")
        XCTAssertGreaterThan(Self.focusFloorPointsSquared(noisePt2: 5),
                             Self.focusFloorPointsSquared(noisePt2: 1),
                             "地板不随噪声抬高 ⇒ 一台抖动大的机器会把噪声当成'焦点搬动了'")
        emit("FOCUS_DISPOSITION_TRUTH_TABLE judged/behaviorAbsent/channelBlind/边界/占比=5 格 "
            + "+ 地板随噪声=3 格 ⇒ 地板=\(floor)pt² 证人=\(competenceFloor)pt² 占比=\(minFraction)")
    }

    ///
    /// 为什么必须**合成夹具**而不是拿帧来判：本轮要钉的性质是"同一个物理变化在 1× 与 2×
    /// 上给出同一个数"，而这条只能靠**构造**出来 —— 我手上没有第二台机器，
    /// runner 的那一遍读数要等 CI（R70 那一课的对称：能被自己造出来的性质不等 CI）。
    /// 夹具是**直接写字节**的（`flatRep` 那一族的原因同样成立：`setColor(_:atX:y:)`
    /// 在整数格式位图上不落地、而且不报错，而尺子的夹具读到 0 最容易被读成"没差别"）。
    ///
    /// 夹具的形状：一张 **100×20pt** 的图，两帧各自**整张一块均匀的墨**（⑤ 那格单独把
    /// 第二帧的右半改成另一个 alpha）。期望值全是解析数：
    ///   面积 = 100×20 = 2000pt²；每像素动 Δ ⇒ 搬动 = 2000×Δ÷255。
    ///   ② Δalpha=100 ⇒ **784.31**；③ 黑翻蓝（Δ蓝=255，alpha 不变）⇒ **2000.00**；
    ///   ⑤ 右半 1000pt² 动 100 ⇒ 左读 **0**、右读 **392.16**；
    ///   ⑥ Δ=1 ⇒ **0**（地板下）；⑦ Δ=3 ⇒ **23.53**（地板上）；
    ///   ⑨ 单帧 alpha=200 整张 ⇒ **1568.63**；⑧ 旧尺数像素 ⇒ **2000×缩放²**。
    ///
    /// 九个格子各拦一种错：
    ///   ① `same` —— 自己减自己 = 0（拦"尺恒开"）。
    ///   ② `alphaDim` —— 只在 alpha 上动的一整块墨：**两档缩放必须给出同一个 pt²**。
    ///      这一格是整轮的性质所在（R38：地板不能跟着像素网格变）。
    ///   ③ `colorOnly` —— 全不透明、只在蓝通道上动 ⇒ 必须读得出（R77 并集语义的另一半；
    ///      一把只读 alpha 的尺在这里给 0，那一族的后果在 BACKLOG 108）。
    ///   ④ `invisible` —— α 恒 0 而 RGB 不同（预乘格式里的非法态，故意造出来）⇒ 必须读成 0，
    ///      这条钉的是尺子里那句"α=0 就当没画"的夹紧：通道哪天换了非预乘格式，
    ///      不夹紧就会把"根本没画"的像素算成搬动过的墨（R77 那族假阳性的镜像）。
    ///   ⑤ `position` —— 变化只在右半 ⇒ 量左半那块矩形必须读 0（位置同一性，不是"有没有变化"）。
    ///   ⑥⑦ `underFloor` / `overFloor` —— 每像素差 1 与差 3：**成对**给出，
    ///      这样 `noiseFloor` 不是一句注释而是一道有两边的门（只给一边就能被抵消）。
    ///   ⑧ **本轮换尺的理由本身**：同一件物理变化在旧那把尺上按 `缩放²` 变
    ///      （2000 个像素 vs 8000 个）。那道 `≥500 个像素` 的地板在两台机器上量的不是同一件事
    ///      ⇒ R76 那句"本机 1797 / runner 0"里最多 3/4 是网格，剩下那 1/4 才是交给 CI 去分的问题。
    ///   ⑨ `inkPointsSquared` —— 单帧墨面积在两种网格下同一个 pt²（占比那条判据的分母）。
    func testMovedInkRulerIsGridNormalizedAndReadsBothAxes() throws {
        // 一帧一块均匀的墨：`from*` 是第一帧、`to*` 是第二帧（**不是**同一帧的左右两半 ——
        // 第一版我把参数写成 left/right，然后把整张一涂的夹具当成"左半有墨"来算期望值，
        // ②③⑦⑧⑨ 五格集体差了两倍；这一格留在这里当反面教材，因为它是"参数名替事实说话"）。
        func makeRep(scale: Int, alpha: Int, blue: Int) -> NSBitmapImageRep {
            let w = 100 * scale, h = 20 * scale
            let rep = NSBitmapImageRep(bitmapDataPlanes: nil, pixelsWide: w, pixelsHigh: h,
                                       bitsPerSample: 8, samplesPerPixel: 4, hasAlpha: true,
                                       isPlanar: false, colorSpaceName: .deviceRGB,
                                       bytesPerRow: 4 * w, bitsPerPixel: 32)!
            guard let data = rep.bitmapData else {
                XCTFail("造不出夹具位图 ⇒ 这把尺的真值表没有对象")
                return rep
            }
            for y in 0..<h {
                for x in 0..<w {
                    let o = y * rep.bytesPerRow + x * 4
                    // 整块都写成同样的字节：**不给抗锯齿**，这几格要的是"整块墨"的形状。
                    data[o] = 0
                    data[o + 1] = 0
                    data[o + 2] = UInt8(blue)
                    data[o + 3] = UInt8(alpha)
                }
            }
            return rep
        }
        func flatPair(scale: Int, fromAlpha: Int, toAlpha: Int,
                      toBlue: Int = 0) -> (NSBitmapImageRep, NSBitmapImageRep) {
            (makeRep(scale: scale, alpha: fromAlpha, blue: 0),
             makeRep(scale: scale, alpha: toAlpha, blue: toBlue))
        }
        var readings: [String] = []
        for scale in [1, 2] {
            let w = 100 * scale, h = 20 * scale
            let wholeRect = CGRect(x: 0, y: 0, width: w, height: h)
            func moved(_ pair: (NSBitmapImageRep, NSBitmapImageRep), _ rect: CGRect) -> Double {
                Self.movedInkPointsSquared(pair.0, pair.1, rect: rect, scale: scale)
            }
            // ①
            XCTAssertEqual(moved(flatPair(scale: scale, fromAlpha: 200, toAlpha: 200), wholeRect),
                           0, accuracy: 0.001, "\(scale)×：自己减自己必须读 0")
            // ②
            let dim = flatPair(scale: scale, fromAlpha: 200, toAlpha: 100)
            let movedDim = moved(dim, wholeRect)
            XCTAssertEqual(movedDim, 784.31, accuracy: 1.0,
                "\(scale)×：2000pt² 的墨从 alpha 200 掉到 100，搬动量必须 ≈784.31pt² "
                    + "（实测 \(String(format: "%.2f", movedDim))）⇒ 这个数一旦跟着缩放走，"
                    + "判据地板就又是『一台机器的读数当另一台的地板』（R38）")
            // ③ 只在蓝通道上动、alpha 拉满：一把只读 alpha 的尺在这里给 0
            let color = flatPair(scale: scale, fromAlpha: 255, toAlpha: 255, toBlue: 255)
            let movedColor = moved(color, wholeRect)
            XCTAssertEqual(movedColor, 2000.0, accuracy: 1.0,
                "\(scale)×：全不透明的黑翻成蓝，搬动量必须 ≈2000pt²（实测 \(String(format: "%.2f", movedColor))）"
                    + "⇒ 读到 0 就是这把尺**只认 alpha**，那一族的后果写在 BACKLOG 108")
            // ④ alpha 恒 0 而 RGB 不同 ⇒ 合成到底上是同一块 ⇒ 必须 0
            let ghost = flatPair(scale: scale, fromAlpha: 0, toAlpha: 0, toBlue: 255)
            let movedGhost = moved(ghost, wholeRect)
            XCTAssertEqual(movedGhost, 0, accuracy: 0.001,
                "\(scale)×：两帧都是全透的（alpha=0），RGB 再怎么不同也**没画** ⇒ 必须读 0，"
                    + "否则这把尺会把『看不见』的东西算成视觉后果")
            // ⑤ 变化只在右半 ⇒ 量左半那块矩形必须读 0（位置同一性）
            let right = flatPair(scale: scale, fromAlpha: 200, toAlpha: 200)
            if let data = right.1.bitmapData {
                for y in 0..<h {
                    for x in (50 * scale)..<w {
                        data[y * (4 * w) + x * 4 + 3] = 100
                    }
                }
            }
            let leftHalf = CGRect(x: 0, y: 0, width: 50 * scale, height: h)
            let rightHalf = CGRect(x: 50 * scale, y: 0, width: 50 * scale, height: h)
            let movedLeft = moved(right, leftHalf)
            let movedRight = moved(right, rightHalf)
            XCTAssertEqual(movedLeft, 0, accuracy: 0.001,
                "\(scale)×：变化明明在右半，量左半却读出 \(String(format: "%.2f", movedLeft))pt² ⇒ "
                    + "矩形没起作用，这把尺会把『动在别处』当成『动在这一格』")
            XCTAssertEqual(movedRight, 392.16, accuracy: 1.0,
                "\(scale)×：右半那 1000pt² 的墨掉一半，应该 ≈392.16pt²（实测 \(String(format: "%.2f", movedRight))）")
            // ⑥⑦ 噪声地板两边各一格：每像素差 1（<2，必须不算）与差 3（>2，必须算）
            let movedUnder = moved(flatPair(scale: scale, fromAlpha: 200, toAlpha: 199), wholeRect)
            let overPair = flatPair(scale: scale, fromAlpha: 200, toAlpha: 197)
            let movedOver = moved(overPair, wholeRect)
            XCTAssertEqual(movedUnder, 0, accuracy: 0.001,
                "\(scale)×：每像素只差 1/255 必须被 `noiseFloor` 挡掉（实测 \(movedUnder)）⇒ "
                    + "地板没有下边这一格，它就等于不存在")
            XCTAssertGreaterThan(movedOver, 0,
                "\(scale)×：每像素差 3/255 必须过 `noiseFloor` —— 地板只有一边就是一道能被抵消的门")
            XCTAssertEqual(movedOver, 23.53, accuracy: 0.5,
                "\(scale)×：2000pt² 每像素动 3/255 ⇒ ≈23.53pt²（实测 \(String(format: "%.2f", movedOver))）")
            // ⑨ 单帧墨面积（占比那条判据的分母）
            let ink = Self.inkPointsSquared(dim.0, rect: wholeRect, scale: scale)
            XCTAssertEqual(ink, 1568.63, accuracy: 1.0,
                "\(scale)×：整张 2000pt²、alpha=200 的墨，面积必须 ≈1568.63pt² "
                    + "（实测 \(String(format: "%.2f", ink))）⇒ 它是占比那条判据的分母，"
                    + "分母跟着网格走，整条判据就跟着网格走")
            // ⑧ **本轮换尺的理由**：同一件物理变化在旧尺上按 缩放² 变。
            let changed = Self.changedPixelCount(dim.0, dim.1, clipping: wholeRect)
            XCTAssertEqual(Double(changed), Double(2000 * scale * scale), accuracy: Double(scale * scale),
                "\(scale)×：旧那把尺在同一个物理变化上数到 \(changed) 个像素 —— 它**应该**按 缩放² 变，"
                    + "这一格钉的是『换尺的理由』这件事本身：那道 `≥500 个像素` 的地板在 1× 与 2× 上"
                    + "量的不是同一件事（本机 1797 / runner 0 那句里最多 3/4 是网格）")
            readings.append("\(scale)×:②搬动=\(String(format: "%.2f", movedDim)) "
                + "③并集=\(String(format: "%.2f", movedColor)) ④全透=\(String(format: "%.2f", movedGhost)) "
                + "⑤左/右=\(String(format: "%.2f", movedLeft))/\(String(format: "%.2f", movedRight)) "
                + "⑥⑦地板下/上=\(String(format: "%.2f", movedUnder))/\(String(format: "%.2f", movedOver)) "
                + "⑨面积=\(String(format: "%.2f", ink)) ⑧旧尺像素=\(changed)")
        }
        emit("CAPTURE_INK_RULER_TRUTH_TABLE " + readings.joined(separator: " | "))
    }
    /// R76 / U-116：浮层搜索框的**焦点那一档** —— 它不是"没有视觉后果"，是"只活在 alpha 通道里"。
    ///
    /// 这条判据本来要写的是"焦点态在帧里看不见 ⇒ 只能真机判"。量出来不是那么回事，
    /// 而且中间我自己错了一次（U-131）：第一版拿"建出来时"与"`makeFirstResponder` 之后"相减，
    /// 而实测那颗框**建出来的那一刻就已经聚焦**（AppKit 把 key view 选成了它）
    /// ⇒ 两张帧同一个状态，那个"0 个变化像素"什么都没证明。
    /// 换成"聚焦 vs 撤掉焦点"两态之后，差是真的，而且很大（**下面这几个数就是这条判据自己打出来的
    /// 那一行 `QUICKPICK_FOCUS`，R78 对过账**：本机 2×，亮档 / 暗档）：
    ///   框内变化像素 1797 / 2354，框外那一圈 0 / 0；
    ///   那一格平均 alpha 10.71 ⇒ 6.77（亮）、13.15 ⇒ 8.64（暗），差 3.93 / 4.52；
    ///   占位区（左 30%、内缩 3pt）有墨像素 1699 / 1871，整窗 69048 / 71021。
    /// R76 的注释在这里写过一组别的数（"1901 / 2144 个像素"与"alpha 143.6 ⇒ 90.9"），
    /// 而那两个数在这条判据的读数里根本不存在 —— 1901/2144 其实是**有墨像素**（R78 新加的那一列
    /// 量出来正好是它们），被当成"变化像素"抄进了注释；143.6/90.9 是第一版拿另一块矩形量的。
    /// 记在这里是因为这就是"注释替事实背书"的代价：R77 的台账照抄了注释，
    /// 而判据自己打的读数才是唯一该被引的那一份（U-139）。
    /// 但**同一对在亮度轴上只有 -0.66 / +2.25（/255）** ⇒ 只看亮度的尺会判成"焦点没有后果"。
    /// 于是这一格的四条断言各钉一样，少一条就有一族回归没人管：
    ///   ① 焦点确实落进那颗框（读产品对象：窗口响应者是字段编辑器，不是帧）；
    ///   ② 焦点**有**视觉后果，且方向是"让位"（那一格 alpha 必须降）—— 不是"变响"；
    ///   ③ 后果必须留在框内（框外那一圈 0 个像素）⇒ "不加自定义焦点环"这一格是量过的决定，
    ///      将来谁让焦点往框外画东西，这条会红，含义是"该重判"，不是"把绘制删掉"；
    ///   ④ 系统环不许被关掉（`focusRingType` 必须是 0 = 系统自己决定）。
    ///      **这格的坑**：raw 0 才是"系统决定"，而 Swift 里 `.none` 的 raw 是 **1**，
    ///      按名字猜会写成"等于 .none"，那正好把"环被关掉"当成通过（U-133）。
    /// 外加一条源码守卫：产品 `show()` 的函数体里必须同时有 `makeKeyAndOrderFront` 与
    /// `makeFirstResponder(field)` —— 少了后者的话①②③④全都不会红（浮层照样能用，
    /// 只是打字要用户多点一下那颗框）。
    ///
    /// 仍然量不到的一件事（点名，不猜）：真机上那颗框**有没有**系统焦点环。
    ///
    /// **R80 换了②③那两条的尺**（BACKLOG 109 的答案、D-138）：从"数过地板的像素个数"
    /// 换成"搬动了多少 **pt²** 的墨 + 占那一格现有墨的**比例**"，并同时拍下三条证人臂
    /// （同态重拍的噪声 / 撤掉 `placeholderString` / 打进一个字）。换尺是被 R79 的 CI 逼的：
    /// 那一遍 runner 上存在性闸门**开**（`占位整条宽=87.0pt`）而两态差读 0 个像素，
    /// 于是"焦点没有视觉后果"与"这台机器的网格太粗"又长回了同一句话。
    /// 合成夹具那一轮的真值表（`CAPTURE_INK_RULER_TRUTH_TABLE`）钉住新旧两把尺的分别是
    /// **4 倍**（2000 个像素 vs 8000 个，同一个物理变化）—— 那道 `≥500 个像素` 的地板
    /// 在两台机器上量的从来不是同一件事。④ 那条（不许关掉系统环）本轮**挪到像素判据之前**，
    /// 因为 R78 那道闸门会 `continue`，而它的注释写着"④照判"—— 注释在替代码撒谎（U-139 那一族）。
    ///
    /// 这条通道不带 key 窗口（`appActive=false 面板key=false`），所以③那个"框外 0 像素"
    /// 不能推成"产品没有环" ⇒ `QUICKPICK_FOCUS_RING_NOT_RUN=1`，人工批次 68.1。
    /// 存在性闸门的地板（pt）：带内"有墨像素的 x 包围盒"至少这么宽，才算那串占位字画出来了。
    /// 来历见调用点：图标自己 ≈14pt、图标 + 占位字实测 86.5pt，40pt 落在两者中间且两边都有倍数余量。
    static let placeholderMinSpanPoints: Double = 40

    /// 焦点"让位"那条判据的地板（R80），三条一起用：
    ///   · `focusMinMovedPointsSquared` —— 搬动的墨至少这么多 **pt²**；
    ///   · `focusNoiseMargin` —— 或者至少是**这一台机器上同态重拍噪声**的这么多倍（臂 R）；
    ///   · `focusMinDimFraction` —— 且不少于那一格里现有墨的这个**占比**。
    /// 来历（本机 2× 那一遍 `QUICKPICK_FOCUS_INK` 打的数，亮 / 暗）：
    ///   焦点搬动 **98.7 / 113.3pt²**、那一格现有墨 **268.7 / 330.1pt²**、占比 **0.367 / 0.343**、
    ///   同态重拍噪声 **0.0 / 0.0pt²**、证人臂撤占位字 **268.7 / 330.0pt²**、打进字 **236.7 / 283.9pt²**。
    /// ⇒ 40pt² 是实测焦点搬动量的约 1/2.5～1/3，8% 是实测占比的约 1/4.5；而 runner 那一侧按 R79 读到的
    ///   均值差换算约 **1.3pt²**（0.05×6400÷255）—— 在地板下面 30 倍。这道地板**不是**为 runner 调的
    ///   （R38：不许拿一台机器的读数当另一台的地板），它两边都留了倍数余量；
    ///   runner 过不了的时候由**证人臂**决定那是『尺在这一格瞎了』还是『这台机器不调淡』。
    /// 为什么不沿用 R76 那两个数（`变化像素 ≥ 500`、`alpha 均值掉 ≥ 2.0`）：
    /// 它们量的都是**同一件事在某一像素网格上的投影**。runner 1× 与本机 2× 读出
    /// 0 与 1797（同一个 3/4 是网格），而"均值掉 2.0"那道地板在带均值 10.71 与 3.55 的两台机器上
    /// 也不是一个难度（R38 那一课，只是这次是我自己新写的判据中招）。
    /// pt² 与占比都是**网格无关**的量 ⇒ 同一道地板在两台机器上说的是同一句话。
    static let focusMinMovedPointsSquared: Double = 40
    static let focusNoiseMargin: Double = 10
    static let focusMinDimFraction: Double = 0.08
    /// 证人臂（撤占位符 / 打进字）至少要搬动这么多 pt²，才算"这把尺在这一格看得见东西"。
    /// 它决定 `QUICKPICK_FOCUS_AXIS_NOT_RUN` 那句是"尺瞎了"还是"这台机器不调淡"——
    /// 两种成因的处置不同，所以这条地板不能与上面那条合用一个数（R77 的教训：
    /// 同一个词在两个判据里含义不同就别统一成一个布尔值）。本机实测这条臂 268.7 / 330.0pt²。
    static let competenceMinMovedPointsSquared: Double = 40

    func testOverlaySearchFieldFocusRecedesThePlaceholderAndDrawsNoRing() throws {
        for (label, appearance) in [("亮", NSAppearance.Name.aqua),
                                    ("暗", NSAppearance.Name.darkAqua)] {
            let build = QuickPickCapturePanel.builder(store: makePopulatedStore(), query: "")
            guard let panel = build(), let content = panel.contentView else {
                throw XCTSkip("捕获入口建不出浮层窗口 ⇒ 这一档今天无从判定（不是产品没做）")
            }
            _ = NSApplication.shared
            let previousAppearance = NSApplication.shared.appearance
            NSApplication.shared.appearance = NSAppearance(named: appearance)
            content.appearance = NSAppearance(named: appearance)
            panel.setFrameOrigin(NSPoint(x: -20011, y: -20011))
            panel.orderFrontRegardless()
            RunLoop.main.run(until: Date().addingTimeInterval(0.2))
            Self.tileScrollViews(in: content)
            defer {
                NSApplication.shared.appearance = previousAppearance
                panel.orderOut(nil)
            }
            guard let field = Self.firstView(ofType: QuickPickSearchField.self, in: content) else {
                return XCTFail("浮层树里找不到那颗 `QuickPickSearchField` ⇒ 这条判据没有对象")
            }
            func shoot() -> NSBitmapImageRep {
                panel.display()
                RunLoop.main.run(until: Date().addingTimeInterval(0.05))
                guard let rep = content.bitmapImageRepForCachingDisplay(in: content.bounds) else {
                    return NSBitmapImageRep()
                }
                content.cacheDisplay(in: content.bounds, to: rep)
                return rep
            }
            // 两态对照：**"焦点这一档有没有像素"只能拿"聚焦"与"不聚焦"两张帧相减。**
            // 这一条第一版写错了，而错得很有代表性：我拿的是"建出来时"与"`makeFirstResponder` 之后"，
            // 实测建出来的那一刻那颗框**就已经**带着字段编辑器（AppKit 把 key view 选成了它）
            // ⇒ 两张帧是同一个状态，那个"0 个变化像素"什么也没证明。
            // 这就是"正对照读的不是判据读的那个量"那一族（U-131），本轮自己撞在自己新写的判据上。
            let builtInEditor = field.currentEditor()
            let accepted = panel.makeFirstResponder(field)
            RunLoop.main.run(until: Date().addingTimeInterval(0.15))
            let focusedResponder = panel.firstResponder
            let focused = shoot()
            // 反面那一态：把焦点从那颗框上拿走。两态必须**真的**不同，否则下面的相减是空转。
            panel.makeFirstResponder(nil)
            RunLoop.main.run(until: Date().addingTimeInterval(0.15))
            let blankResponder = panel.firstResponder
            let unfocused = shoot()
            // ===== R80 的三条证人臂（BACKLOG 109 的第二分支：独占区有墨而两态差为 0）=====
            // runner（run 38760347161）把这一格判成"焦点没有视觉后果"，而本机判成"有 394pt² 的墨在动"。
            // 只靠这两张帧永远分不开那两句话，所以这里在同一颗框上再加三个状态，
            // **全部用同一把尺**（R68：证人必须与它作证的判据读同一个量）量"那一格里搬动了多少墨"：
            //   臂 R `againUnfocused` —— **不改变任何状态**再拍一张。它给的是这台机器上这把尺的
            //     噪声地板：同一态两张帧之差读出来多少，判据地板就必须高于它（R38：地板从表推导，不猜）。
            //   臂 D `noPlaceholder` —— `placeholderString = ""`。这一格里那串字**必须**消失，
            //     它是"这条通道在 1× 上能不能表达这一格的墨变化"的直接证人：
            //     D 读得出东西而 B 读不出 ⇒ 尺不瞎，是"聚焦不调淡"这件事在这台机器上不成立。
            //   臂 C `hasText` —— `stringValue = "搜"`（AppKit 在有字时不画占位符）。
            //     与 D 不同的失效面：D 撤的是**属性**（AppKit 的占位符绘制分支整条不走），
            //     C 走的是**另一条绘制路径**（字符串本身）。两条都空 = 这一格对这把尺失明；
            //     只有一条空 = 那条臂作废，读数仍然要发出来。
            // 这三张帧都不落盘（`shoot()` 只返回 rep），所以帧基线那 124 张不受影响。
            let againUnfocused = shoot()
            let placeholderWas = field.placeholderString
            field.placeholderString = ""
            RunLoop.main.run(until: Date().addingTimeInterval(0.05))
            let noPlaceholder = shoot()
            field.placeholderString = placeholderWas
            let textWas = field.stringValue
            field.stringValue = "搜"
            RunLoop.main.run(until: Date().addingTimeInterval(0.05))
            let hasText = shoot()
            field.stringValue = textWas
            let scale = max(1, focused.pixelsWide / max(Int(content.bounds.width), 1))
            let inContent = field.convert(field.bounds, to: nil)
            let band = CGRect(x: inContent.minX * CGFloat(scale),
                              y: (content.bounds.height - inContent.maxY) * CGFloat(scale),
                              width: inContent.width * CGFloat(scale),
                              height: inContent.height * CGFloat(scale))
            // 焦点环画在框**外面**（约 3–4pt），所以只看框那一格会把"环"看成"没有变化"。
            let halo = band.insetBy(dx: -8 * CGFloat(scale), dy: -8 * CGFloat(scale))
            let changedIn = Self.changedPixelCount(focused, unfocused, clipping: band)
            let changedHalo = Self.changedPixelCount(focused, unfocused, clipping: halo)
            // **两把尺一起打：亮度轴与 alpha 轴。** 实测（R76，本机 2×，亮/暗两档）：
            //   亮度轴整带差 = -0.66 / +2.25（/255）⇒ 只看亮度会得出"焦点没有视觉后果"的假结论；
            //   alpha 轴：占位符那一格 143.6 ⇒ 90.9（亮）、156.5 ⇒ 102.9（暗），
            //            变化像素 1901 / 2144，包围盒正好是那一串占位字（x 12.0–98.5pt、y 顶下 14–26pt）。
            // ⇒ 焦点这一档**有**视觉后果（占位符退后给光标让位），但它只活在 alpha 通道里。
            //    判据必须走 alpha —— 与"灰 vs 蓝别用亮度轴"同族（U-132）。
            let lumIn = Self.meanLuminance(unfocused, rect: band) - Self.meanLuminance(focused, rect: band)
            let alphaUnfocused = Self.meanAlpha(unfocused, rect: band)
            let alphaFocused = Self.meanAlpha(focused, rect: band)
            // **存在性尺（R78）**：这一格里画没画东西，与"两态差没差"是两个问题。
            // runner 那一遍（run 38743276799）报的是 `框内变化像素=0`、`alpha 差 0.05`，
            // 本机是 1797 / 3.93 —— 只读差值的尺子分不开"焦点没有后果"与"那串字今天没画"。
            // 所以这里另量一个不依赖两态相减的数：占位符那一格里 alpha 过地板的像素数。
            let wholePanel = CGRect(x: 0, y: 0, width: unfocused.pixelsWide, height: unfocused.pixelsHigh)
            // 存在性那一格量的**不是整条 band**，而是"占位字该在的那一块"：
            // 左边 30% 宽、四周再内缩 3pt。**R80 对过账**：这一格里画着的墨**全是那串占位字**
            // （臂 D 把 `placeholderString` 撤成空，带墨面积从 268.7 / 330.1pt² 掉到 **0.0pt²**，
            //  亮 / 暗）—— 产品这颗框是 `isBordered=false` + `drawsBackground=false`，
            // 所以"描边混进来"与"图标混进来"那两条理由在**这个控件**上都不成立，
            // 内缩 3pt 与左 30% 是**防御性**形状（将来谁给它加了边框或图标，这两个数就真的有对象）。
            // 真正被读数用过的理由只有一条：② 占位字的实测包围盒是 x 12.5–98.5pt（band 宽 400pt）
            // ⇒ 左 30% 把它整个包住。本机这一格有墨像素 **1699 / 1871**（亮 / 暗，
            // 就是 `QUICKPICK_FOCUS` 行里 `占位区有墨(不聚焦,左30%内缩3pt)` 那一列；
            // 这条注释之前写的 1967 / 2208 是探针形状改掉之后的旧数，U-139 那一族）。
            let inset = 3.0 * CGFloat(scale)
            let inkProbe = CGRect(x: band.minX + inset, y: band.minY + inset,
                                  width: band.width * 0.3 - inset, height: band.height - 2 * inset)
            let inkUnfocused = Self.alphaInkPixels(unfocused, rect: inkProbe)
            let inkFocused = Self.alphaInkPixels(focused, rect: inkProbe)
            let inkWholePanel = Self.alphaInkPixels(unfocused, rect: wholePanel)
            // **R79：决定闸门的是宽度的存在性，不是计数。** R78 用"占位区里 ≥20 个有墨像素"，
            // 结果它在 runner 上没拦住（run 38757049151 仍是那四条红）——
            // **R80 把机制查清了**（臂 D：那一格里的墨全是那串占位字，图标与描边都不存在），
            // 所以 R79 注释里"那颗放大镜 AppKit 画得出它"那句作废（U-146）。真正的原因是：
            // **过地板的像素数分不开"画了开头两个字"与"画了整串字"** —— 前缀就够 20 个。
            // 计数与宽度的分别正在这里：
            //   开头那一片 ≈17pt；本机实测整串是 x 12.5–98.5pt = 86.5pt。
            // 地板取 40pt：两个数差五倍，不在刀尖上（R66 那条 `deadSpan=0.05` 同道理）。
            let spanUnfocused = Self.alphaInkSpan(unfocused, rect: band)
            let spanFocused = Self.alphaInkSpan(focused, rect: band)
            let spanWidthPt = spanUnfocused.max < 0 ? -1.0
                : Double(spanUnfocused.max - spanUnfocused.min + 1) / Double(scale)
            // 第二根证人：**只有占位字能待的那一块**（x 从带左起 50pt 之后、上下各内缩 2pt）。
            // 为什么宽度还不够：一圈 1px 的**描边**能把包围盒撑到整条 band 宽，
            // 而它进不了这一块 —— 上下被内缩排掉，左边被 50pt 排掉。
            // 两个条件取**合取**：图标一个人开不了门（宽度不够、这一块也是空的），
            // 描边也开不了门（这一块是空的），只有那串字在的时候两个都成立。
            let textOnlyRect = CGRect(x: band.minX + 50 * CGFloat(scale),
                                      y: band.minY + 2 * CGFloat(scale),
                                      width: band.width - 52 * CGFloat(scale),
                                      height: band.height - 4 * CGFloat(scale))
            let textOnlyInk = Self.alphaInkPixels(unfocused, rect: textOnlyRect)
            let placeholderDrawn = spanWidthPt >= Self.placeholderMinSpanPoints && textOnlyInk >= 20
            emit("QUICKPICK_FOCUS \(label) appActive=\(NSApp.isActive) 面板key=\(panel.isKeyWindow) "
                + "主=\(panel.isMainWindow) makeFirstResponder=\(accepted) "
                + "建出来时就聚焦=\(builtInEditor != nil) 聚焦时响应者是编辑器=\(focusedResponder is NSText) "
                + "撤焦点后还是=\(blankResponder is NSText) "
                + "focusRingType=\(field.focusRingType.rawValue) 缩放=\(scale)× 带=\(NSStringFromRect(band)) "
                + "框内变化像素=\(changedIn) 框外一圈变化像素=\(changedHalo - changedIn) "
                + "alpha 聚焦=\(String(format: "%.2f", alphaFocused)) "
                + "不聚焦=\(String(format: "%.2f", alphaUnfocused)) "
                + "差=\(String(format: "%.2f", alphaUnfocused - alphaFocused)) 亮度轴差=\(String(format: "%.2f", lumIn)) "
                + "占位区有墨(不聚焦,左30%内缩3pt)=\(inkUnfocused) 有墨(聚焦)=\(inkFocused) 整窗有墨=\(inkWholePanel) "
                + "文字独占区有墨(不聚焦,x≥50pt 内缩2pt)=\(textOnlyInk) "
                + "带内有墨包围盒(不聚焦)=\(spanUnfocused.min)…\(spanUnfocused.max)px "
                + "宽=\(String(format: "%.1f", spanWidthPt))pt(聚焦 \(spanFocused.min)…\(spanFocused.max)) "
                + "地板=\(String(format: "%.0f", Self.placeholderMinSpanPoints))pt "
                + "⇒ 存在性尺说\(placeholderDrawn ? "这一格画了东西，像素那两条有对象" : "这一格今天没画那串字，像素那两条没有对象")")
            XCTAssertGreaterThanOrEqual(changedIn, 0, "\(label)档：尺读不出两张帧 ⇒ 无从判定，不许当通过")
            // **闸门的判别力对照（R79，R80 更正了它的机制）**：这一格里没有放大镜、也没有描边
            // （臂 D 撤掉 `placeholderString` 之后带墨面积 = 0.0pt²），所以这里框住的是
            // **那串字的开头一小片**。R79 的注释把它说成"那颗放大镜 AppKit 画得出来"，
            // 那句话是**编的**（U-146），而它当时能过是因为"一小片字"和"一颗图标"在这把尺上读数一样。
            // 如果这一小片就能把宽度撑到地板以上，这道闸门等于没设 —— 而 R78 就是那样倒的
            // （它数的是像素个数，开头那一片一个人就过了）。所以这里单独量这一小片的包围盒，
            // 要求它**过不了**闸门。整串字画出来时这一格才有对象；没画出来时这一小片仍然有对象
            // （开头在不在与整串在不在是两件事），所以不设 `placeholderDrawn` 前提。
            let prefixRect = CGRect(x: (inContent.minX + 3) * CGFloat(scale),
                                    y: band.minY,
                                    width: 17 * CGFloat(scale), height: band.height)
            let prefixSpan = Self.alphaInkSpan(unfocused, rect: prefixRect)
            let prefixWidthPt = prefixSpan.max < 0 ? 0.0
                : Double(prefixSpan.max - prefixSpan.min + 1) / Double(scale)
            emit("QUICKPICK_FOCUS_GATE \(label) 开头那一小片宽=\(String(format: "%.1f", prefixWidthPt))pt "
                + "占位整条宽=\(String(format: "%.1f", spanWidthPt))pt 地板=\(String(format: "%.0f", Self.placeholderMinSpanPoints))pt "
                + "⇒ 闸门\(placeholderDrawn ? "开（那串字画全了）" : "关（只有开头那一小片）")")
            XCTAssertLessThan(prefixWidthPt, Self.placeholderMinSpanPoints,
                "\(label)档：只框住那串字的开头一小片，量出来的墨包围盒就有 \(String(format: "%.1f", prefixWidthPt))pt "
                    + "（地板 \(String(format: "%.0f", Self.placeholderMinSpanPoints))pt）⇒ 这道存在性闸门**分不开**"
                    + "'只有开头几个字'与'整串字'，它就恒开，像素那几条又回到没人看着的状态。"
                    + "换探针形状或换地板，别把断言删掉")
            // ① 焦点落进那颗框（行为，读的是产品对象，不是帧）。
            XCTAssertTrue(accepted,
                "\(label)档：`makeFirstResponder(field)` 都没接受 ⇒ 那颗框不是可聚焦的响应者，"
                    + "浮层打开时打字会落空（产品 `show()` 靠的就是这一步）")
            XCTAssertTrue(focusedResponder is NSText,
                "\(label)档：接受了焦点却没有把字段编辑器装成窗口的响应者 ⇒ 焦点在别处，"
                    + "那颗框收不到打字")
            // 正对照：两态必须不同。少了这一格，②③那几条像素断言可以靠"自己减自己"永远绿。
            XCTAssertFalse(blankResponder is NSText,
                "\(label)档：`makeFirstResponder(nil)` 之后窗口响应者**还是**字段编辑器 ⇒ 撤不掉焦点，"
                    + "于是下面那几条断言量的是同一张帧减自己（假绿的教科书形状，U-131）")
            // ④ 值守卫：不许关掉系统环。**R80 把这一条挪到像素那几条之前**：
            // R78 那道存在性闸门（还有本轮那两条 `_NOT_RUN` 出口）都 `continue`，
            // 而它的注释写着"行为那几条照判"—— 注释在替代码撒谎，那一族的账本号是 U-139。
            // 挪上来之后，任何一条缺席出口都仍然判得到这里。
            // **这个枚举的坑（R76 实测）**：raw 0 才是"系统自己决定"，而 Swift 里 `.none` 的 raw 是 **1**
            // （`.automatic` 这个成员在本 SDK 根本不存在，写 `== .automatic` 编译不过）。
            // 一个人按名字猜，就会把这条守卫写成"等于 .none"—— 那正好把"系统环被关掉"当成通过。
            let automatic = NSFocusRingType(rawValue: 0)
            XCTAssertEqual(field.focusRingType, automatic,
                "\(label)档：那颗框的 `focusRingType` 不再是 0（= 系统自己决定；读到 "
                    + "\(field.focusRingType.rawValue)，而 `.none` 的 raw 是 1）"
                    + " ⇒ 焦点环在这条通道里本来就读不到（③那条缺席），关掉它这件事**永远不会被任何一张帧发现**，"
                    + "所以这条值守卫是唯一防线")
            // **存在性闸门（R78）**：像素那两条只在"这一格真的画了东西"时判。
            // 处置按机器分开（R60 那一课）：2× 上没画 ⇒ **红**（那是捕获或产品坏了，必须有人去查），
            // 1× 上没画 ⇒ 点名 not-run（runner 不画 SwiftUI/AppKit 文本是已知通道性质，
            // 见 `PROBE_ELIGIBILITY … ink=0.0%` 那一批读数）。
            // 名字以 `_NOT_RUN` 结尾：`ci_capture_gate.py` 认这个后缀（R36/U-59）。
            if !placeholderDrawn {
                emit("QUICKPICK_FOCUS_NOT_RUN=1 \(label)：占位符那串字今天在这条通道里没画出来"
                    + "（带内有墨包围盒只有 \(String(format: "%.1f", spanWidthPt))pt，"
                    + "低于 \(String(format: "%.0f", Self.placeholderMinSpanPoints))pt 那道地板；"
                    + "计数却有 \(inkUnfocused) 个像素 ⇒ 那一格里画得出的只有开头一小片，不是整串字）⇒ "
                    + "\"聚焦与不聚焦两张帧相同（这次读到 \(changedIn) 个变化像素）这一句，不能推成『焦点没有视觉后果』，"
                    + "它说的是这条通道今天看不见那串字。行为那两条（①响应者、④没关系统环）与源码守卫照判。")
                XCTAssertLessThan(scale, 2,
                    "\(label)档：2× 的捕获通道上占位符那串字的包围盒只有 \(String(format: "%.1f", spanWidthPt))pt ⇒ "
                        + "本机这一格**必须**画得出来（R76 实测 1797 / 2354 个变化像素、包围盒 86.5pt）。"
                        + "红在这里的含义是『捕获或产品今天坏了』，不是『这台机器看不见』——"
                        + "只有 1× 才允许缺席（R60：机器前提不同 ⇒ 处置不同，但都不许静默）")
                continue
            }
            // ② 焦点必须有视觉后果，而**这条判据读的是"搬动了多少墨"（pt²），不是像素个数**（R80）。
            //
            // 换尺的理由是 R79 的 CI 读出来的，不是审美：runner 那一遍（run 38760347161）
            // 存在性闸门**开**（`QUICKPICK_FOCUS_GATE … 占位整条宽=87.0pt … 闸门开`），
            // 而 `框内变化像素=0`、alpha 3.55⇒3.50 —— 命中 BACKLOG 109 预登记的第二个分支：
            // "独占区非 0 而两态差仍是 0 ⇒ 那四条红是真的，要查的是产品/通道，不许再抬地板"。
            // 查出来的结论是：**那把尺本身跟着像素网格变**。`changedPixelCount` 数的是
            // "过 8/255 的像素个数"，本机 2× 同一条字给 1797 个、runner 1× 给 0 个，
            // 而这两个数之间的差别有 **3/4 是网格**（同样多的墨摊在 4 倍数量的像素上）。
            // 所以地板从"个数"换成"pt² 的墨"：它是同一串字在两台机器上**唯一共同的分母**。
            // 三条证人臂（R/D/C，见上面注释）读的是同一把尺，于是"看不见"必须分成两种：
            //   尺在这一格整体失明（证人臂也读不出东西）／ 尺看得见而聚焦不调淡（证人臂读得出）。
            // 两种都不许静默，也都**不许在 2× 上放行** —— 本机是判这条轴的那台机器。
            let noisePt2 = Self.movedInkPointsSquared(unfocused, againUnfocused, rect: band, scale: scale)
            let focusPt2 = Self.movedInkPointsSquared(unfocused, focused, rect: band, scale: scale)
            let armPlaceholderPt2 = Self.movedInkPointsSquared(unfocused, noPlaceholder,
                                                               rect: band, scale: scale)
            let armTextPt2 = Self.movedInkPointsSquared(unfocused, hasText, rect: band, scale: scale)
            let haloPt2 = Self.movedInkPointsSquared(unfocused, focused, rect: halo, scale: scale)
            let bandInkPt2 = Self.inkPointsSquared(unfocused, rect: band, scale: scale)
            let inkNoPlaceholderPt2 = Self.inkPointsSquared(noPlaceholder, rect: band, scale: scale)
            let dimFraction = bandInkPt2 > 0 ? focusPt2 / bandInkPt2 : -1
            let competencePt2 = max(armPlaceholderPt2, armTextPt2)
            // 地板的一半来自**这台机器自己的噪声**（臂 R）：同一态两张帧之差读出来多少，
            // 判据地板就不能低于它的 `focusNoiseMargin` 倍（R38：地板从表推导，不猜常数）。
            let focusFloorPt2 = Self.focusFloorPointsSquared(noisePt2: noisePt2)
            let ringPt2 = haloPt2 - focusPt2
            // 处置由**纯函数**给（`focusDisposition`）：那两支 1× 出口在本机永远走不到，
            // 没有单独的真值表它们就是"没有红钉着的分支"（`testFocusAxisDispositionIsATruthTable`）。
            let disposition = Self.focusDisposition(focusMovedPt2: focusPt2, floorPt2: focusFloorPt2,
                                                    dimFraction: dimFraction,
                                                    minDimFraction: Self.focusMinDimFraction,
                                                    competencePt2: competencePt2,
                                                    competenceFloorPt2: Self.competenceMinMovedPointsSquared)
            let focusJudged = disposition == .judged
            let channelSeesThatBand = disposition != .channelBlindOnThisMachine
            emit("QUICKPICK_FOCUS_INK \(label) 缩放=\(scale)× 带墨面积=\(String(format: "%.1f", bandInkPt2))pt² "
                + "焦点搬动=\(String(format: "%.1f", focusPt2))pt²(地板 \(String(format: "%.1f", focusFloorPt2))"
                + "=max(\(String(format: "%.0f", Self.focusMinMovedPointsSquared)), "
                + "\(String(format: "%.0f", Self.focusNoiseMargin))×噪声) 占比=\(String(format: "%.3f", dimFraction))"
                + "(地板 \(String(format: "%.2f", Self.focusMinDimFraction))) "
                + "噪声(同态重拍)=\(String(format: "%.1f", noisePt2))pt² "
                + "证人臂撤占位字=\(String(format: "%.1f", armPlaceholderPt2))pt² "
                + "证人臂打进字=\(String(format: "%.1f", armTextPt2))pt² "
                + "撤占位字之后带墨面积=\(String(format: "%.1f", inkNoPlaceholderPt2))pt² "
                + "框外那一圈=\(String(format: "%.1f", ringPt2))pt² "
                + "旧尺像素个数=\(changedIn)（R79 的 runner 那一遍这一列是 0） "
                + "⇒ \(focusJudged ? "焦点这一档看得见在让位" : (channelSeesThatBand ? "尺在这一格看得见别的东西在动，而聚焦不动" : "这一格对这把尺整体失明（证人臂也读不出）"))")
            // 证人臂自己也得有对象：撤掉 `placeholderString` 之后那一格的墨**必须少一半以上**。
            // 少了这一格，"臂读不出东西"这句话就可能是**臂没生效**（比如占位符由产品自己画、
            // 改属性撤不掉），而不是"通道看不见" —— 那两种成因的处置完全不同。
            let armDemptiesTheBand = bandInkPt2 <= 0 || inkNoPlaceholderPt2 <= bandInkPt2 * 0.5
            XCTAssertGreaterThanOrEqual(armPlaceholderPt2, 0,
                "\(label)档：证人臂 D 读不出两张帧 ⇒ 这条轴的证据链断了（不是产品红，是尺红）")
            XCTAssertTrue(armDemptiesTheBand,
                "\(label)档：把 `placeholderString` 撤成空，那一格的墨面积只从 "
                    + "\(String(format: "%.1f", bandInkPt2))pt² 变成 "
                    + "\(String(format: "%.1f", inkNoPlaceholderPt2))pt² ⇒ 臂 D 没生效："
                    + "这一格里的墨不是 AppKit 那串占位字（那就是 R79 的包围盒归因错了），"
                    + "要重查这一格里到底画了什么，不许直接引用证人臂的读数")
            if !focusJudged {
                emit("QUICKPICK_FOCUS_AXIS_NOT_RUN=1 \(label)：焦点那一档的墨移动在这一台机器上读到 "
                    + "\(String(format: "%.1f", focusPt2))pt²，地板 \(String(format: "%.1f", focusFloorPt2))pt²"
                    + "（缩放=\(scale)×，同态噪声 \(String(format: "%.1f", noisePt2))pt²）。"
                    + (channelSeesThatBand
                        ? "同一把尺在同一格里读得出别的成因：撤占位字搬动 \(String(format: "%.1f", armPlaceholderPt2))pt²、"
                          + "打进字 \(String(format: "%.1f", armTextPt2))pt² ⇒ **尺不瞎**，"
                          + "是这台机器的 AppKit 不为非 key 窗口调淡占位符（`面板key=\(panel.isKeyWindow) appActive=\(NSApp.isActive)`），"
                          + "这一条不能推成『焦点没有视觉后果』也不能推成『产品没有焦点反馈』"
                        : "两条证人臂也只读出 \(String(format: "%.1f", competencePt2))pt² ⇒ **这一格对这把尺整体失明**，"
                          + "焦点那一条根本没有对象，判不判都是空的")
                    + " 行为那几条（①响应者、④没关系统环）与源码守卫照判 —— 它们在这一格里不依赖像素。")
                // **2× 上这一句必须红**：本机是判这条轴的机器，它读不到就是捕获或产品坏了。
                XCTAssertLessThan(scale, 2,
                    "\(label)档：本机 2× 上焦点那一档只搬动 \(String(format: "%.1f", focusPt2))pt² "
                        + "（地板 \(String(format: "%.1f", focusFloorPt2))pt²、占比 "
                        + "\(String(format: "%.3f", dimFraction))），而同一格里撤掉占位字能读出 "
                        + "\(String(format: "%.1f", armPlaceholderPt2))pt² ⇒ "
                        + "'聚焦不调淡占位符'这件事在**判这条轴的那台机器**上成立了，必须有人去查："
                        + "要么产品/AppKit 变了（那焦点就只剩光标），要么捕获通道变了（那 124 张帧一起要重看）")
                if scale < 2 { continue }
            }
            XCTAssertGreaterThanOrEqual(focusPt2, focusFloorPt2,
                "\(label)档：聚焦与不聚焦两张帧之间只搬动了 \(String(format: "%.1f", focusPt2))pt² 的墨，"
                    + "地板 \(String(format: "%.1f", focusFloorPt2))pt² ⇒ 焦点这一档变成看不见了。"
                    + "今天它是那一串占位字退后（本机实测 98.7 / 113.3pt²、"
                    + "旧那把像素个数尺 1797 / 2354 个）；两种成因都值得查：占位符被换成实色（那就该重判音量），"
                    + "或者 AppKit 不再为聚焦的框调淡占位符（那焦点就只剩光标了）")
            XCTAssertGreaterThanOrEqual(dimFraction, Self.focusMinDimFraction,
                "\(label)档：焦点搬动的墨只占那一格里现有墨的 \(String(format: "%.3f", dimFraction))"
                    + "（地板 \(String(format: "%.2f", Self.focusMinDimFraction))）⇒ 占比这一根轴管的是"
                    + "'这一格的墨有没有明显少掉'，它与绝对量各自拦一种错：整格墨变少而聚焦仍然调淡同一比例，"
                    + "绝对量会掉到地板以下但占比不会；墨面积涨了而绝对量够，占比会掉下来")
            XCTAssertLessThanOrEqual(alphaFocused, alphaUnfocused,
                "\(label)档：聚焦之后那一格的 alpha 反而不比不聚焦时低（聚焦=\(String(format: "%.2f", alphaFocused)) "
                    + "不聚焦=\(String(format: "%.2f", alphaUnfocused))）⇒ 焦点反馈的**方向**变了："
                    + "今天是'占位符退后给光标让位'，'聚焦把那一格叫得更响'是另一种设计，该重判。"
                    + "R80 把原来那条『绝对掉 2.0』的地板拆到这里：那个数跟着墨的绝对水平走，"
                    + "本机带均值 10.71 而 runner 3.55 ⇒ 同一道地板在两台机器上不是一个难度")
            // ③ 后果必须留在框内：这一格是量过之后决定**不加**自定义焦点环的。
            XCTAssertLessThanOrEqual(ringPt2, focusFloorPt2,
                "\(label)档：框外那一圈搬动了 \(String(format: "%.1f", ringPt2))pt² 的墨（地板 "
                    + "\(String(format: "%.1f", focusFloorPt2))pt²）⇒ 焦点开始往框外画东西了"
                    + "（多半是自定义环/描边，或系统环真的开始画）。这一格是 R76 量过才决定不加的："
                    + "红在这里的含义是'该重判'，不是'把那段绘制删掉'。"
                    + "旧的像素个数那一列（框外 \(changedHalo - changedIn) 个）仍然发在 QUICKPICK_FOCUS 行里，"
                    + "但它不再做判断：那一圈只有 8pt 宽，1× 上一条描边就几个像素，判不了")
            emit("QUICKPICK_FOCUS_RING_NOT_RUN=1 \(label)：焦点环这一档在这条通道里读不到"
                + "（框外那一圈 \(String(format: "%.1f", ringPt2))pt²，而 `面板key=\(panel.isKeyWindow) "
                + "appActive=\(NSApp.isActive)`）"
                + "⇒ 真机上有没有系统环只能你看（人工批次 68.1），不许把这条缺席写成'产品没有焦点环'")
        }
        // 产品入口那条赋值必须还在（①②③全都不会红的那一族回归，只有这条守卫抓得到）。
        let source = Self.codeOnly(try productSource(named: "Managers/QuickPickController.swift"))
        let body = Self.functionBody(named: "func show()", in: source)
        XCTAssertFalse(body.isEmpty,
                       "扫不到 `show()` 的函数体 ⇒ 下面两条守卫是空转的（正对照）")
        XCTAssertTrue(body.contains("makeKeyAndOrderFront"),
                      "`show()` 不再把面板变成 key ⇒ 焦点环与打字都可能落空，"
                          + "而①②③三条读的是夹具那条路径，看不见这件事")
        XCTAssertTrue(body.contains("makeFirstResponder(field)"),
                      "`show()` 不再把焦点交给那颗框 ⇒ 浮层打开后要先点一下才能打字。"
                          + "这一族在帧里、在①②里都没有影子（夹具故意不抢前台），只有这条守卫抓得到")
        XCTAssertTrue(Self.functionBody(named: "func definitelyNotInThisFile()", in: source).isEmpty,
                      "不存在的函数名也扫得出东西 ⇒ 截取器'永远看得见'，上面两条一起退化成噪声计数器")
    }


    /// R71 / BACKLOG 99：浮层那一行的字号，与"同一条记录的标题"在别处的字号，必须是同一档。
    ///
    /// 这条从**产品入口**进（DoD 第 1 条）：建出真的浮层面板，读真的 `NSTextField.font`，
    /// 而不是读源码里的一个数。三处断言各自拦一种错：
    ///   · 行标签 == `VisualFont.row` ⇒ 拦"浮层自己再定一档"（改之前它是就地写的 13，
    ///     而侧栏 / 行视图 / 搜索建议那五处全是 12 ⇒ 同一个对象在两处响一档）；
    ///   · 搜索框 == `VisualFont.body` ⇒ 拦"浮层比主窗口那颗搜索框更响"（原来是就地写的 14，
    ///     主窗口是 13 —— 浮层的职责是"快"，不是"大"）；
    ///   · 五行必须**同档** ⇒ 拦"某一行的字号被别处覆盖掉"（那种错在帧上几乎看不出来，
    ///     因为差只有 1pt；但它是"两处各写一个数"的下一步）。
    ///
    /// 为什么这里**不**去帧上量墨高来跨表面对齐：同一把尺量到的行距是
    /// 浮层 33–35pt（单行）vs 侧栏 38–47pt（双行），两者不可比；
    /// 而墨高跟着字形内容走（有没有 `g/y/9` 差一截），拿它当判据就是拿噪声当契约。
    /// 跨表面的同一性由**令牌**保证，这一条就是保证它真的到了产品对象上。
    func testQuickPickTypographyComesFromTheLadder() throws {
        _ = NSApplication.shared
        let store = makePopulatedStore()
        let build = QuickPickCapturePanel.builder(store: store, query: "", hoveredRow: nil)
        guard let panel = build(), let content = panel.contentView else {
            throw XCTSkip("捕获入口建不出浮层窗口 ⇒ 这一档今天无从判定（不是产品没做）")
        }
        panel.setFrameOrigin(NSPoint(x: -20007, y: -20007))
        panel.orderFrontRegardless()
        RunLoop.main.run(until: Date().addingTimeInterval(0.2))
        defer { panel.orderOut(nil) }
        guard let table = Self.productTable(in: content) else {
            return XCTFail("帧根里找不到那颗产品表格 ⇒ 这条判据没有对象")
        }
        var labelSizes: [CGFloat] = []
        for row in 0..<table.numberOfRows {
            guard let cell = table.view(atColumn: 0, row: row, makeIfNecessary: true) else { continue }
            if let field = (cell as? NSTableCellView)?.textField ?? Self.firstTextField(in: cell) {
                labelSizes.append(field.font?.pointSize ?? -1)
            }
        }
        let fieldSizes = Set(labelSizes)
        let searchSize = (Self.firstView(ofType: QuickPickSearchField.self, in: content))?.font?.pointSize ?? -1
        let sizesAsInts = labelSizes.map { Int($0.rounded()) }
        emit("QUICKPICK_TYPE 行数=\(labelSizes.count) 行标签字号=\(sizesAsInts) "
            + "期望=\(Int(VisualFont.row)) 搜索框字号=\(Int(searchSize.rounded())) 期望=\(Int(VisualFont.body))")
        XCTAssertGreaterThanOrEqual(labelSizes.count, 3,
                                    "只读到 \(labelSizes.count) 个行标签 ⇒ 这条判据没有对象（表格没建出来？）")
        XCTAssertEqual(fieldSizes, [CGFloat(VisualFont.row)],
                       "浮层行标签的字号不再是 `VisualFont.row`(\(Int(VisualFont.row))) —— 读到 \(labelSizes)。"
                           + "同一条记录的标题在侧栏 / 行视图 / 搜索建议那五处都是这一档，"
                           + "浮层是第六处，它没有理由自己响一档（BACKLOG 99）")
        XCTAssertEqual(searchSize, CGFloat(VisualFont.body),
                       "浮层搜索框是 \(Int(searchSize))pt，而主窗口那颗搜索框是 `VisualFont.body`(\(Int(VisualFont.body)))pt "
                           + "⇒ 同一个控件在两个表面响一档。浮层的职责是快，不是大")
    }

    /// 视图树里第一个 `NSTextField`（深度优先）。
    private static func firstTextField(in root: NSView) -> NSTextField? {
        firstView(ofType: NSTextField.self, in: root)
    }

    /// 视图树里第一个指定类型的视图（深度优先）。
    /// 用类型而不是"位置"来找搜索框：`content.subviews` 的顺序由 AppKit 决定，
    /// 拿顺序当身份，下一次布局改动就会把判据指向别的东西（R53 那一族"守卫命中守卫自己"的近亲）。
    private static func firstView<T: NSView>(ofType type: T.Type, in root: NSView) -> T? {
        for sub in root.subviews {
            if let match = sub as? T { return match }
            if let found = firstView(ofType: type, in: sub) { return found }
        }
        return nil
    }

    /// 空结果那一句的**两条**契约（R63）：它得真的在画（不是停在淡入的起点），
    /// 以及它得落在列表那一格（紧跟搜索框），不许掉在面板最底下。
    ///
    /// 为什么要分开两条：
    /// · `alphaValue` —— `applyEmptyState` 走 `animator()`，而非图层的 view 上这条**不提交模型值**
    ///   （spike 四臂：无图层两臂设完读到 0.000、转 2.1s 仍是 0.000 且完成回调从不跑；
    ///   图层化那一臂立刻读到 1.000）。也就是说"用户看不看得见这句话"被压在"动画跑没跑完"上。
    ///   这条断言不许它再回到那种形状。淡入本身仍然是"源码已接、产物未量"（账本 D-055）。
    /// · 位置 —— 这一条由**看帧**得出：R7 当年把句子放在表格下面，理由是实现便利；
    ///   第一次把这个浮层拍出来看到的是搜索框下面 227pt 空白、句子在面板最底下。
    ///   坐标约定实测过（AppKit y 向上：搜索框在 y 大的一侧），所以判据写的是
    ///   "句子顶边到搜索框底边的间隙 ≤ 24pt"，而不是"句子在 y=??"。
    func testQuickPickEmptyStateSentenceIsCommittedAndSitsInTheListSlot() throws {
        let store = makePopulatedStore()
        let build = QuickPickCapturePanel.builder(store: store, query: "zzz 不存在")
        guard let panel = build(), let content = panel.contentView else {
            return XCTFail("捕获入口建不出浮层窗口 ⇒ 这条判据失去了对象，必须红")
        }
        _ = NSApplication.shared
        defer { panel.orderOut(nil) }
        panel.setFrameOrigin(NSPoint(x: -20000, y: -20000))
        panel.orderFrontRegardless()
        RunLoop.main.run(until: Date().addingTimeInterval(0.2))
        Self.tileScrollViews(in: content)
        panel.display()
        RunLoop.main.run(until: Date().addingTimeInterval(0.05))

        var field: NSTextField?
        var sentence: NSTextField?
        var otherFields: [String] = []
        func find(_ view: NSView) {
            if let tf = view as? NSTextField {
                if tf is QuickPickSearchField {
                    field = tf
                } else if tf.identifier?.rawValue == "quickPickEmptyMessage" {
                    sentence = tf
                } else if !tf.stringValue.isEmpty {
                    otherFields.append("len=\(tf.stringValue.count) id=\(tf.identifier?.rawValue ?? "-")")
                }
            }
            view.subviews.forEach(find)
        }
        find(content)
        guard let sentence else {
            return XCTFail("浮层里没有「没有匹配…」那句话（identifier=quickPickEmptyMessage）"
                           + " ⇒ 空结果态什么都没有说；非搜索框的其它 NSTextField：\(otherFields)")
        }
        emit("QUICKPICK_EMPTY_FIELD 句子长=\(sentence.stringValue.count) "
             + "其它字段=\(otherFields.count)")
        XCTAssertFalse(sentence.isHidden, "那句话被藏起来了 ⇒ 空结果时浮层是一片空白")
        XCTAssertEqual(sentence.alphaValue, 1, accuracy: 0.001,
                       "那句话的模型值是 \(sentence.alphaValue) ⇒ 它的可见性被压在「淡入动画跑完」上。"
                       + "实测：非图层的 view 上 `animator().alphaValue` 不提交模型值（spike 臂1/臂2 停在 0.000），"
                       + "所以这条路径在没有真实显示周期的地方就是「字在、看不见」。淡入是装饰，看得见才是契约")
        guard let field else { return XCTFail("找不到搜索框 ⇒ 「紧跟搜索框」这一条没有对象") }
        // 两个 frame 都换算到**同一个**祖先（content）再比 —— 不假设嵌套层数，
        // 也不拿 stack 局部坐标和 window 坐标相减（那种数看着像读数，其实是错的）。
        guard let fieldRect = Self.frame(field, in: content),
              let sentenceRect = Self.frame(sentence, in: content) else {
            return XCTFail("换算不到同一坐标系 ⇒ 「句子紧跟搜索框」这条判据没有对象")
        }
        // AppKit 的 y 向上：搜索框在**上面**，所以它的 `minY` 就是它的底边。
        let gap = fieldRect.minY - sentenceRect.maxY
        emit("QUICKPICK_EMPTY_SENTENCE fieldBottom=\(String(format: "%.1f", fieldRect.minY)) "
              + "sentenceTop=\(String(format: "%.1f", sentenceRect.maxY)) gap=\(String(format: "%.1f", gap))")
        XCTAssertLessThanOrEqual(gap, 24,
                                "那句话与搜索框之间空了 \(Int(gap))pt ⇒ 它又掉回面板最底下了。"
                                + "用户刚打完字，眼睛就在列表区那一行；解释必须落在那一格（R63 挪的位置）")
        XCTAssertGreaterThan(gap, -4,
                             "那句话压到搜索框上面去了（gap=\(Int(gap))）⇒ 两行叠在一起，读不成一句")
        // 第三条：**横向居中**。它自己写着 `alignment = .center`，但那句"居中"只在它自己的框里成立 ——
        // 框不居中，字就不居中。这一条是变异 M332 替我审出来的：第一版判据只量竖向的"紧跟搜索框"，
        // 于是"撤掉那句话的等宽约束"这一刀**绿着回来**（它退回字宽，位置那条完全没感觉）。
        let sentenceMidX = sentenceRect.midX
        let panelMidX = content.bounds.midX
        XCTAssertLessThan(abs(sentenceMidX - panelMidX), 3,
                          "那句话的中心在 x=\(String(format: "%.1f", sentenceMidX))，面板中心在 "
                          + "\(String(format: "%.1f", panelMidX)) ⇒ 差 \(String(format: "%.1f", abs(sentenceMidX - panelMidX)))pt。"
                          + "它的框不再等宽于面板时，`alignment = .center` 只是在一条偏掉的带子里居中")

        // 第二档：**长查询词**。上面那条短查询的句子比面板窄，所以"框被撑到面板外"这件事
        // 它看不见 —— 而 `lineBreakMode = .byTruncatingTail` 只在自己的框里截，
        // 框一旦比面板宽，两端就被面板硬切，省略号根本没机会出现。
        // 这一档是"那句话的等宽约束到底有没有作者"的答案：M332 单独撤它时判据全绿
        // （短查询下默认对齐也居中），只有这一档能把它判红。
        let longQuery = String(repeating: "很长的搜索词", count: 8)
        let longBuild = QuickPickCapturePanel.builder(store: makePopulatedStore(), query: longQuery)
        guard let longPanel = longBuild(), let longContent = longPanel.contentView else {
            return XCTFail("长查询词那一档建不出浮层 ⇒ 这条判据没有对象")
        }
        defer { longPanel.orderOut(nil) }
        longPanel.setFrameOrigin(NSPoint(x: -20006, y: -20006))
        longPanel.orderFrontRegardless()
        RunLoop.main.run(until: Date().addingTimeInterval(0.2))
        Self.tileScrollViews(in: longContent)
        longPanel.display()
        RunLoop.main.run(until: Date().addingTimeInterval(0.05))
        var longSentence: NSTextField?
        func findLong(_ view: NSView) {
            if let tf = view as? NSTextField, tf.identifier?.rawValue == "quickPickEmptyMessage" {
                longSentence = tf
            }
            view.subviews.forEach(findLong)
        }
        findLong(longContent)
        guard let longLabel = longSentence else {
            return XCTFail("长查询词那一档没找到那句话 ⇒ 空结果态在长查询下根本没说话")
        }
        guard let longRect = Self.frame(longLabel, in: longContent) else {
            return XCTFail("长查询那一档换算不到 content 坐标系 ⇒ 判据没有对象")
        }
        emit("QUICKPICK_LONG_QUERY 句子 frame=\(NSStringFromRect(longRect)) "
              + "面板=\(NSStringFromRect(longContent.bounds)) 文本长度=\(longLabel.stringValue.count)")
        // **面板不许因为内容变宽**。这一条不是"防回归"，它防的是本轮自己改出来的东西：
        // 把 stack 钉到面板上之后，"内容要多宽"第一次传到了窗口 ——
        // 修之前实测面板被顶到 899pt（`contentResizeIncrements` 救不了，那是 Auto Layout 在推 frame）。
        // 判据写成"两个状态的面板同宽"而不是"面板等于 420"：面板尺寸是产品定的，
        // 而"它不随查询词长度变化"才是这条判据真正守的约定。
        XCTAssertEqual(longContent.bounds.width, content.bounds.width, accuracy: 0.5,
                       "长查询词把浮层面板从 \(Int(content.bounds.width))pt 顶到了 "
                       + "\(Int(longContent.bounds.width))pt ⇒ 这个浮层的设计前提是「固定尺寸、呼出即输入」，"
                       + "而句子的长度是用户决定的。谁在决定面板宽度，这里就露出来了")
        XCTAssertGreaterThanOrEqual(longRect.minX, longContent.bounds.minX,
                                    "那句话的左边伸出面板 \(Int(longContent.bounds.minX - longRect.minX))pt ⇒ "
                                    + "它被面板硬切而不是被省略号截断。它的等宽约束是这一条的承重墙")
        XCTAssertLessThanOrEqual(longRect.maxX, longContent.bounds.maxX,
                                 "那句话的右边伸出面板 \(Int(longRect.maxX - longContent.bounds.maxX))pt ⇒ "
                                 + "同一族：用户读到的是被切掉一半的字，而不是「换个词或按 Esc 清空」")
        XCTAssertLessThan(abs(longRect.midX - longContent.bounds.midX), 3,
                          "长查询下那句话的中心偏了 \(String(format: "%.1f", abs(longRect.midX - longContent.bounds.midX)))pt")
        // 截断必须**真的发生**：不截断而只是"面板变宽"的话，上面四条可以一起绿。
        // 这里不用 `NSCell.truncatedStr`（那是方法不是属性，且要自己算 textRange）——
        // "实际宽度 < 固有宽度"就是"它被压过"的充分证据，而 `.byTruncatingTail` 只在被压时出省略号。
        XCTAssertTrue(longRect.width < longLabel.intrinsicContentSize.width,
                      "句子实际宽 \(Int(longRect.width))pt，而它的固有宽度是 "
                      + "\(Int(longLabel.intrinsicContentSize.width))pt ⇒ 它没有被压过。"
                      + "那说明这一档要么在靠面板变宽让位（上面那条同宽判据该红），"
                      + "要么根本没截出省略号 —— 两种都等于这一档什么都没判")
    }

    /// 不覆盖管线：这是选择器的纯函数契约；像素证人在 `testInlineCodeBackgroundHasPadding`。
    func testInlineCodeBandChoicePrefersTheCoveredRun() {
        let trueBand = InlineCodeBandChoice.Candidate(row: 10, left: 40, right: 124, coverage: 0.9, ink: 80, padding: 6, rowMaxBandRun: 85)
        let falseBand = InlineCodeBandChoice.Candidate(row: 20, left: 20, right: 169, coverage: 0.55, ink: 147, padding: 3, rowMaxBandRun: 150)
        let subBand = InlineCodeBandChoice.Candidate(row: 15, left: 50, right: 128, coverage: 1.0, ink: 78, padding: 1, rowMaxBandRun: 79)
        XCTAssertEqual(InlineCodeBandChoice.best([trueBand, falseBand, subBand], minSpan: 40, maxSpan: 150,
                                                 minCoverage: 0.55, minInk: 6)?.row, 10,
                       "假文字带（padding 3）与带内子段（padding 1）都不该盖过真带（padding 6）")
        XCTAssertNil(InlineCodeBandChoice.best([falseBand], minSpan: 40, maxSpan: 150,
                                               minCoverage: 0.56, minInk: 6),
                     "覆盖率不足的假带必须被排除（不是靠上界藏）")
        let tooWide = InlineCodeBandChoice.Candidate(row: 30, left: 0, right: 159, coverage: 1.0, ink: 80, padding: 6, rowMaxBandRun: 160)
        XCTAssertNil(InlineCodeBandChoice.best([tooWide], minSpan: 40, maxSpan: 150,
                                               minCoverage: 0.55, minInk: 6),
                     "超过 150pt 的 run 不是行内码带")
        // R470：runner dark 的 150/147/3.0 是 320pt code-block 底里的一段；它的 padding 20
        // （块底无字）会压过真带的 6 ⇒ 必须靠「整行最长带 run > 150」把它整行排除。
        let blockSegment = InlineCodeBandChoice.Candidate(row: 40, left: 30, right: 179, coverage: 1.0, ink: 147, padding: 20, rowMaxBandRun: 320)
        XCTAssertEqual(InlineCodeBandChoice.best([blockSegment, trueBand], minSpan: 40, maxSpan: 150,
                                                 minCoverage: 0.55, minInk: 6)?.row, 10,
                       "全宽块底那一行上的 150pt 碎片必须被排除，真带（padding 6）胜出")
        XCTAssertNil(InlineCodeBandChoice.best([blockSegment], minSpan: 40, maxSpan: 150,
                                               minCoverage: 0.55, minInk: 6),
                     "只剩全宽块底碎片时必须是 nil，不许拿它冒充行内码带")
    }

    /// R476：ink 门读**带上下窗口**里的墨，不读"这一行有没有字"。
    ///
    /// runner dark 的四门分桶是 `过span=12 → 过coverage=12 → 过ink=1 → 过rowMax=0`：
    /// 完整 99pt 的带只出现在文字上下的 padding 行（那一行自身 ink=0），文字行则被字形
    /// 切短并落在 320pt 块底那一行（被 rowMax 排掉）。所以"这一行有字"这道门把真带整族砍掉。
    /// 这一格用三个合成件钉住新语义：padding 行（本行 ink=0、窗口有字）必须能当选；
    /// 窗口里也没有字的 padding 行必须仍被拒；文字行碎片不能凭 padding 抢走它。
    func testInlineCodeBandChoiceReadsInkInTheVerticalWindow() {
        let paddingRow = InlineCodeBandChoice.Candidate(
            row: 10, left: 40, right: 159, coverage: 1.0, ink: 0,
            padding: 6, rowMaxBandRun: 120, verticalInk: 80)
        let textFragment = InlineCodeBandChoice.Candidate(
            row: 11, left: 40, right: 79, coverage: 0.8, ink: 80,
            padding: 2, rowMaxBandRun: 120)
        XCTAssertEqual(InlineCodeBandChoice.best([paddingRow, textFragment],
                                                 minSpan: 80, maxSpan: 300,
                                                 minCoverage: 0.55, minInk: 24)?.row, 10,
                       "完整带只在 padding 行上（ink=0、verticalInk=80）⇒ 它必须能当选，"
                       + "不能被同一条带被字形切碎后的短 run 抢走")
        let emptyPadding = InlineCodeBandChoice.Candidate(
            row: 20, left: 40, right: 159, coverage: 1.0, ink: 0,
            padding: 6, rowMaxBandRun: 120, verticalInk: 0)
        XCTAssertNil(InlineCodeBandChoice.best([emptyPadding], minSpan: 80, maxSpan: 300,
                                               minCoverage: 0.55, minInk: 24),
                     "窗口里也没有字的 padding 行仍必须被拒 —— 这道门不是「有带就放行」")
        // R476：对象是**整条带**，不是被字形切碎后 padding 虚高的碎片。
        let wideBand = InlineCodeBandChoice.Candidate(
            row: 1, left: 20, right: 118, coverage: 1.0, ink: 0,
            padding: 6.0, rowMaxBandRun: 99, verticalInk: 80)
        let narrowRich = InlineCodeBandChoice.Candidate(
            row: 2, left: 20, right: 62, coverage: 1.0, ink: 0,
            padding: 9.0, rowMaxBandRun: 99, verticalInk: 80)
        XCTAssertEqual(InlineCodeBandChoice.best([narrowRich, wideBand], minSpan: 40, maxSpan: 300,
                                                 minCoverage: 0.55, minInk: 24)?.row, 1,
                       "实心带里取最宽的那条：碎片 padding 9 不能把整条 99pt 带的 6.0 挤掉")
        // R477：runner light 上有一条 102/101/1.0 的宽带，真带 85/80/5.0。
        // 先过 4.5 地板再取最宽 —— 否则宽带会把没有内边距的那条顶上来。
        let wideNoPadding = InlineCodeBandChoice.Candidate(
            row: 3, left: 20, right: 121, coverage: 1.0, ink: 0,
            padding: 1.0, rowMaxBandRun: 102, verticalInk: 80)
        let truePadded = InlineCodeBandChoice.Candidate(
            row: 4, left: 20, right: 104, coverage: 1.0, ink: 0,
            padding: 5.0, rowMaxBandRun: 85, verticalInk: 80)
        XCTAssertEqual(InlineCodeBandChoice.best([wideNoPadding, truePadded], minSpan: 40, maxSpan: 300,
                                                 minCoverage: 0.55, minInk: 24)?.row, 4,
                       "102/1.0 的宽带不过 4.5 地板，真带 85/5.0 必须胜出")
    }

    /// R471：截断说明是**界面说明**，字号必须小于正文（不是最后一段内容）。
    ///
    /// 判据从产品渲染出的 NSTextView 读：说明出现次数、说明的 `.font` 与正文的 `.font`。
    /// 相对量（说明 < 正文 −1pt），不抄产品字号常数。像素帧 `detail-markdown-truncated` 滚到底。
    func testTruncationNoteSitsBelowTheBodyTier() throws {
        let scratch = FileManager.default.temporaryDirectory
            .appendingPathComponent("r471-truncation-\(UUID().uuidString)", isDirectory: true)
        try FileManager.default.createDirectory(at: scratch, withIntermediateDirectories: true)
        defer { try? FileManager.default.removeItem(at: scratch) }

        let parsed = MarkdownParser.parse(Self.truncatedFixtureBody)
        let parsedText = MarkdownPresentation.attributedString(for: parsed)
        emit("TRUNCATION_PARSE 截断=\(parsed.isTruncated) 块=\(parsed.blocks.count)"
             + " 属性串长=\(parsedText.length) 含说明=\(parsedText.string.contains(MarkdownParsingPolicy.truncationNote))")
        var judged = 0
        for appearance in [NSAppearance.Name.aqua, .darkAqua] {
            let tag = appearance == .darkAqua ? "dark" : "light"
            guard let fixture = fixtures(appearance: appearance)
                .first(where: { $0.name == "detail-markdown-truncated" }) else {
                return XCTFail("\(tag)：找不到 `detail-markdown-truncated` ⇒ 这条判据没有对象")
            }
            let file = scratch.appendingPathComponent("truncated-\(tag).png")
            var noteSize: CGFloat = -1, bodySize: CGFloat = -1, noteCount = 0
            var textFound = false, textLength = 0
            var prefix = "", suffix = "", hasHeading = false, hasNoteText = false
            _ = try render(fixture, appearance: appearance, to: file, inspect: { host in
                var stack: [NSView] = [host]
                var textView: ChineseSelectableNSTextView?
                while let view = stack.popLast() {
                    if let text = view as? ChineseSelectableNSTextView { textView = text; break }
                    stack.append(contentsOf: view.subviews)
                }
                guard let text = textView else { return }
                textFound = true
                textLength = text.string.count
                prefix = String(text.string.prefix(60))
                suffix = String(text.string.suffix(80))
                hasHeading = text.string.contains("# 截断")
                hasNoteText = text.string.contains("后面的内容没有渲染")
                let ns = text.string as NSString
                let noteRange = ns.range(of: MarkdownParsingPolicy.truncationNote)
                let bodyRange = ns.range(of: "这是一段用于截断提示验收的长文本")
                guard noteRange.location != NSNotFound, bodyRange.location != NSNotFound else { return }
                noteCount = ns.components(separatedBy: MarkdownParsingPolicy.truncationNote).count - 1
                let attr = text.attributedString()
                if let font = attr.attribute(.font, at: noteRange.location, effectiveRange: nil) as? NSFont {
                    noteSize = font.pointSize
                }
                if let font = attr.attribute(.font, at: bodyRange.location, effectiveRange: nil) as? NSFont {
                    bodySize = font.pointSize
                }
            })
            emit("TRUNCATION_NOTE \(tag) 找到=\(textFound) 文长=\(textLength) 说明字号=\(noteSize) 正文字号=\(bodySize) 说明出现=\(noteCount)"
                 + " 标题标记=\(hasHeading) 说明文本=\(hasNoteText) 首=\(prefix.debugDescription) 尾=\(suffix.debugDescription)")
            guard noteSize > 0, bodySize > 0, noteCount == 1 else {
                emit("TRUNCATION_NOTE_NOT_RUN=\(tag) 说明或正文没有读到")
                continue
            }
            judged += 1
            XCTAssertLessThan(noteSize, bodySize,
                              "\(tag)：截断说明 \(noteSize)pt 不小于正文 \(bodySize)pt ⇒ 它会被读成最后一段内容")
            XCTAssertLessThanOrEqual(noteSize, bodySize - 1.0,
                                     "\(tag)：说明与正文字号只差 \(bodySize - noteSize)pt（<1）⇒ 层级没有拉开")
        }
        if judged == 0 { throw XCTSkip("TRUNCATION_NOTE_NOT_RUN：两种外观下都没有对象") }
    }

    /// R473：数据页也要说出保存位置（隐私卡里有，但用户找"存在哪"时在数据页）。
    ///
    /// 判据读帧：路径行是**Latin 密集**的一行。2x 数"窄字簇"（宽 ≤9pt，Latin 字形；
    /// CJK 与正文说明的宽字簇不算），1x 字形会连成词 ⇒ 改数总词簇（路径有空格，CJK 说明没有）。
    /// 阈值按倍率取（不把 2x 的 20 抄到 1x）：2x ≥20 个窄簇、1x ≥5 个词簇。
    func testSettingsDataPageShowsTheStoragePath() throws {
        let scratch = FileManager.default.temporaryDirectory
            .appendingPathComponent("r473-data-path-\(UUID().uuidString)", isDirectory: true)
        try FileManager.default.createDirectory(at: scratch, withIntermediateDirectories: true)
        defer { try? FileManager.default.removeItem(at: scratch) }

        var judged = 0
        for appearance in [NSAppearance.Name.aqua, .darkAqua] {
            let tag = appearance == .darkAqua ? "dark" : "light"
            guard let fixture = fixtures(appearance: appearance)
                .first(where: { $0.name == "settings-data" }) else {
                return XCTFail("\(tag)：找不到 `settings-data` ⇒ 这条判据没有对象")
            }
            let file = scratch.appendingPathComponent("settings-data-\(tag).png")
            _ = try render(fixture, appearance: appearance, to: file)
            guard let data = try? Data(contentsOf: file),
                  let rep = NSBitmapImageRep(data: data), let base = rep.bitmapData else {
                XCTFail("\(tag)：settings-data 帧读不回字节")
                continue
            }
            let scale = Double(rep.pixelsWide) / 720.0
            let width = rep.pixelsWide, height = rep.pixelsHigh
            let bytesPerRow = rep.bytesPerRow, spp = rep.samplesPerPixel
            let alphaFirst = rep.bitmapFormat.contains(.alphaFirst)
            let rOff = alphaFirst ? 1 : 0
            func luma(_ x: Int, _ y: Int) -> Double {
                let o = y * bytesPerRow + x * spp
                return 0.299 * Double(base[o + rOff]) + 0.587 * Double(base[o + rOff + 1])
                    + 0.114 * Double(base[o + rOff + 2])
            }
            let x0 = Int((SettingsViewLayout.sidebarWidth + 12) * scale)
            let x1 = min(width, Int((fixture.size.width - 12) * scale))
            var histogram: [Int: Int] = [:]
            for y in stride(from: Int(80 * scale), to: height, by: 2) {
                for x in stride(from: x0, to: x1, by: 2) { histogram[Int(luma(x, y)) / 4, default: 0] += 1 }
            }
            let page = Double((histogram.max { $0.value < $1.value }?.key ?? 0) * 4 + 2)
            func isInk(_ x: Int, _ y: Int) -> Bool { abs(luma(x, y) - page) > 30 }
            var bands: [(top: Int, bottom: Int)] = []
            var top = -1
            for y in Int(80 * scale)..<height {
                var has = false
                for x in x0..<x1 where isInk(x, y) { has = true; break }
                if has && top < 0 { top = y }
                if !has && top >= 0 { bands.append((top, y - 1)); top = -1 }
            }
            if top >= 0 { bands.append((top, height - 1)) }
            // 路径行是**等宽**的：窄簇的起点间隔应围着产品 pathFont 的 advance 连跑。
            // 旧帧里最密的那条是 CJK 导出说明（窄簇 37 个，但等距连跑只有 3）⇒ 不能只数簇。
            let advance = ("0" as NSString).size(withAttributes: [.font: SettingsPathPresentation.pathFont]).width
            var maxRun = 0, maxTotal = 0, best = ""
            for band in bands {
                var cols = [Bool](repeating: false, count: x1 - x0)
                for y in band.top...band.bottom {
                    for x in x0..<x1 where isInk(x, y) { cols[x - x0] = true }
                }
                var clusters: [(Int, Int)] = []
                var start = -1
                for i in 0..<cols.count {
                    if cols[i] { if start < 0 { start = i } }
                    else if start >= 0 { clusters.append((start, i - 1)); start = -1 }
                }
                if start >= 0 { clusters.append((start, cols.count - 1)) }
                let narrow = clusters.filter { Double($0.1 - $0.0 + 1) / scale <= 9.0 }
                var run = 0, bandRun = 0
                var prev: Int?
                for cluster in narrow {
                    if let previous = prev {
                        let delta = Double(cluster.0 - previous) / scale
                        if abs(delta - advance) <= 1.0 { run += 1 } else { run = 1 }
                    } else { run = 1 }
                    bandRun = max(bandRun, run)
                    prev = cluster.0
                }
                if bandRun > maxRun {
                    maxRun = bandRun
                    best = "y=\(band.top)..\(band.bottom) 簇=\(clusters.count) 窄=\(narrow.count) 等距连跑=\(bandRun)"
                }
                maxTotal = max(maxTotal, clusters.count)
            }
            emit("SETTINGS_DATA_PATH \(tag) 带数=\(bands.count) 最大等距连跑=\(maxRun) 最大总簇=\(maxTotal) advance=\(String(format: "%.1f", advance)) \(best)")
            guard bands.count >= 5 else {
                emit("SETTINGS_DATA_PATH_NOT_RUN=settings-content-blank \(tag) 带数=\(bands.count)")
                continue
            }
            judged += 1
            if scale >= 1.5 {
                XCTAssertGreaterThanOrEqual(maxRun, 10,
                    "\(tag)：数据页没有等宽路径行（最大等距连跑 \(maxRun)）⇒ 保存位置没画出来")
            } else {
                XCTAssertGreaterThanOrEqual(maxTotal, 5,
                    "\(tag)：1x 上数据页没有带空格的路径行（最大词簇 \(maxTotal)）⇒ 保存位置没画出来")
            }
        }
        if judged == 0 { throw XCTSkip("SETTINGS_DATA_PATH_NOT_RUN：两种外观下都没有设置内容") }
    }

    func testCaptureKeyViews() throws {
        guard let directory = outputDirectory else {
            throw XCTSkip("未设置 CLIPBOARD_HISTORY_UI_SHOTS，跳过离屏渲染")
        }
        var report: [(name: String, metrics: CaptureMetrics)] = []
        /// 哪些夹具声明了"内容必须整块放得下"。**从夹具自己读**，不在判据里另抄一份名单
        /// （两处各写一份的话，加一条夹具只会红一半 —— R18 那条"两处各写一个数"同族）。
        var mustFitNames: Set<String> = []
        /// 夹具机械自己也要有一条判据：**谁种了默认值，谁必须还原**。
        /// 不还原的污染是静默的 —— 后面的帧照样画得出来，只是多了两行本来不在那一页的东西，
        /// 而基线会把那份污染当成"产品长这样"钉住（`--against working` 从此永远比不回来）。
        var originalSeeds: [String: String?] = [:]
        for appearance in [NSAppearance.Name.aqua, .darkAqua] {
            let tag = appearance == .darkAqua ? "dark" : "light"
            for fixture in fixtures(appearance: appearance) {
                let file = directory.appendingPathComponent(
                    "\(fixture.name)-\(Int(fixture.size.width))x\(Int(fixture.size.height))-\(tag).png"
                )
                /// R98：这里**不再种、也不再还原** —— 那两件事搬进了 `render`（见那里的注释）。
                /// 留下来的只有"记一下种之前是什么"，因为最后那条断言要拿它对照：
                /// 现在它判的是 `render` 有没有还原，而不是"调用方有没有记得还原"。
                if let seed = fixture.seed, !originalSeeds.keys.contains(seed.key) {
                    originalSeeds[seed.key] = UserDefaults.standard.string(forKey: seed.key)
                }
                let metrics = try render(fixture, appearance: appearance, to: file)
                if fixture.contentMustFit { mustFitNames.insert(fixture.name) }
                report.append((file.lastPathComponent, metrics))
            }
        }

        for (key, original) in originalSeeds {
            XCTAssertEqual(UserDefaults.standard.string(forKey: key), original,
                           "种子键 \(key) 拍完之后没还原 ⇒ 同一进程里后面的测试与下一轮帧都会读到上一张帧的夹具")
        }

        // **这台机器能判哪几条**（R36 / BACKLOG 49 / U-59）。存在的理由不是宽容，是**换个问法**：
        // runner 上有 4 条红被 report-only 那一步吞掉了（一条正对照读 0%、两条"捕获失效"、
        // 一条"材质黑带消失了"），没有一条是产品 —— 可"红了没人看"和"没有红"在报表里长得一样，
        // 于是那一步既拦不住真缺陷，也记不下"今天到底判了多少"。
        // 现在：这台机器判不了的**那一条**登记成 `*_NOT_RUN`（带读数、带原因），
        // 其余任何一条红都必须是新的、有名字的 ⇒ 工作流那一步从此可以带闸门
        // （`python3 scripts/ci_capture_gate.py`，它的正对照就是下面那 4 行逐字日志）。
        // —— 三条前提，各自只看它要判的那个量 ——
        // 这一块的上一版写的是"settings 族画不画得出来 / List 族画不画得出来"两句话。
        // 听起来干净，实际是**一把尺管三件事**：它同时决定"95% 未绘制"要不要放行、
        // 正对照要不要跑、黑带名单要不要比 —— 而 runner 的逐帧实测（run 38473962277，
        // 片段已钉进 `scripts/tests/fixtures/r36_runner_capture.log`）说这三件事方向各不相同：
        //   · settings 族：本机未绘制 20.8–78.8%，runner 90.6–95.9% ⇒ 这一族在 CI 上**整体空白**；
        //   · sidebar / content 族：两台机器都画得出来（未绘制 0.0%），可 runner 上**一张黑带都没有**
        //     （本机 9 张），而且 sidebar 亮色版底行墨 0.0%、同一帧暗色版 100.0%；
        //   · 底行墨这把尺本身在两台机器上都是活的（detail 族两边都读到 100.0%）。
        // 于是"某一族画不出来"这句话既放过过不该放的，也红过不该红的。
        // 现在三条前提各自独立、全部是**在这台机器上量出来的**，没有一条靠"这是 CI"这种身份判断。
        let readings = report.map { item in
            CaptureCapability.Reading(
                fixture: Self.fixtureName(fromFile: item.name),
                family: Self.fixtureName(fromFile: item.name).components(separatedBy: "-").first ?? "",
                transparent: item.metrics.transparent,
                blackBandPt: item.metrics.blackBandPt,
                bottomInkFraction: item.metrics.bottomInkFraction)
        }
        let capability = CaptureCapability.measure(readings)
        let settingsFamilyIsBlank = capability.settingsFamilyIsBlank
        let settingsLowestBlank = capability.settingsLowestBlank
        let bandsSeenHere = capability.bandsSeenHere
        emit("CAPTURE_CAPABILITY settings族整体空白=\(settingsFamilyIsBlank ? "是" : "否")"
              + "（族内最低未绘制 " + String(format: "%.1f", settingsLowestBlank * 100) + "% / "
              + "\(readings.filter { $0.family == "settings" }.count) 张）"
              + " / 这一台见过黑带=\(bandsSeenHere ? "是" : "否")")

        emit("CAPTURED \(report.count) -> \(directory.path)")
        for item in report {
            emit("  \(item.name)  transparent=\(String(format: "%.1f", item.metrics.transparent * 100))%"
                  + "  blackBandPt=\(String(format: "%.0f", item.metrics.blackBandPt))"
                  + "  bottomInk=\(String(format: "%.1f", item.metrics.bottomInkFraction * 100))%")
        }

        // R392：整页录制帧必须真的拍到那一圈强调色。R273 的 fixture 只等
        // `button.layer` 的动画键，而强调圈是 SwiftUI overlay、动画不在那层 ⇒
        // 快门落在圈还透明的时候：录制帧与静置帧的差集只覆盖标题文字，控件四周
        // 0 个高色度像素。修好等待之后本机现读 亮 1794 / 暗 1788 颗，差集 bbox
        // 正好是控件四边 (966,503)..(1221,550)。这条判据只看颜色/差分，不钉矩形几何；
        // 平涂页走既有能力闸门，记具名 NOT-RUN，不把「没画」读成「产品没画」。
        if settingsFamilyIsBlank {
            emit("RECORDER_FRAME_RING_NOT_RUN=flat-page：settings 族整体空白（本机最低未绘制 "
                 + String(format: "%.1f", settingsLowestBlank * 100) + "%）⇒ 整页录制帧判不了")
        } else {
            func loadFrame(_ name: String) -> NSBitmapImageRep? {
                let url = directory.appendingPathComponent(name)
                guard let image = NSImage(contentsOf: url) else { return nil }
                return NSBitmapImageRep(data: image.tiffRepresentation ?? Data())
            }
            func ringReading(_ recording: NSBitmapImageRep, _ idle: NSBitmapImageRep) -> (diff: Int, recBlue: Int, idleBlue: Int, box: CGRect) {
                let w = min(recording.pixelsWide, idle.pixelsWide)
                let h = min(recording.pixelsHigh, idle.pixelsHigh)
                func blue(_ c: NSColor) -> Bool {
                    let r = c.redComponent, g = c.greenComponent, b = c.blueComponent
                    return b > r + 0.08 && b > g + 0.04 && b > 0.31
                }
                // R399 CI 归因：runner 的录制/静置整页帧布局会不同，whole-page diff 把
                // 侧栏强调蓝也卷进来（现读 idleBlue=4284/465，bbox 覆盖整页），
                // 于是这条只数**产品那颗录制控件自己的带**。坐标来自 R392 的环 bbox
                // (966,503)..(1221,550)@2x ⇒ x 470..620、y 240..285pt；band 是判据的取样窗，
                // 不是产品几何。平涂页仍走上面的具名 NOT-RUN。
                let scale = Double(w) / 720.0
                let bx0 = Int(470 * scale), bx1 = min(w, Int(620 * scale))
                let by0 = Int(240 * scale), by1 = min(h, Int(285 * scale))
                var diff = 0, recBlue = 0, idleBlue = 0
                var minX = w, minY = h, maxX = -1, maxY = -1
                for y in by0..<by1 {
                    for x in bx0..<bx1 {
                        guard let a = recording.colorAt(x: x, y: y),
                              let b = idle.colorAt(x: x, y: y) else { continue }
                        let changed = (a.redComponent, a.greenComponent, a.blueComponent)
                            != (b.redComponent, b.greenComponent, b.blueComponent)
                        guard changed else { continue }
                        diff += 1
                        if blue(a) { recBlue += 1 }
                        if blue(b) { idleBlue += 1 }
                        minX = min(minX, x); maxX = max(maxX, x)
                        minY = min(minY, y); maxY = max(maxY, y)
                    }
                }
                return (diff, recBlue, idleBlue,
                        maxX >= minX ? CGRect(x: minX, y: minY, width: maxX - minX + 1, height: maxY - minY + 1) : .zero)
            }
            for tag in ["light", "dark"] {
                let recName = "settings-shortcuts-recording-720x540-\(tag).png"
                let idleName = "settings-shortcuts-720x540-\(tag).png"
                guard let rec = loadFrame(recName), let idle = loadFrame(idleName) else {
                    XCTFail("RECORDER_FRAME_RING_MISSING：\(tag) 录制/静置帧不在捕获目录 ⇒ 这条判据没有对象")
                    continue
                }
                let r = ringReading(rec, idle)
                emit("RECORDER_FRAME_RING \(tag) 变化=\(r.diff) 录制侧蓝=\(r.recBlue) 静置侧蓝=\(r.idleBlue)"
                     + " bbox=(\(Int(r.box.minX)),\(Int(r.box.minY)))..(\(Int(r.box.maxX)),\(Int(r.box.maxY)))")
                XCTAssertGreaterThan(r.diff, 100,
                                     "\(tag)：录制帧与静置帧几乎相同（变化=\(r.diff)）⇒ 这一帧没拍到录制态")
                XCTAssertGreaterThanOrEqual(r.recBlue, 200,
                                            "\(tag)：录制帧里只有 \(r.recBlue) 颗强调蓝（要 ≥200）"
                                                + " ⇒ 整页帧把「我在听」那一圈拍丢了；先查 fixture 等的是不是只有 button.layer")
                XCTAssertEqual(r.idleBlue, 0,
                               "\(tag)：静置帧在变化处也读到 \(r.idleBlue) 颗强调蓝 ⇒ 那一圈在没录制时也在画")
            }
        }

        // R412：行级录制态（描边）必须**只落在正在录制的那一行**，邻行不动。
        // 与上面的环判据分开取样：那条量的是 128×28 的录音器，这条量的是它左边的标题/说明带
        // （环的 bbox 从 x≈470pt 起，这条带止于 480pt，两把尺不互相借证据）。
        if settingsFamilyIsBlank {
            emit("RECORDER_ROW_EDGE_NOT_RUN=flat-page：settings 族整体空白（本机最低未绘制 "
                 + String(format: "%.1f", settingsLowestBlank * 100) + "%）⇒ 行级录制帧判不了")
        } else {
            func loadFrame(_ name: String) -> NSBitmapImageRep? {
                let url = directory.appendingPathComponent(name)
                guard let image = NSImage(contentsOf: url) else { return nil }
                return NSBitmapImageRep(data: image.tiffRepresentation ?? Data())
            }
            // 点是捕获帧的 pt 坐标；行带覆盖第三行标题/说明与描边的上/下/左边，
            // 邻行带取第二行同一列。两带都要先过能力闸门，平涂页走上面的具名 NOT-RUN。
            let rowBand = CGRect(x: 175, y: 224, width: 305, height: 74)
            let neighborBand = CGRect(x: 175, y: 150, width: 305, height: 68)
            for tag in ["light", "dark"] {
                let recName = "settings-shortcuts-recording-720x540-\(tag).png"
                let idleName = "settings-shortcuts-720x540-\(tag).png"
                guard let rec = loadFrame(recName), let idle = loadFrame(idleName) else {
                    XCTFail("RECORDER_ROW_EDGE_MISSING：\(tag) 录制/静置帧不在捕获目录 ⇒ 这条判据没有对象")
                    continue
                }
                let scale = Double(rec.pixelsWide) / 720.0
                let row = RecorderRowEdgeRuler.read(recording: rec, idle: idle,
                                                    bandPoints: rowBand, frameWidthPoints: 720)
                let neighbor = RecorderRowEdgeRuler.read(recording: rec, idle: idle,
                                                          bandPoints: neighborBand, frameWidthPoints: 720)
                emit("RECORDER_ROW_EDGE \(tag) 缩放=\(String(format: "%.1f", scale))x "
                     + "行带变化=\(row.changed) 行带强调=\(row.accentChanged) 行带总数=\(row.total) "
                     + "邻行变化=\(neighbor.changed) 邻行强调=\(neighbor.accentChanged)")
                XCTAssertGreaterThanOrEqual(row.changed, 500,
                                            "\(tag)：录制/静置在行带里只差 \(row.changed) 个像素 ⇒ 行级描边没画上")
                XCTAssertGreaterThanOrEqual(row.accentChanged, 400,
                                            "\(tag)：行带里只有 \(row.accentChanged) 颗强调色（要 ≥400）"
                                                + " ⇒ 行级状态没有可读的形状")
                XCTAssertEqual(neighbor.accentChanged, 0,
                               "\(tag)：邻行读到 \(neighbor.accentChanged) 颗强调色 ⇒ 行级状态画到了错误的行")
                // runner 1x 的 idle/recording 两帧有整页 1 级底色差（邻行 changed=100%、强调=0），
                // 那是窗口焦点变化的通道底色，不是描边泄漏。隔离判据认**强调色**；
                // 任意变化那一格只作读数，不判（R412 的 20740/0 就是这条）。
                emit("RECORDER_ROW_EDGE_TINT \(tag) 邻行任意变化=\(neighbor.changed) "
                     + "邻行强调=\(neighbor.accentChanged) ⇒ 任意变化只记读数；隔离看强调")
            }
        }

        // R414：设置侧栏选中胶囊的三态。静置/中点/落定各一帧，x 带取胶囊左缘与文字之间，
        // 中心必须从起点走到中点再到落点；旧的每行各自淡入淡出在中点会停在落点（红）。
        func loadSidebarSelectionFrame(_ name: String) -> NSBitmapImageRep? {
            let url = directory.appendingPathComponent(name)
            guard let image = NSImage(contentsOf: url) else { return nil }
            return NSBitmapImageRep(data: image.tiffRepresentation ?? Data())
        }
        for tag in ["light", "dark"] {
            let names = ["idle", "mid", "end"].map {
                "settingssidebar-selection-\($0)-300x200-\(tag).png"
            }
            guard let idle = loadSidebarSelectionFrame(names[0]),
                  let mid = loadSidebarSelectionFrame(names[1]),
                  let end = loadSidebarSelectionFrame(names[2]) else {
                XCTFail("SETTINGS_SIDEBAR_SELECTION_MISSING：\(tag) 三态帧不在捕获目录 ⇒ 这条判据没有对象")
                continue
            }
            let idleRead = SettingsSidebarCapsuleRuler.center(recording: idle, frameWidthPoints: 300)
            let midRead = SettingsSidebarCapsuleRuler.center(recording: mid, frameWidthPoints: 300)
            let endRead = SettingsSidebarCapsuleRuler.center(recording: end, frameWidthPoints: 300)
            emit("SETTINGS_SIDEBAR_SELECTION_CAPSULE \(tag) 静置=\(String(format: "%.1f", idleRead.centerY))pt/\(idleRead.count) "
                 + "中点=\(String(format: "%.1f", midRead.centerY))pt/\(midRead.count) "
                 + "落定=\(String(format: "%.1f", endRead.centerY))pt/\(endRead.count)")
            XCTAssertGreaterThan(idleRead.count, 20, "\(tag)：静置帧没有读到胶囊底色")
            XCTAssertGreaterThan(midRead.count, 20, "\(tag)：中点帧没有读到胶囊底色")
            XCTAssertGreaterThan(endRead.count, 20, "\(tag)：落定帧没有读到胶囊底色")
            XCTAssertGreaterThan(midRead.centerY, idleRead.centerY + 5,
                                 "\(tag)：中点没有离开起点（\(midRead.centerY) vs \(idleRead.centerY)）⇒ 胶囊在跳")
            XCTAssertLessThan(midRead.centerY, endRead.centerY - 5,
                              "\(tag)：中点已经到落点（\(midRead.centerY) vs \(endRead.centerY)）⇒ 中段帧替瞬移作证")
            XCTAssertGreaterThan(endRead.centerY, idleRead.centerY + 20,
                                 "\(tag)：起点与落定没有拉开一行 ⇒ 夹具/尺坏了")
        }

        // R396：不支持登录项时，复选框可以禁用，但「开机启动」标签必须仍可读。
        // 整页 captured frame 的旧结构实测 亮 1.76 / 暗 2.13:1（低于禁用标签地板 2.2）；
        // 新结构 2.84 / 4.38。只读第一行标签自己的语义带（x 195..255、y 118..135pt）——
        // 先按字墨 bbox 定位再看图：R396 第一版写成 x 380..700 / y 225..275，
        // 实际量的是第三行「识别截图文字」，旧结构也能读 2.81（假绿）。
        // 捕获产物是 top-left，不做上/下二选一。
        if settingsFamilyIsBlank {
            emit("LOGIN_UNSUPPORTED_FRAME_NOT_RUN=flat-page：settings 族整体空白")
        } else {
            func loadFrame(_ name: String) -> NSBitmapImageRep? {
                let url = directory.appendingPathComponent(name)
                guard let image = NSImage(contentsOf: url) else { return nil }
                return NSBitmapImageRep(data: image.tiffRepresentation ?? Data())
            }
            func reading(_ rep: NSBitmapImageRep, flipped: Bool) -> (fill: Int, ink: Int, contrast: Double) {
                let scale = Double(rep.pixelsWide) / 720.0
                let x0 = Int(195 * scale), x1 = Int(255 * scale)
                let y0p = Int(118 * scale), y1p = Int(135 * scale)
                let y0 = flipped ? rep.pixelsHigh - y1p : y0p
                let y1 = flipped ? rep.pixelsHigh - y0p : y1p
                guard let base = rep.bitmapData else { return (0, 0, 0) }
                var values: [Int] = []
                for y in max(0, y0)..<min(rep.pixelsHigh, y1) {
                    for x in x0..<min(rep.pixelsWide, x1) {
                        let o = y * rep.bytesPerRow + x * 4
                        values.append(Int((0.2126 * Double(base[o]) + 0.7152 * Double(base[o + 1])
                                           + 0.0722 * Double(base[o + 2])).rounded()))
                    }
                }
                var hist: [Int: Int] = [:]
                for v in values { hist[v / 4, default: 0] += 1 }
                let fill = (hist.max { $0.value < $1.value }?.key ?? 0) * 4 + 2
                let inks = values.filter { abs($0 - fill) > 40 }
                let mean = inks.isEmpty ? fill : inks.reduce(0, +) / inks.count
                func rel(_ v: Int) -> Double {
                    let x = Double(v) / 255
                    return x <= 0.03928 ? x / 12.92 : pow((x + 0.055) / 1.055, 2.4)
                }
                let a = rel(mean), b = rel(fill)
                return (fill, inks.count, (max(a, b) + 0.05) / (min(a, b) + 0.05))
            }
            for tag in ["light", "dark"] {
                let name = "settings-general-login-unsupported-720x540-\(tag).png"
                guard let rep = loadFrame(name) else {
                    XCTFail("LOGIN_UNSUPPORTED_FRAME_MISSING：\(tag) 帧不在捕获目录")
                    continue
                }
                // 捕获产物是 top-left（与 /tmp 帧逐像素对过）；不做「上下二选一」，
                // 否则下半张卡里的说明文字会顶替标签、把 1.76 读成 2.8（M1033 第一版）。
                let r = reading(rep, flipped: false)
                emit("LOGIN_UNSUPPORTED_FRAME \(tag) fill=\(r.fill) 墨=\(r.ink)"
                     + " 对比=\(String(format: "%.2f", r.contrast))")
                if r.ink == 0 {
                    emit("LOGIN_UNSUPPORTED_FRAME_NOT_RUN=band-empty：\(tag)")
                    continue
                }
                XCTAssertGreaterThanOrEqual(r.contrast, 2.2,
                                            "\(tag)：不支持登录项时标签对卡片只有 "
                                                + "\(String(format: "%.2f", r.contrast)):1（地板 2.2）"
                                                + " ⇒ 禁用复选框把解释标签一起压没了")
            }
        }

        // R397：整块 pane 空态只有这一句话，必须过 AA 正文线（4.5:1）。
        // 旧 `.secondary` 在同一带实测亮 2.90 / 暗 4.52（暗档刚好贴线）；新 pane 墨档亮/暗都要 ≥4.5。
        // 带子按字墨 bbox 定位：content-empty-750x560 的提示在 x 445..585、y 325..357pt，
        // 上面那颗图标在 y<310pt，不会顶替；带空则写具名 NOT-RUN，不把读不到判成产品淡。
        do {
            func loadEmptyFrame(_ name: String) -> NSBitmapImageRep? {
                let url = directory.appendingPathComponent(name)
                guard let image = NSImage(contentsOf: url) else { return nil }
                return NSBitmapImageRep(data: image.tiffRepresentation ?? Data())
            }
            func readEmptyBand(_ rep: NSBitmapImageRep) -> (fill: Int, ink: Int, contrast: Double) {
                let scale = Double(rep.pixelsWide) / 750.0
                let x0 = Int(445 * scale), x1 = Int(585 * scale)
                let y0 = Int(325 * scale), y1 = Int(357 * scale)
                guard let base = rep.bitmapData else { return (0, 0, 0) }
                var values: [Int] = []
                for y in max(0, y0)..<min(rep.pixelsHigh, y1) {
                    for x in x0..<min(rep.pixelsWide, x1) {
                        let o = y * rep.bytesPerRow + x * 4
                        values.append(Int((0.2126 * Double(base[o]) + 0.7152 * Double(base[o + 1])
                                           + 0.0722 * Double(base[o + 2])).rounded()))
                    }
                }
                var hist: [Int: Int] = [:]
                for v in values { hist[v / 4, default: 0] += 1 }
                let fill = (hist.max { $0.value < $1.value }?.key ?? 0) * 4 + 2
                let inks = values.filter { abs($0 - fill) > 40 }
                let mean = inks.isEmpty ? fill : inks.reduce(0, +) / inks.count
                func rel(_ v: Int) -> Double {
                    let x = Double(v) / 255
                    return x <= 0.03928 ? x / 12.92 : pow((x + 0.055) / 1.055, 2.4)
                }
                let a = rel(mean), b = rel(fill)
                return (fill, inks.count, (max(a, b) + 0.05) / (min(a, b) + 0.05))
            }
            for tag in ["light", "dark"] {
                let name = "content-empty-750x560-\(tag).png"
                guard let rep = loadEmptyFrame(name) else {
                    XCTFail("EMPTY_STATE_HINT_FRAME_MISSING：\(tag) 帧不在捕获目录")
                    continue
                }
                let r = readEmptyBand(rep)
                emit("EMPTY_STATE_HINT \(tag) fill=\(r.fill) 墨=\(r.ink)"
                     + " 对比=\(String(format: "%.2f", r.contrast))")
                if r.ink == 0 {
                    emit("EMPTY_STATE_HINT_NOT_RUN=band-empty：\(tag)")
                    continue
                }
                XCTAssertGreaterThanOrEqual(r.contrast, 4.5,
                                            "\(tag)：空态提示只有 "
                                                + "\(String(format: "%.2f", r.contrast)):1（AA 正文线 4.5）"
                                                + " ⇒ 全屏唯一的信息读不清，不能算「安静」")
            }
        }

        // R398：详情加载态也只有一句话，必须过 AA 正文线（4.5:1）。
        // 旧 `.secondary` 在同一带亮 2.86 / 暗 4.52；新 pane 墨档亮/暗都要 ≥4.5。
        // 带子按字墨 bbox 定位：detail-loading-720x520 的句子在 x 18..115、y 102..120pt；
        // 上面的三根骨架在 y≈75pt，不会顶替；带空写具名 NOT-RUN。
        do {
            func loadLoadingFrame(_ name: String) -> NSBitmapImageRep? {
                let url = directory.appendingPathComponent(name)
                guard let image = NSImage(contentsOf: url) else { return nil }
                return NSBitmapImageRep(data: image.tiffRepresentation ?? Data())
            }
            func readLoadingBand(_ rep: NSBitmapImageRep) -> (fill: Int, ink: Int, contrast: Double) {
                let scale = Double(rep.pixelsWide) / 720.0
                let x0 = Int(18 * scale), x1 = Int(115 * scale)
                let y0 = Int(102 * scale), y1 = Int(120 * scale)
                guard let base = rep.bitmapData else { return (0, 0, 0) }
                var values: [Int] = []
                for y in max(0, y0)..<min(rep.pixelsHigh, y1) {
                    for x in x0..<min(rep.pixelsWide, x1) {
                        let o = y * rep.bytesPerRow + x * 4
                        values.append(Int((0.2126 * Double(base[o]) + 0.7152 * Double(base[o + 1])
                                           + 0.0722 * Double(base[o + 2])).rounded()))
                    }
                }
                var hist: [Int: Int] = [:]
                for v in values { hist[v / 4, default: 0] += 1 }
                let fill = (hist.max { $0.value < $1.value }?.key ?? 0) * 4 + 2
                let inks = values.filter { abs($0 - fill) > 40 }
                let mean = inks.isEmpty ? fill : inks.reduce(0, +) / inks.count
                func rel(_ v: Int) -> Double {
                    let x = Double(v) / 255
                    return x <= 0.03928 ? x / 12.92 : pow((x + 0.055) / 1.055, 2.4)
                }
                let a = rel(mean), b = rel(fill)
                return (fill, inks.count, (max(a, b) + 0.05) / (min(a, b) + 0.05))
            }
            for tag in ["light", "dark"] {
                let name = "detail-loading-720x520-\(tag).png"
                guard let rep = loadLoadingFrame(name) else {
                    XCTFail("DETAIL_LOADING_HINT_FRAME_MISSING：\(tag) 帧不在捕获目录")
                    continue
                }
                let r = readLoadingBand(rep)
                emit("DETAIL_LOADING_HINT \(tag) fill=\(r.fill) 墨=\(r.ink)"
                     + " 对比=\(String(format: "%.2f", r.contrast))")
                if r.ink == 0 {
                    emit("DETAIL_LOADING_HINT_NOT_RUN=band-empty：\(tag)")
                    continue
                }
                XCTAssertGreaterThanOrEqual(r.contrast, 4.5,
                                            "\(tag)：详情加载句只有 "
                                                + "\(String(format: "%.2f", r.contrast)):1（AA 正文线 4.5）"
                                                + " ⇒ 加载态唯一的信息读不清")
            }
        }

        // R402：空输入时「添加」必须是禁用态 —— 与同帧启用态的「移除」比文字亮度：
        // 亮档启用=近黑、禁用=灰（差 ≥20）；暗档启用=近白、禁用=灰（差仍是 ≥20）。
        // 只读文字自己那两条带；带空写具名 NOT-RUN。
        do {
            func loadAddFrame(_ name: String) -> NSBitmapImageRep? {
                let url = directory.appendingPathComponent(name)
                guard let image = NSImage(contentsOf: url) else { return nil }
                return NSBitmapImageRep(data: image.tiffRepresentation ?? Data())
            }
            func bandMean(_ rep: NSBitmapImageRep, x0p: Int, x1p: Int, y0p: Int, y1p: Int) -> (Int, Int) {
                let scale = Double(rep.pixelsWide) / 720.0
                let x0 = Int(Double(x0p) * scale), x1 = Int(Double(x1p) * scale)
                let y0 = Int(Double(y0p) * scale), y1 = Int(Double(y1p) * scale)
                guard let base = rep.bitmapData else { return (0, 0) }
                var values: [Int] = []
                for y in max(0, y0)..<min(rep.pixelsHigh, y1) {
                    for x in x0..<min(rep.pixelsWide, x1) {
                        let o = y * rep.bytesPerRow + x * 4
                        values.append(Int((0.2126 * Double(base[o]) + 0.7152 * Double(base[o + 1])
                                           + 0.0722 * Double(base[o + 2])).rounded()))
                    }
                }
                var hist: [Int: Int] = [:]
                for v in values { hist[v / 4, default: 0] += 1 }
                let fill = (hist.max { $0.value < $1.value }?.key ?? 0) * 4 + 2
                let inks = values.filter { abs($0 - fill) > 40 }
                return (fill, inks.isEmpty ? fill : inks.reduce(0, +) / inks.count)
            }
            for tag in ["light", "dark"] {
                let name = "settings-privacy-excluded-720x1040-\(tag).png"
                guard let rep = loadAddFrame(name) else {
                    XCTFail("ADD_DISABLED_STATE_FRAME_MISSING：\(tag) 帧不在捕获目录")
                    continue
                }
                let add = bandMean(rep, x0p: 455, x1p: 481, y0p: 633, y1p: 645)
                let remove = bandMean(rep, x0p: 662, x1p: 685, y0p: 575, y1p: 590)
                emit("ADD_DISABLED_STATE \(tag) 添加fill=\(add.0) 添加墨=\(add.1)"
                     + " 移除fill=\(remove.0) 移除墨=\(remove.1)"
                     + " 墨差=\(abs(add.1 - remove.1))")
                if add.1 == add.0 || remove.1 == remove.0 {
                    emit("ADD_DISABLED_STATE_NOT_RUN=band-empty：\(tag)")
                    continue
                }
                XCTAssertGreaterThanOrEqual(abs(add.1 - remove.1), 20,
                                            "\(tag)：空输入下「添加」与启用态「移除」的文字亮度只差 "
                                                + "\(abs(add.1 - remove.1)) ⇒ 「添加」不是禁用态")
            }
        }

// R404：详情浮动操作栏的删除按钮必须读到错误红；同一带里先要读到图标（否则不是产品）。
        do {
            for tag in ["light", "dark"] {
                let name = "glass-pill-states-120x232-\(tag).png"
                let url = directory.appendingPathComponent(name)
                guard let image = NSImage(contentsOf: url),
                      let rep = NSBitmapImageRep(data: image.tiffRepresentation ?? Data()),
                      let base = rep.bitmapData else {
                    XCTFail("TRASH_RED_FRAME_MISSING：\(tag) 帧不在捕获目录")
                    continue
                }
                let scale = Double(rep.pixelsWide) / 120.0
                let x0 = Int(45 * scale), x1 = Int(75 * scale)
                let y0 = Int(185 * scale), y1 = Int(215 * scale)
                var red = 0, ink = 0
                for y in max(0, y0)..<min(rep.pixelsHigh, y1) {
                    for x in x0..<min(rep.pixelsWide, x1) {
                        let o = y * rep.bytesPerRow + x * 4
                        let r = Double(base[o]) / 255, g = Double(base[o + 1]) / 255
                        let b = Double(base[o + 2]) / 255
                        if r > g + 0.08 && r > b + 0.08 && r > 0.31 { red += 1 }
                        if (0.2126 * r + 0.7152 * g + 0.0722 * b) < 0.55 { ink += 1 }
                    }
                }
                emit("TRASH_RED \(tag) 红=\(red) 图标墨=\(ink)")
                if ink == 0 {
                    emit("TRASH_RED_NOT_RUN=band-empty：\(tag)")
                    continue
                }
                XCTAssertGreaterThanOrEqual(red, 20,
                                            "\(tag)：详情删除图标只读到 \(red) 颗错误红（要 ≥20）"
                                                + " ⇒ 破坏性动作和普通图标同色")
            }
        }

        // **夹具不许裁自己的内容**（R22 / BACKLOG 32）。名单见 `Fixture.contentMustFit`。
        // 这条是 M76 那支"知道会漏还故意放"的变异终于被抓回去的一次：
        // 以前把 `weights` 的框改小回去**不会有任何测试红**，
        // 于是"帧里少了三行"这件事在账本里躺了九轮。
        //
        // R37 换了参照点之后这条才**真的**在判裁切（以前它判的是色差，见 `bottomInkFraction`）。
        // 读数含义也要说清：底行"有墨"= 那一行有像素不是底色，**被裁的字与压在边上的深色材质
        // 都算**（`content-min` 读 43.4% 就是选中行那块黑药丸贴到了帧底）。所以这条只用于
        // **不该被裁的组件帧**（mustFit 那十张），滚动区帧（settings / content / sidebar）不在其列。
        for item in report where mustFitNames.contains(Self.fixtureName(fromFile: item.name)) {
            XCTAssertLessThan(item.metrics.bottomInkFraction, InkFloor.fixtureBottomInkMaxFraction,
                              "\\(item.name) 的最底一行有 \(String(format: "%.1f", item.metrics.bottomInkFraction * 100))% 的墨"
                              + " ⇒ 这张夹具正在裁自己的内容（被裁的元素一定压在底边上）。"
                              + "把 `Fixture` 的高度抬到放得下，而不是把这条断言关掉 —— "
                              + "被裁掉的那部分从来没有进过帧基线，也就从来没有被审过")
        }
        let judgedFit = mustFitNames.count
        emit("CONTENT_FIT \(judgedFit) fixtures 判了底行墨（\(mustFitNames.sorted().joined(separator: ","))）")

        // **正对照**（R37 / U-60）：一把只在"该红的时候没红"上被检验的尺，等于没被检验。
        // 上面那十张读到的都是 0.0%，所以必须有**一张已知会被裁**的帧读得到墨，
        // 否则"把阈值调到 100000"这种把尺弄瞎的改动不会有任何测试红。
        //
        // 以前这条点名的对照物是 `sidebar-history` —— R36 查出它读到的 100% 是**色差**不是墨
        // （参照点是左上角那一个像素），也就是说这条判据十四年来没有过有效的正对照。
        // 现在换成 `row-clipped-control`：同一颗 `HistoryRowButton`、外框压到 58pt 再 `.clipped()`，
        // 帧上看得见第二行日期被切成半截。本机实测 **10.8%（亮）/ 12.5%（暗）**。
        //
        // 这条**不做成机器前提**（R36 那一版做了）：前提会把"这台机器上一个像素都读不到"
        // 说成"机器不行"，而那恰恰是判据最该红的一次。
        let canaries = report.filter { Self.fixtureName(fromFile: $0.name) == Self.bottomEdgeInkCanary }
        XCTAssertFalse(canaries.isEmpty,
                       "正对照帧 \(Self.bottomEdgeInkCanary) 没被拍到 ⇒ 这把尺今天没被检验")
        for item in canaries {
            XCTAssertGreaterThan(item.metrics.bottomInkFraction, InkFloor.bottomEdgeControlMinFraction,
                                 "正对照帧 \(item.name) 的底行只读到 "
                                 + String(format: "%.1f", item.metrics.bottomInkFraction * 100) + "% 的墨"
                                 + "（线 " + String(format: "%.0f", InkFloor.bottomEdgeControlMinFraction * 100) + "%）"
                                 + " ⇒ 这把尺**瞎了**：它量不到那张**已知被裁**的帧压在底边上的半截字，"
                                 + "上面那 \(judgedFit) 条'没被裁'的绿也就没有意义。"
                                 + "两种可能都要查：尺的参照点又被挪走了，或者那张对照帧不再被裁了"
                                 + "（后者意味着 `clippedRowFrame` 失效，判据同样失去正对照）")
        }
        emit("CONTENT_FIT_CANARY " + canaries.map { "\($0.name)=\(String(format: "%.1f", $0.metrics.bottomInkFraction * 100))%" }
            .joined(separator: " ")
            + "（线 " + String(format: "%.0f", InkFloor.bottomEdgeControlMinFraction * 100) + "%，"
            + "mustFit 那批的上限是 " + String(format: "%.0f", InkFloor.fixtureBottomInkMaxFraction * 100) + "%）")
        // **第二把锁：这把尺读的是产物，不是 raw rep**（R37 立的锁，R38 换成恒等式）。
        //
        // R37 那一版写的是"`content-min` 的底行至少读到 20%"，本机 43.4% 通过，
        // 而 runner 上同一帧读到 **9.3%** ⇒ 红（run 38485603211，被闸门指名）。
        // 那是**用一台机器的读数当另一台机器的地板** —— 正是这一族判据反复栽的那个形状，
        // 而且这次是 R36 刚说完"别这么写"之后我自己写的。
        //
        // 换成恒等式：**判据用的读数 == 从写盘那个文件重算出来的读数**。
        // 它在任何机器上都成立（两边同一台机器算），而谁把来源换回 raw rep，
        // 两边就会差出 13 倍（本机 3.4% vs 43.4%）⇒ 锁照样咬得住，且不再依赖帧长什么样。
        var identityChecked = 0
        var identityDiffering: [String] = []
        for item in report {
            let url = directory.appendingPathComponent(item.name)
            guard let bytes = try? Data(contentsOf: url),
                  let disk = NSBitmapImageRep(data: bytes), let dbase = disk.bitmapData else {
                XCTFail("\(item.name) 读不回字节 ⇒ 这条恒等式没被真的检验（帧没落盘？）")
                continue
            }
            let fromDisk = Self.bottomInkFraction(bytes: dbase, width: disk.pixelsWide,
                                                  height: disk.pixelsHigh, bytesPerRow: disk.bytesPerRow)
            XCTAssertEqual(fromDisk, item.metrics.bottomInkFraction, accuracy: 0.0001,
                           "\(item.name)：判据用的读数 "
                           + String(format: "%.1f", item.metrics.bottomInkFraction * 100)
                           + "% ≠ 从落盘文件重算的 " + String(format: "%.1f", fromDisk * 100)
                           + "% ⇒ 尺读的不是产物（raw rep 里\"没画\"的像素是透明的，会抢走底行中位数）")
            identityChecked += 1
            if abs(fromDisk - item.metrics.bottomInkFraction) > 0.001 { identityDiffering.append(item.name) }
        }
        XCTAssertGreaterThanOrEqual(identityChecked, 100,
                                    "恒等式只对了 \(identityChecked) 张帧 ⇒ 遍历坏了，这条锁等于没上")
        emit("BOTTOM_INK_IDENTITY \(identityChecked) 张帧：判据读数 == 从 PNG 重算的那一份")

        // 新知识（R37 才有）：哪些帧的底行**真的**压着东西。以前这条清单是假的（色差）。
        let edgeCarriers = report.filter { $0.metrics.bottomInkFraction >= InkFloor.fixtureBottomInkMaxFraction }
        emit("BOTTOM_EDGE_INK \(edgeCarriers.count) 张帧的底行读到 ≥"
              + String(format: "%.0f", InkFloor.fixtureBottomInkMaxFraction * 100) + "% 非底色像素："
              + edgeCarriers.map { "\(Self.fixtureName(fromFile: $0.name))=\(String(format: "%.1f", $0.metrics.bottomInkFraction * 100))%" }
                .sorted().joined(separator: " "))


        var exemptedSparse = Set<String>()
        // R168 / BACKLOG 194：这一格循环是"空帧"唯一被处置的地方，所以放行谓词的**活体调用点**
        // 就建在这里 —— 计数器不是装饰：本机 `loop_items` 必须 ≥1（`quickpick-empty` 本机 97.9% 未绘制），
        // 为 0 就说明这条分支在这台机器上根本没有证人，谓词接没接线都看不出来。
        var blankLoopItems = 0
        var blankLoopWithGeometry = 0
        var blankLoopWouldRelease = 0
        for item in report where item.metrics.transparent > 0.95 {
            let name = Self.fixtureName(fromFile: item.name)
            let family = name.components(separatedBy: "-").first ?? ""
            let knownIncapable = (family == "settings" && settingsFamilyIsBlank)
            blankLoopItems += 1
            if let geometry = capturedGeometry[item.name] {
                blankLoopWithGeometry += 1
                let would = Self.shouldRegisterBlankAsMachineGap(
                    family: family, requestedHeightPt: geometry.requested,
                    contentHeightPt: geometry.content, hostHeightPt: geometry.host,
                    drawnBoxPt: item.metrics.drawnBoxPt)
                if would { blankLoopWouldRelease += 1 }
                emit("BLANK_GAP_WOULD_RELEASE \(item.name) release=\(would)"
                     + " requested=\(Int(geometry.requested)) content=\(Int(geometry.content))"
                     + " host=\(Int(geometry.host)) drawnBoxPt=\(Int(item.metrics.drawnBoxPt))"
                     + " drawnBottomPt=\(Int(item.metrics.drawnBottomPt))"
                     + " screenVisibleHeightPt=\(Int(geometry.screen))")
                if would {
                    // R170：这条出口**只认实测到的那一种形状**（画出一条比需求窄、又不等于屏幕可视高的带）。
                    // 名字必须是 `*_NOT_RUN` 全大写，`scripts/ci_capture_gate.py` 才把它算成"这台机器判不了"，
                    // 而不是"被吞掉的红"（闸门自己写的处置只有这两种，见 STEP[15] 的正文）。
                    emit("CAPTURE_BLANK_NOT_RUN \(item.name) 高窗在这台机器上只画出一条窄带："
                         + "drawnBoxPt=\(Int(item.metrics.drawnBoxPt)) < requested=\(Int(geometry.requested))"
                         + " 且 ≠ screenVisibleHeightPt=\(Int(geometry.screen))，而同一份二进制本机 box=1040/blank≈0"
                         + " ⇒ 通道性质，记未运行（BACKLOG 194 / R170），机制未命名")
                    continue
                }
            } else {
                emit("BLANK_GAP_WOULD_RELEASE \(item.name) would=no-reading"
                     + "（这一张没进同源几何读数：它的高 <\(Int(Self.tallFixtureHeightFloor))）")
            }
            if knownIncapable {
                emit("CAPTURE_NOT_RUN \(item.name) \(Int(item.metrics.transparent * 100))% 未绘制"
                      + "，而 settings 族在这台机器上**每一张**都超过 "
                      + String(format: "%.0f", InkFloor.captureFamilyBlankFraction * 100) + "%（族内最低 "
                      + String(format: "%.1f", settingsLowestBlank * 100) + "%）⇒ 记为未运行")
                continue
            }
            if Self.sparseByDesignFixtures.contains(name) {
                // 稀可以，全空不行：这条正对照是这份豁免的承重部分（见名单注释）。
                let drawn = 1 - item.metrics.transparent
                XCTAssertGreaterThan(drawn, Self.sparseByDesignInkFloor,
                                     "\(item.name) 在「天生就稀」的名单里，但它一张都没画出来"
                                     + "（drawn=\(String(format: "%.2f", drawn * 100))%，门槛 "
                                     + "\(String(format: "%.1f", Self.sparseByDesignInkFloor * 100))% 来自本机实测的 "
                                     + "empty 2.1% / runner 5.1%，而\"捕获真的坏了\"是 0.0%）⇒ 这不是稀，这是捕获坏了")
                exemptedSparse.insert(name)
            }
            if item.metrics.transparent > 0.95, !Self.sparseByDesignFixtures.contains(name) {
                XCTFail("\(item.name) 有 \(Int(item.metrics.transparent * 100))% 像素未被绘制，"
                        + "判定为捕获失效，不能作为视觉验收证据"
                        + "（这一族的其他帧画得出来 ⇒ 不是机器不行，是这一张不行）")
            }
        }
        // R168：这一行是谓词**活体调用**的证人。它不判产品，只说明这台机器上
        // 这条分支有没有被真的走过 —— 没有证人的接线与没接线同形（R167 空对账那一族）。
        // 本机与 runner 目前都有证人（本机 `quickpick-empty` 未绘制 ≈97.9%、runner 另有六张高帧），
        // 所以这里**不加地板**：零证人是"这台机器测不到"，不是产品缺陷，写成 skip 名字而不是红。
        if blankLoopItems == 0 {
            emit("BLANK_GAP_WOULD_RELEASE_NOT_RUN 这次捕获一张未绘制帧都没有 ⇒ "
                 + "放行谓词在本机没有活体调用，只有单测那三格（不许据此说出口已验收）")
        } else {
            emit("BLANK_GAP_WOULD_RELEASE_CENSUS loop_items=\(blankLoopItems)"
                 + " with_geometry=\(blankLoopWithGeometry) would_release=\(blankLoopWouldRelease)"
                 + "（with_geometry=0 ⇒ 本机没有高帧空图，放行条件只能靠 CaptureBlankFrameGapTests 那几格（本轮 10 格））")
        }

        // R168 / BACKLOG 194：**分辨轴**。runner 上六张高帧剩下的两种解释（被屏幕裁 / 根本没渲染）
        // 由这一行的 `drawnBoxPt` 分开：`0` ⇒ 没渲染，`≈ screenVisibleHeightPt` ⇒ 被裁，`≈ requested` ⇒ 画满。
        // 依旧**只出读数，不放行、不 skip、不豁免**（R162 的规矩）；本机的高帧是"画满"那一侧的标定样本，
        // 所以两边一起看才知道这把尺在两种形状上都会说话。
        var tallReadings = 0
        for item in report {
            guard let requested = Self.requestedHeightPt(fromFile: item.name),
                  requested >= Self.tallFixtureHeightFloor else { continue }
            tallReadings += 1
            let screenPt = capturedGeometry[item.name]?.screen ?? -1
            emit("CAPTURE_DRAW \(item.name) requested=\(Int(requested))"
                 + " drawnBoxPt=\(Int(item.metrics.drawnBoxPt))"
                 + " drawnBottomPt=\(Int(item.metrics.drawnBottomPt))"
                 + " transparent=\(String(format: "%.1f", item.metrics.transparent * 100))%"
                 + " screenVisibleHeightPt=\(Int(screenPt))")
        }
        emit("CAPTURE_DRAW_CENSUS tall=\(tallReadings)"
             + "（tall=0 ⇒ 这台机器一张高帧都没拍出来，这根轴等于没接，不许读成\"轴已验收\"）")

        // 名单不许攒着 —— 但**判"攒着"的尺必须两台机器都成立**（R38 那条：一台机器的读数
        // 不能当另一台机器的地板）。R63 第一次上 runner 就是被这条自己写的新守卫判红的：
        // `quickpick-empty` 本机未绘制 97.9%、runner 94.9%，而门槛是 95.0% ⇒
        // 同一张帧在一台机器上"需要豁免"、在另一台上"不需要"，
        // 于是"它这次没走豁免分支 ⇒ 名单过期"这句话在 runner 上是**假红**。
        // 换成**同一次运行内的兄弟比较**：空结果态必须明显比 5 行的列表态更空。
        // 这条与 backing scale、与字体渲染的粗细都无关，只与"这一格里有没有内容"有关。
        // 同名帧亮暗各一张 ⇒ 先按夹具名归并，**取更空的那一张**（保守方向：宁可漏判过期，不可假红）。
        // （`Dictionary(uniqueKeysWithValues:)` 在这里会当场 crash —— "Duplicate values for key"，
        // 本机第一遍就是这么死的。归并必须显式写，不能假装一个名字只有一张帧。）
        var drawnByName: [String: Double] = [:]
        for item in report {
            let name = Self.fixtureName(fromFile: item.name)
            let drawn = 1 - item.metrics.transparent
            if let existing = drawnByName[name] {
                drawnByName[name] = min(existing, drawn)
            } else {
                drawnByName[name] = drawn
            }
        }
        let sparseControl = ["quickpick-empty": "quickpick-list"]
        for (entry, control) in sparseControl where Self.sparseByDesignFixtures.contains(entry) {
            guard let entryDrawn = drawnByName[entry], let controlDrawn = drawnByName[control] else {
                emit("SPARSE_EXEMPTION_NOT_RUN \(entry)/\(control) 这台机器没拍出这两张帧 ⇒ 不判")
                continue
            }
            XCTAssertLessThan(entryDrawn, controlDrawn - 0.03,
                              "「天生就稀」的 \(entry) 这次只比 \(control) 少画 \(String(format: "%.1f", (controlDrawn - entryDrawn) * 100))%"
                              + "（\(String(format: "%.1f", entryDrawn * 100))% vs \(String(format: "%.1f", controlDrawn * 100))%）⇒ "
                              + "那一格大概已经有内容了，把 \(entry) 从 `sparseByDesignFixtures` 拿掉，并肉眼审一遍新帧。"
                              + "注意这里**不写未绘制的绝对门槛**：本机 97.9% / runner 94.9% 差 3pt，"
                              + "任何绝对数都会在某台机器上变成假红或免检牌（R38）")
            emit("SPARSE_EXEMPTION_OK \(entry) drawn=\(String(format: "%.1f", entryDrawn * 100))%"
                  + " < \(control) drawn=\(String(format: "%.1f", controlDrawn * 100))% - 3pt")
        }
        emit("SPARSE_EXEMPTION 本次真正走了豁免分支的帧 \(exemptedSparse.sorted())，名单共 \(Self.sparseByDesignFixtures.count) 条"
              + "（走不走由这台机器的未绘制比例决定，**判过期不由它决定**）")

        // **材质盲区要能被数出来**（R18）。
        // 名单外的帧冒出黑带 ⇒ 又多了一处"看着拍到了、其实那块是黑的"，先红再说；
        // 名单里的帧不再冒黑 ⇒ 那一处现在能拍了（或者有人把选中底色改回自绘了），
        // 两种情况都必须**真的去看那张帧**，而不是把名单一行删掉了事。
        let blind = Set(report.map { (Self.fixtureName(fromFile: $0.name), $0.metrics.blackBandPt) }
                            .filter { $0.1 > 0 }
                            .map { $0.0 })
        let extra = blind.subtracting(Self.materialBlindSpotFixtures)
            .subtracting(UICaptureBlackBands.intentional)
        let gone = Self.materialBlindSpotFixtures.subtracting(blind)
        XCTAssert(extra.isEmpty,
                  "这些帧第一次出现纯黑填充带：\(extra.sorted()) ⇒ 有一处材质在离屏下画成了黑，"
                  + "它的视觉状态从此量不到。先确认是谁、为什么黑，再决定是加进名单还是修掉黑的那一层")
        if bandsSeenHere {
            XCTAssert(gone.isEmpty,
                      "这些帧的黑带消失了：\(gone.sorted()) ⇒ 那一处现在能拍了，"
                      + "把 `materialBlindSpotFixtures` 缩掉，并且肉眼审一遍新帧（别只改名单）")
        } else {
            // runner 实测（run 38473962277）：**102 帧里一处黑带都没有**，而名单上有 9 处
            // ⇒ "黑带消失了"那条守卫在 CI 上恒红（并被 report-only 吞掉）。
            // 名单是本机量出来的**事实**，拿到没见过黑带的机器上判"事实变了"不是判据，是错觉。
            // 只关这一个方向：`extra`（第一次冒黑）在上面，任何机器上都照样红 —— 它自己带证据。
            emit("MATERIAL_BLIND_NOT_RUN 这台机器 102 帧里一处黑带都没有，而名单上有 "
                  + "\(Self.materialBlindSpotFixtures.count) 处 ⇒ 「黑带消失了」这一方向无从判起"
                  + "（名单是本机量出来的）；「第一次冒黑」那一方向仍然开着")
        }
        emit("MATERIAL_BLIND_SPOTS \(blind.count) of \(Set(report.map { Self.fixtureName(fromFile: $0.name) }).count) fixtures")
    }

    /// settings 族的一行读数（其余两条前提只看族外，这里给个"没裁到底"的正常值）。
    private static func settingsReading(_ transparent: Double) -> CaptureCapability.Reading {
        CaptureCapability.Reading(fixture: "", family: "settings", transparent: transparent,
                                  blackBandPt: 0, bottomInkFraction: 0.794)
    }

    private static func otherReading(_ family: String, transparent: Double = 0,
                                     band: Double = 0, ink: Double = 0) -> CaptureCapability.Reading {
        CaptureCapability.Reading(fixture: "", family: family, transparent: transparent,
                                  blackBandPt: band, bottomInkFraction: ink)
    }

    // 两台机器各自的**实测**读数。本机那份量自 `/tmp/r36-shots-local`（同一份代码），
    // runner 那份量自 `scripts/tests/fixtures/r36_runner_capture.log`（run 38473962277 逐字日志里的
    // 102 行逐帧表格）。settings 族 18 行**全抄** —— 那条判据是"族内每一张都超过线"，
    // 少一行这张表就钉不住 `allSatisfy`（第一版我只抄了极值，于是"中间有一张画得出来"
    // 这种最该红的情形在表上是空的）。黑带与底行墨那两条判的是 `contains` 与 `max`，
    // 比它们小的行不会改变结论，所以每台只抄决定性的那几行。
    private static let localCapabilityReadings: [CaptureCapability.Reading] =
        [0.696, 0.697, 0.564, 0.564, 0.435, 0.435, 0.208, 0.208, 0.231, 0.231,
         0.285, 0.286, 0.544, 0.544, 0.787, 0.788, 0.704, 0.708].map { settingsReading($0) }
        + [otherReading("sidebar", band: 66, ink: 1.0),        // sidebar-history 亮色版
           otherReading("sidebar", band: 29, ink: 1.0),        // 暗色版
           otherReading("content", band: 43, ink: 0.967),
           otherReading("detail", ink: 1.0),
           otherReading("row", ink: 0.025)]

    private static let runnerCapabilityReadings: [CaptureCapability.Reading] =
        (Array(repeating: 0.922, count: 14) + [0.906, 0.906, 0.959, 0.959]).map { settingsReading($0) }
        + [otherReading("sidebar", ink: 1.0),                  // 暗色版：100.0%
           otherReading("sidebar", ink: 0.0),                  // 亮色版：**0.0%**（本机是 100.0%）
           otherReading("content", band: 0, ink: 0.56),
           otherReading("detail", ink: 1.0),
           otherReading("row")]

    /// 两条前提各自都要有一条"该反过来"的臂，否则这张表只是在抄读数。
    ///
    /// R37 起这里**只剩两条**前提：第三条（"底行墨这把尺活着"）被撤掉了 ——
    /// 它当时是 `bottomInkFraction` 的色差假读数撑着的（U-60），而"这台机器上一帧都读不到墨"
    /// 这件事的正确反应是**红**，不是登记成未运行。现在那件事由 `row-clipped-control`
    /// 这张已知被裁的对照帧无条件判（见 `bottomEdgeInkCanary`），不在这张表里。
    func testCaptureCapabilityPremisesAreMachineVisible() {
        let local = CaptureCapability.measure(Self.localCapabilityReadings)
        XCTAssertFalse(local.settingsFamilyIsBlank,
                       "本机 settings 族最低那张只未绘制 20.8% ⇒ 这一族在本机是画得出来的")
        XCTAssertTrue(local.bandsSeenHere)
        XCTAssertEqual(0.208, local.settingsLowestBlank, accuracy: 0.0001)

        let runner = CaptureCapability.measure(Self.runnerCapabilityReadings)
        XCTAssertTrue(runner.settingsFamilyIsBlank,
                      "runner 上 settings 族 18 张**全部**超过 85%（最低 90.6%）⇒ 那两条"
                      + "「95% 未绘制」的红在这台机器上属于「整族画不出来」，登记成 CAPTURE_NOT_RUN")
        XCTAssertFalse(runner.bandsSeenHere,
                       "runner 上 102 帧一处黑带都没有，而名单上有 9 处 ⇒ 「黑带消失了」那个方向无从判起")
        XCTAssertEqual(0.906, runner.settingsLowestBlank, accuracy: 0.0001)

        // 反例臂①：**只有一张** settings 帧空白，兄弟帧都画得出来（本机那 17 行的真实读数 + 一张 99%）。
        // 这正是那条 XCTFail 存在的理由（"不是机器不行，是这一张不行"），
        // 它绝不可以被族前提放行 —— 这一臂红了说明整个"登记 NOT-RUN"机制被做宽了。
        let oneBadFrame = CaptureCapability.measure(
            Array(Self.localCapabilityReadings.dropLast()) + [Self.settingsReading(0.99)])
        XCTAssertFalse(oneBadFrame.settingsFamilyIsBlank,
                       "族里有画得出来的兄弟帧时，`settingsFamilyIsBlank` 必须为假 ⇒ 那张空白要红，不许登记")

        // 反例臂②：这一族只交出**一张**帧。一张不构成"整族"，不许当机器能力用。
        let singleFrameFamily = CaptureCapability.measure(
            [Self.settingsReading(0.99), Self.otherReading("detail", ink: 1.0)])
        XCTAssertFalse(singleFrameFamily.settingsFamilyIsBlank,
                       "只有一张帧时不许宣告整族空白 —— 那正好是「捕获失效」最像「机器不行」的形状")
        emit("CAPABILITY_TRUTH_TABLE 4 臂（本机 / runner / 单帧空白 / 族只一张）："
              + "local(blank=\(local.settingsFamilyIsBlank),band=\(local.bandsSeenHere)) "
              + "runner(blank=\(runner.settingsFamilyIsBlank),band=\(runner.bandsSeenHere))")
    }

    /// 这把尺自己的真值表（R37 / U-60）：**合成图**，三张，各钉一个方向。
    ///
    /// 这不覆盖管线：它只判"参照点在哪"这一件事。管线级判据在 `testCaptureKeyViews` 里 ——
    /// 那张 `row-clipped-control`（已知被裁，必须读得到墨）与 mustFit 那十条（必须读不到）。
    /// 两边都要有：只有合成图，改坏渲染通道不会红；只有真帧，"参照点是角点"这种错就没人钉。
    func testBottomInkRulerUsesTheRowOwnBackground() throws {
        func bitmap(_ pixels: (Int, Int) -> (Int, Int, Int), width: Int = 100, height: Int = 40)
            throws -> NSBitmapImageRep {
            guard let rep = NSBitmapImageRep(bitmapDataPlanes: nil, pixelsWide: width, pixelsHigh: height,
                                             bitsPerSample: 8, samplesPerPixel: 4, hasAlpha: true,
                                             isPlanar: false, colorSpaceName: .deviceRGB,
                                             bytesPerRow: width * 4, bitsPerPixel: 32),
                  let base = rep.bitmapData else {
                throw XCTSkip("建不出位图（这台机器给不了 bitmapData）")
            }
            for y in 0..<height {
                for x in 0..<width {
                    let rgb = pixels(x, y)
                    let o = y * rep.bytesPerRow + x * 4
                    base[o] = UInt8(rgb.0); base[o + 1] = UInt8(rgb.1)
                    base[o + 2] = UInt8(rgb.2); base[o + 3] = 255
                }
            }
            return rep
        }
        func ink(_ rep: NSBitmapImageRep) -> Double {
            Self.bottomInkFraction(bytes: rep.bitmapData!, width: rep.pixelsWide,
                                   height: rep.pixelsHigh, bytesPerRow: rep.bytesPerRow)
        }
        let grey = (240, 240, 240)
        // ① 整帧都是底色，只有**左上角那一个像素**是白的：这就是 U-60 的形状。
        //    旧实现（参照点 = `bytes[0]`）在这里读 100%（45 > 12 ⇒ 整行数成墨），
        //    正确实现必须读 0 —— 这一张就是"参照点被挪回角点"的绊线。
        let cornerOnly = try bitmap { x, y in (x == 0 && y == 0) ? (255, 255, 255) : grey }
        XCTAssertEqual(ink(cornerOnly), 0.0, accuracy: 0.0001,
                       "底行整行都是底色，只有角点不同 ⇒ 读到墨就说明参照点又变回'左上角那一个像素'了")
        // ② 底行左半边压着半截字 ⇒ 读到 ~50%。
        let halfInk = try bitmap { x, y in (y == 39 && x < 50) ? (20, 20, 20) : grey }
        XCTAssertGreaterThan(ink(halfInk), 0.45, "半行被压住 ⇒ 这把尺必须读到")
        XCTAssertLessThan(ink(halfInk), 0.55, "读到 100% 说明它把整行都数成了墨")
        // ③ 底行**整行**是同一个深色块（全出血）：中位数就是它 ⇒ 读 0。
        //    这是**写下来的边界**，不是缺陷：那种帧要的是另一条判据（"帧底不许是全出血填充"）。
        let fullBleed = try bitmap { _, y in y == 39 ? (20, 20, 20) : grey }
        XCTAssertEqual(ink(fullBleed), 0.0, accuracy: 0.0001,
                       "整行同色时这把尺读 0 —— 已知边界，别把它当'没裁'的证据")
        // 两条线必须是**一对**：mustFit 要求"读不到"，对照帧要求"读得到"。
        // 上限一旦抬到不低于对照帧的下限，同一条读数就能同时满足两条 ⇒ 这两条判据互相取消了。
        XCTAssertLessThan(InkFloor.fixtureBottomInkMaxFraction, InkFloor.bottomEdgeControlMinFraction,
                          "mustFit 的上限（" + String(format: "%.2f", InkFloor.fixtureBottomInkMaxFraction)
                          + "）必须**低于**正对照的下限（"
                          + String(format: "%.2f", InkFloor.bottomEdgeControlMinFraction)
                          + "）⇒ 否则放宽一条就等于同时满足两条，这把尺的正对照与判据互相取消")
        emit("BOTTOM_INK_TRUTH_TABLE 角点=\(String(format: "%.1f", ink(cornerOnly) * 100))%"
              + " 半行=\(String(format: "%.1f", ink(halfInk) * 100))%"
              + " 全出血=\(String(format: "%.1f", ink(fullBleed) * 100))%")
    }

    /// 通用页那颗开关的三态：启用 / 禁用 / 失败回执（R39）。
    ///
    /// 目标里那句"全部状态（空/加载/错误/成功/选中/悬停/按下/聚焦/**禁用**）"，
    /// 禁用是修前那 104 张帧里唯一一帧都没有的一档（本轮之后 108）—— 而它不是没有代码：`SettingsView:325` 有
    /// `.disabled(!isSupported)`、`LoginItemSettings:104` 有那句"当前系统不支持…"、
    /// 模型层三条单测都齐，视图层一个像素都没有。
    ///
    /// 这条判据问三件事，其中两件是**成对的**（都带负对照）：
    /// ① 禁用必须看得见 —— 同一块标签矩形，禁用帧的最深偏离要明显比启用帧淡
    ///    （看不见的禁用等于"能点但没反应"）；
    /// ② 那句回执必须画得出来 —— 它那一块必须是**说明档**、不能是别的控件（标题档），
    ///    并且比**没有回执的那张帧在同一块上多出一行说明档**；
    /// ③ 回执那一行必须还在说明档 —— 交给 `captionInkProbes`（本轮登记两条新探针）。
    ///
    /// ②里那条跨帧对照为什么是"差值"而不是"没回执的帧读 0 墨"，见下面 ③ 处的记录。
    ///
    /// **这一档有机器前提**（R39b 补，起因是 R39 第一版在 CI 上恒红）：三张帧都来自 `SettingsView`，
    /// 而 runner 上这一族是一块平涂（BACKLOG 43）⇒ 那里每条读数天然是 0。判据先问
    /// "这一列在这一台画没画出来"：三张全没画 ⇒ 显式记未运行（`DISABLED_STATE_NOT_RUN`，
    /// 闸门会把它算进 NOT_RUN）；三张全画了 ⇒ 判；**只画出一部分 ⇒ 红**（那不是环境问题）。
    ///
    /// 所有读数都打出来：禁用后"到底有多淡"是要给人判断的，不是要藏在一个 ✓ 后面。
    func testDisabledToggleAndFailureReceiptAreVisible() throws {
        // 两个矩形都是从帧上量的（`testSettingsCaptionRowTierProfileDiagnostic` 这轮把两张新帧
        // 也扫了）：标签带 y=117.5..129.0，它下面那句回执带 y=136.5..145.5。
        let labelRect = CGRect(x: 150, y: 117.5, width: 200, height: 11.5)
        let receiptRect = CGRect(x: 150, y: 136.0, width: 420, height: 10.0)
        let scratch = FileManager.default.temporaryDirectory
            .appendingPathComponent("r39-disabled-\(UUID().uuidString)", isDirectory: true)
        try FileManager.default.createDirectory(at: scratch, withIntermediateDirectories: true)
        defer { try? FileManager.default.removeItem(at: scratch) }

        struct Reading {
            let labelRatio: Double      // 标签的对比度（inkContrast，尾墨 2%）
            let labelInk: Int           // 标签带里"算字"的像素数
            let receiptInk: Int
            let receiptCaption: Int     // 回执带里说明档那一档的像素数
            let receiptTitle: Int       // 同一块里标题档的像素数（负对照要看它）
            let contentInk: Int         // **整条内容列**的算字像素 —— 只回答"这一台拍不拍得出这一页"
        }
        func read(_ name: String, _ appearance: NSAppearance.Name) throws -> Reading? {
            guard let fixture = fixtures(appearance: appearance).first(where: { $0.name == name }) else {
                XCTFail("找不到夹具 \(name) ⇒ 禁用态判据失去对象"); return nil
            }
            let file = scratch.appendingPathComponent("\(name)-\(appearance.rawValue).png")
            _ = try render(fixture, appearance: appearance, to: file)
            // 读**落盘那张图**（R37 的教训：raw rep 里"没画"的像素是透明的，会把中位数抢走）
            guard let bytes = try? Data(contentsOf: file),
                  let rep = NSBitmapImageRep(data: bytes), let base = rep.bitmapData else {
                XCTFail("\(file.lastPathComponent) 读不回字节"); return nil
            }
            let scale = Double(rep.pixelsWide) / 720.0
            func mass(_ rect: CGRect) -> Int {
                Self.textInkMass(bytes: base, width: rep.pixelsWide, height: rep.pixelsHigh,
                                 bytesPerRow: rep.bytesPerRow, rect: rect, scale: scale).pixels
            }
            let profile = Self.rowTierProfile(bytes: base, width: rep.pixelsWide, height: rep.pixelsHigh,
                                              bytesPerRow: rep.bytesPerRow, rect: receiptRect, scale: scale)
            return Reading(
                labelRatio: Self.inkContrast(bytes: base, width: rep.pixelsWide, height: rep.pixelsHigh,
                                             bytesPerRow: rep.bytesPerRow, rect: labelRect, scale: scale).ratio,
                labelInk: mass(labelRect),
                receiptInk: mass(receiptRect),
                receiptCaption: profile.reduce(0) { $0 + $1.caption },
                receiptTitle: profile.reduce(0) { $0 + $1.title },
                contentInk: mass(CGRect(x: 150, y: 20, width: 560, height: 500)))
        }

        var judged = 0
        var notRun = 0
        for appearance in [NSAppearance.Name.aqua, .darkAqua] {
            let tag = appearance == .darkAqua ? "dark" : "light"
            guard let plain = try read("settings-general", appearance),
                  let unsupported = try read("settings-general-login-unsupported", appearance),
                  let failed = try read("settings-general-login-failed", appearance) else {
                emit("DISABLED_STATE_NOT_RUN \(tag) 三张帧没齐 ⇒ 这一档在这一台无从判起")
                notRun += 1
                continue
            }
            // **机器前提（R39b，CI 第一次跑就红给它看了）**：runner 上 `SettingsView` 的内容列
            // 是一块平涂（BACKLOG 43；本轮 CI 的 `ROWTIER settings-general-login-* dark：有字行 0 行`
            // 就是同一件事），于是这里每一条读数都是 0 / 对比度 1.00 —— 那不是"禁用没淡"，
            // 是"这一台拍不出这一页"。判据必须先问这一列画没画，再问画出来的东西对不对；
            // 反过来把地板降到能容纳 0 读数，就等于把判据删掉（U-61 / U-62 同一族，第三次犯）。
            //
            // 三条帧问的是**同一个问题**，所以这里判的是**一致性**而不是量级：
            // 0 张有墨 ⇒ 这一台拍不出这一页 ⇒ 如实记未运行；3 张有墨 ⇒ 判；
            // **1 或 2 张** ⇒ 同一列不可能只画出一部分，那是某一帧坏了或框贴错了 —— 照旧红。
            let drawable = Self.settingsDrawability(
                [plain.contentInk, unsupported.contentInk, failed.contentInk])
            switch drawable {
            case .partial(let drawn):
                return XCTFail("\(tag)：三张帧的同一条内容列里只有 \(drawn) 张读到墨"
                               + "（\(plain.contentInk)/\(unsupported.contentInk)/\(failed.contentInk)）"
                               + " ⇒ 这不是「这一台画不出这一页」（那要么三张全有、要么三张全无），"
                               + "而是其中某一帧坏了或者我的框贴错了。先去看那一张帧")
            case .noneDrawn:
                emit("DISABLED_STATE_NOT_RUN \(tag) 内容列读到 "
                      + "\(plain.contentInk)/\(unsupported.contentInk)/\(failed.contentInk) 个算字像素"
                      + " ⇒ 这一台拍不出设置页（BACKLOG 43），这一档记未运行，不算通过")
                notRun += 1
                continue
            case .allDrawn:
                break
            }
            judged += 1
            // ① **禁用必须看得见**：同一块标签矩形，禁用帧的对比度要明显比启用帧低。
            //    为什么判对比度而不是"最深偏离"：暗档禁用后的标签淡到连 `isTextInk` 那道门都过不去
            //    （本轮实测：暗档那一行的 profile 是空的）—— 那种情况下"最深偏离"根本没有值可比。
            XCTAssertLessThanOrEqual(unsupported.labelRatio, plain.labelRatio * 0.70,
                "\(tag)：禁用帧标签对比度 \(String(format: "%.2f", unsupported.labelRatio))，"
                    + "启用帧 \(String(format: "%.2f", plain.labelRatio)) ⇒ 淡得不够。"
                    + "看不出禁用的开关，用户会一直点它")
            XCTAssertGreaterThan(unsupported.labelRatio, 1.20,
                "\(tag)：禁用帧标签对比度只有 \(String(format: "%.2f", unsupported.labelRatio)) ⇒ 淡到与背景同色。"
                    + "禁用不等于消失（HIG：被禁的东西仍要读得出是什么东西）—— "
                    + "真到这一步的处置不是把线抬高，而是**别用 `.disabled` 表达这个状态**，"
                    + "让那句回执去说明（回执本身是说明档，读数在下面一行）")
            // ② **回执必须画得出来**（它藏在 `if let message` 后面，模型层三条单测全绿也救不了视图不显示）
            for (name, reading) in [("settings-general-login-unsupported", unsupported),
                                    ("settings-general-login-failed", failed)] {
                XCTAssertGreaterThanOrEqual(reading.receiptInk, 500,
                    "\(tag)：\(name) 的回执带只读到 \(reading.receiptInk) 个算字的像素 ⇒ 那句话没画出来")
                XCTAssertEqual(reading.receiptTitle, 0,
                    "\(tag)：\(name) 的回执带里读到 \(reading.receiptTitle) 个**标题档**像素 ⇒ "
                        + "那块矩形上压着的不是回执，是别的控件（框放错，或者布局把下一行顶上来了）")
            }
            // ③ **负对照，相对版**：同一块矩形，有回执的帧要比没有回执的帧多出整整一行说明档。
            //    第一版这里写的是"没有回执的那张帧读 0 墨"，本机 382 / 471 个像素直接把它推翻了：
            //    通用页在插入那句回执时会把**下面一颗开关的标签**顶到别的位置，而没插入时那颗标签
            //    正好压在 y=136 这一块上（同一块里还读到 971 / 1064 个**标题档**像素 ⇒ 那里住的是
            //    标题，不是说明）。所以布局会随内容移动的矩形上，"跨帧比有没有墨"是错的问法，
            //    正确的问法是"跨比**多出来的墨**"：回执没画 ⇒ 差值 0 ⇒ 红；
            //    回执画了但透明/颜色与背景同 ⇒ 差值是负的 ⇒ 红。
            for (name, reading) in [("settings-general-login-unsupported", unsupported),
                                    ("settings-general-login-failed", failed)] {
                XCTAssertGreaterThan(reading.receiptCaption, plain.receiptCaption + 500,
                    "\(tag)：\(name) 的回执带说明档 \(reading.receiptCaption) 个像素，"
                        + "没回执那张帧同一块 \(plain.receiptCaption) 个 ⇒ 只多出 "
                        + "\(reading.receiptCaption - plain.receiptCaption) 个（要求 >500）。"
                        + "这一行回执要么没画，要么淡到不成字")
            }
            emit("DISABLED_STATE \(tag)：标签对比度 启用=\(String(format: "%.2f", plain.labelRatio)) "
                  + "禁用=\(String(format: "%.2f", unsupported.labelRatio))（淡到 "
                  + String(format: "%.2f", unsupported.labelRatio / max(plain.labelRatio, 0.01)) + " 倍）"
                  + " 标签算字像素 启用=\(plain.labelInk) 禁用=\(unsupported.labelInk)"
                  + "；回执带 墨(不支持/失败)=\(unsupported.receiptInk)/\(failed.receiptInk) "
                  + "说明档=\(unsupported.receiptCaption)/\(failed.receiptCaption) "
                  + "差值(+\(unsupported.receiptCaption - plain.receiptCaption)"
                  + "/+\(failed.receiptCaption - plain.receiptCaption)) "
                  + "无回执那帧同块(说明档/标题档)=\(plain.receiptCaption)/\(plain.receiptTitle)")
        }
        // 两档外观必须**各有一个交代**：判成了，或者显式记为未运行。
        // 这条不要求"必须判成"—— 那正是 R39 第一版在 CI 上恒红的原因（runner 拍不出设置页）。
        // 但它也不允许"悄悄少判一档"：`judged + notRun != 2` 只有两种来路（读不到帧、或者我改坏了循环），
        // 两种都该红。未运行的条数由 `DISABLED_STATE_NOT_RUN` 打进日志，CI 闸门把它算进 NOT_RUN（不省略成"通过"）。
        XCTAssertEqual(judged + notRun, 2,
                       "两档外观应该有 2 个交代（判成或未运行），现在 judged=\(judged) notRun=\(notRun) "
                       + "⇒ 这一档在这一台既没判成、也没被如实记账")
        emit("DISABLED_STATE_COVERAGE 判成 \(judged) 档、未运行 \(notRun) 档（共 2 档）")
    }

    /// 机器前提这把"折成决定"的尺本身要有真值表（R39b）。
    ///
    /// 为什么单独一条：真实环境里这一族**要么三张全有墨（本机）要么三张全无（runner）**，
    /// 中间那一格（1 或 2 张）在两台机器上都走不到 —— 而它正是"环境问题"与"某一帧坏了"的分界。
    /// 走不到的分支不打桩测一次，就等于没有那条分支（M183 把 `.partial` 折成 `.noneDrawn`
    /// 就是这一格的红）。
    func testSettingsDrawabilityTruthTable() {
        XCTAssertEqual(Self.settingsDrawability([900, 1200, 700]), .allDrawn,
                       "三张都有墨必须判 —— 这一格判不成，机器前提就成了免检牌")
        XCTAssertEqual(Self.settingsDrawability([0, 0, 0]), .noneDrawn,
                       "三张都没墨必须记未运行 —— 这是 runner 的真实形状")
        XCTAssertEqual(Self.settingsDrawability([0, 1200, 700]), .partial(2),
                       "只画出一部分不是环境问题：同一列要么全有要么全无，这一格必须红")
        XCTAssertEqual(Self.settingsDrawability([900, 0, 0]), .partial(1),
                       "只有一张有墨同样必须红（那是夹具坏了，不是机器不行）")
        emit("SETTINGS_DRAWABILITY_TRUTH_TABLE 全有=判 / 全无=未运行 / 1|2 张=红（四格全过）")
    }

    /// 夹具图片的字节**不能**随系统外观变。
    ///
    /// 这条是给"帧基线能不能当证据"加的：本轮实测到开发机开着自动切换外观，
    /// 傍晚从浅切到深之后，**同一份代码两次捕获有 18 帧自己变了**
    /// （`row-image` / `detail-1-image` / `sidebar-*` 的图片区域，最大通道差 17）。
    /// 那种漂移会让"改了界面要更新基线"这条硬门变成看天吃饭，
    /// 所以把外观钉死在 `makeStoredImage` 里，并由这条用例钉住它没被改回去。
    func testFixtureImageBytesDoNotDependOnAmbientAppearance() throws {
        // `NSApp` 是隐式解包的可选值：测试进程里没人创建过共享应用，直接读它就是崩溃
        // （本轮第一次跑就是这么挂的）。`render()` 里那行 `_ = NSApplication.shared` 是同一个原因。
        _ = NSApplication.shared
        let size = NSSize(width: 24, height: 16)
        // 阳性对照：先证明"不钉外观就会漂"这件事本身是真的。
        let rawLight = try fillUnderAmbient(.labelColor, appearance: .aqua, size: size)
        let rawDark = try fillUnderAmbient(.labelColor, appearance: .darkAqua, size: size)
        XCTAssertFalse(rawLight.isEmpty)
        XCTAssertNotEqual(rawLight, rawDark,
                          "前提变了：动态色不再随外观解析，这条守卫就没有判别力了（要改写而不是删掉）")

        let previous = NSApp.appearance
        defer { NSApp.appearance = previous }
        NSApp.appearance = NSAppearance(named: .aqua)
        let light = try XCTUnwrap(makeStoredImage(color: .systemTeal, size: size).pngData())
        NSApp.appearance = NSAppearance(named: .darkAqua)
        let dark = try XCTUnwrap(makeStoredImage(color: .systemTeal, size: size).pngData())
        XCTAssertEqual(light, dark,
                       "同一份夹具代码在两种外观下生成了不同字节 ⇒ 帧基线会随系统外观漂移")
    }

    /// 在**给定外观**下裸填充一次（不经过 `makeStoredImage` 的钉死），用来证明漂移的机制。
    private func fillUnderAmbient(_ color: NSColor, appearance name: NSAppearance.Name, size: NSSize) throws -> Data {
        let image = NSImage(size: size)
        NSAppearance(named: name)!.performAsCurrentDrawingAppearance {
            image.lockFocus()
            color.setFill()
            NSRect(origin: .zero, size: size).fill()
            image.unlockFocus()
        }
        return image.tiffRepresentation ?? Data()
    }

    // MARK: - 夹具（用闭包延迟求值：否则四个 detail 拍到的都是"最后一次选中"）

    struct Fixture {
        let name: String
        let size: NSSize
        /// 布局完成之后、按快门之前跑一次。给"内容要等一次异步刷新才落定"的视图用：
        /// 不 settle 就只能拍到刷新途中的那一帧，而那一帧是不是最终态取决于机器快慢。
        let settle: (() -> Void)?
        /// R145 / BACKLOG 177：布局与 caret 静默**之后**、按快门之前，对真实窗口做一次产品入口操作。
        ///
        /// 为什么不能复用 `settle`：捕获路径在 `settle` 之后还会 `makeFirstResponder(nil)` 清闪烁光标，
        /// 而录制态靠第一响应者活着（`HotKeyRecorderButton.resignFirstResponder` 会 `cancelRecording`）
        /// ⇒ 先点再清 caret，等于自己把刚点出来的状态取消掉（本轮实测撞到的）。
        /// 为什么不是"在 build 里造一个已经在录制的视图"：那拍的是我搭的样子，不是产品的入口
        /// （AGENTS.md 第 1 条：验收必须从产品入口进入）。
        let interact: (@MainActor (NSWindow) -> Void)?
        let build: () -> AnyView
        /// 按快门之前临时写进 `UserDefaults.standard` 的一个键，拍完立刻还原。
        ///
        /// 为什么要有这一层：`SettingsView` 里那几处 `@AppStorage` 状态（用户自己加的排除名单）
        /// **没有别的注入点** —— 它不是参数、不是 store 字段，而离屏窗口又不建无障碍树，
        /// 没法"点一下添加"。没有这一层，那一行与它右边那颗「移除」就永远进不了帧基线
        /// （R13 改它样式时正是"源码已接、产物未量"）。
        /// 还原是必须的：不还原的话同一次运行里 `settings-privacy` 那张也会被带脏。
        let seed: (key: String, value: String)?
        /// R18 加通路、R19 才拍到位：AppKit 表面的夹具入口返回**产品自己的窗口**。
        /// 返回 `NSView` 的第一版失败得很安静 —— 把浮层的 contentView 摘进另一个窗口之后，
        /// `NSStackView` 塌成 24×49、滚动视图 0×0，帧仍然"拍得出来"，只是拍的是空壳。
        ///
        /// 为什么要有这一条：快速选择浮层是 `QuickPickController` 自建的 `NSPanel` + `NSTableView`，
        /// 而 96 张基线**一张都没有它** —— 于是关于这个浮层的每一句观感结论只能停在"胶片 + 人眼"。
        /// 更要紧的是：`FRAME_BASELINE_CHANGED=0` 在这种表面上**不是**"没有视觉变化"，
        /// 而是"这里根本没有帧"。这两件事必须能分开（账本 BACKLOG 30 / U-39 / U-41）。
        let appKit: (@MainActor () -> NSWindow?)?
        /// 这张夹具的**内容必须整块放得下**（R22 / BACKLOG 32）。
        ///
        /// 为什么现在才立：这条守卫的代价是"会误报滚动区"，所以必须点名。
        /// 而它要抓的事已经发生过两次，两次都是**靠人眼**：
        /// R18 —— `weights` 用 560 高的框套 850 高的内容，标题与「恢复默认」按钮
        /// 九轮以来从来不在帧里；R20 —— `search-field` 320×96 一直在裁自己的下半条。
        /// 两次的共同点是**改小回去不会有任何测试红**（变异 M76 当年就是 ESCAPED）。
        ///
        /// 判法：帧的**最底一行**不该有墨（被裁的元素一定压在底边上）。
        /// 列表 / 滚动区那批天生会被裁 ⇒ 它们**不进**这个名单，
        /// 否则就是把"滚动视图的正常行为"报成缺陷。
        let contentMustFit: Bool

        init(_ name: String, _ size: NSSize, settle: (() -> Void)? = nil,
             interact: (@MainActor (NSWindow) -> Void)? = nil,
             seed: (key: String, value: String)? = nil,
             contentMustFit: Bool = false,
             appKit: (@MainActor () -> NSWindow?)? = nil, _ build: @escaping () -> AnyView) {
            self.name = name
            self.size = size
            self.settle = settle
            self.interact = interact
            self.seed = seed
            self.contentMustFit = contentMustFit
            self.appKit = appKit
            self.build = build
        }

        /// 给一个已经建好的夹具补上 AppKit 入口（其余字段原样带走）。
        /// 存在的理由：`appKit` 与 `build` 是同一个结构体里的两个入口，
        /// 而 Swift 的成员式初始化器没有"只改一个字段"的写法 ——
        /// 没有这个 helper，加一条浮层帧就要把整条夹具重抄一遍，
        /// 而重抄的那份迟早和原件漂开。
        func withAppKit(_ buildAppKit: @escaping @MainActor () -> NSWindow?) -> Fixture {
            Fixture(name, size, settle: settle, seed: seed, contentMustFit: contentMustFit,
                    appKit: buildAppKit, build)
        }

        /// 给一张已建好的夹具补上「按快门前的一次产品入口操作」（其余字段原样带走）。
        /// 为什么要 helper 而不是直接写参数：`build` 是**无标签**的最后一个参数，
        /// 前面一旦出现带标签的 `interact:`，尾随闭包就不再映射到它（编译器报 `expected ')'`）。
        func withInteract(_ action: @escaping @MainActor (NSWindow) -> Void) -> Fixture {
            Fixture(name, size, settle: settle, interact: action, seed: seed,
                    contentMustFit: contentMustFit, appKit: appKit, build)
        }
    }

    private func fixtures(appearance: NSAppearance.Name) -> [Fixture] {
        let store = makePopulatedStore()
        let empty = HistoryStore(
            clipboardWriter: TestClipboardWriter(),
            persistence: RecordingHistoryPersistence(),
            retentionPolicy: HistoryRetentionPolicy(maxEntries: 50, maxAgeDays: nil)
        )
        let searching = makePopulatedStore()
        searching.perform(.updateSearch("不存在的词"))

        var results: [Fixture] = [
            Fixture("content-with-history", NSSize(width: 750, height: 560)) { AnyView(ContentView(historyStore: store)) },
            Fixture("content-min", NSSize(width: 600, height: 440)) { AnyView(ContentView(historyStore: store)) },
            Fixture("content-wide", NSSize(width: 1100, height: 800)) { AnyView(ContentView(historyStore: store)) },
            Fixture("content-empty", NSSize(width: 750, height: 560)) { AnyView(ContentView(historyStore: empty)) },
            Fixture("content-no-results", NSSize(width: 750, height: 560)) { AnyView(ContentView(historyStore: searching)) },
        ]

        // 菜单栏面板的内容层。以前这里一直标 NOT-RUN（D-019：整块 NSMenu 离屏画不出材质表面，
        // 97.7% 像素未绘制，会被本文件第 2 条规矩拦下 —— 那层判断本身没错）。
        // 但真正上线的是 macOS 13+ 的 SwiftUI `MenuBarExtra`，它的内容就是一个普通 View
        // （`MenuBarRecommendationsView`），可以和其他夹具一样离屏渲染：字号、层级、间距、
        // 空态文案、脱敏标签都拍得到；**拍不到的仍然是系统菜单的材质与圆角**（那层由系统画）。
        // 可复现性：reason 文案会带"当前在<App 名>"，取自 `effectiveFrontmostApp()`；
        // 测试进程从不 `startMonitoring()` ⇒ `lastFrontmostBundleID` 恒为 nil ⇒ 走"第一条记录的来源 App"，
        // 由夹具固定（Safari），所以这些帧仍可做逐字节比对。
        if #available(macOS 13, *) {
            let recommendationStore = makePopulatedStore()
            recommendationStore.refreshPredictions()
            waitUntil("菜单栏面板需要候选") { !recommendationStore.predictionSuggestionEntries.isEmpty }
            results.append(Fixture("menubar-recommendations", NSSize(width: 320, height: 320), settle: {
                self.waitUntil("推荐刷新要收尾") { !recommendationStore.isRefreshingPredictions }
            }) {
                AnyView(self.menuBarFrame(MenuBarRecommendationsView(
                    historyStore: recommendationStore,
                    appDelegate: AppDelegate(historyStore: recommendationStore)
                )))
            })

            // 刷新途中的那一帧：视图 `onAppear` 自己会发起一次刷新，所以不 settle，
            // 并在快门前一瞬**断言它仍在途中** —— 否则这帧的名字就在说谎，
            // 而"名字说正在算、画面上却写着暂无推荐"这种错用肉眼比对很难发现。
            let refreshingStore = HistoryStore(
                clipboardWriter: TestClipboardWriter(),
                persistence: RecordingHistoryPersistence(),
                retentionPolicy: HistoryRetentionPolicy(maxEntries: 50, maxAgeDays: nil)
            )
            results.append(Fixture("menubar-refreshing", NSSize(width: 320, height: 120), settle: {
                XCTAssertTrue(refreshingStore.isRefreshingPredictions,
                              "这一帧叫「正在整理推荐」，拍的时候刷新必须仍在途中")
            }) {
                AnyView(self.menuBarFrame(MenuBarRecommendationsView(
                    historyStore: refreshingStore,
                    appDelegate: AppDelegate(historyStore: refreshingStore)
                )))
            })

